window.MXZ_SIMULATOR_FILES = {
 "mxz_row.py": "\"\"\"The simulator's MXZ row: MXZ Coordinator's own decisions over the invented house's heads.\n\nEvery decision, every order of steps and every wakeup here comes from a product function in\n``custom_components/mxz_coordinator`` that imports no Home Assistant (``tools/import_bounds.py``\n``STDLIB_ONLY``): ``planner``, ``timing``, ``sim_timing``, ``grid``, ``head_writes``,\n``fan_latch``, ``resume`` and ``logic``. This module only maps the page's controls to those\nfunctions' inputs and performs the steps they return, each with the call its docstring names.\nIt follows the per-event list in planner1118d's WRITE-SUMMARY.md, with the hold-end wakeup armed\nat a start (``MXZCoordinator.async_setup``). Where a step belongs to a feature the invented house\ndoes not have (a door/window pause, Dry, a floor, a hands-off room, a head going out of sight),\nit raises ``NotModeled`` instead of doing something else.\n\nThe invented heads are the verification instance's (``verification/instance/invented_house``):\na °F range head on the ``invented_house`` platform, which takes a mode change and its setpoints\nas two calls. ``InventedHeads.shown`` renders a head the way Home Assistant shows that entity.\n\nWhat this does not model, as planner1118d's review 3 lists it: deliveries run head by head in\nthe order they were queued, inside their compute (Home Assistant interleaves heads at each\nawait); a delivery a newer plan supersedes; the shared-mode select. Timing follows\n``sim_timing``, a model of Home Assistant 2025.11 and later.\n\nEvery room, head and number here is invented. Nothing is a measurement of real equipment.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections.abc import Hashable, Iterator, Mapping, Sequence\nfrom dataclasses import dataclass, field\nfrom datetime import timedelta\nfrom typing import Any\n\nfrom invented_house import devices as dv\nfrom invented_house import model\n\nfrom custom_components.mxz_coordinator import fan_latch as fl\nfrom custom_components.mxz_coordinator import grid as gr\nfrom custom_components.mxz_coordinator import head_writes as hw\nfrom custom_components.mxz_coordinator import planner as pl\nfrom custom_components.mxz_coordinator import resume as rs\nfrom custom_components.mxz_coordinator import sim_timing as st\nfrom custom_components.mxz_coordinator import timing as tm\nfrom custom_components.mxz_coordinator.const import (\n    ACTION_VOTE_HOLD,\n    ACTION_VOTE_SETTLE,\n    DEFAULT_ACCEPT_HEAD_CHANGES,\n    DEFAULT_COIL_DRY_MINUTES,\n    DEFAULT_COMFORT_STALE_HOURS,\n    DEFAULT_DEMAND_THRESHOLD,\n    DEFAULT_ENGAGE_DEADBAND,\n    DEFAULT_FAN_BOOST_ENABLE,\n    DEFAULT_FAN_BOOST_MAX,\n    DEFAULT_IDLE_ACTION,\n    DEFAULT_LOST_VOTE_TTL,\n    DEFAULT_MODE_HYSTERESIS,\n    FAN_LADDER,\n    HEAD_WRITES_REMEMBERED,\n    KEY_COOL_LOCKOUT,\n    KEY_COORDINATOR_ENABLE,\n    KEY_ECO_IDLE,\n    KEY_HEAT_LOCKOUT,\n    MODE_OFF,\n    unit_profile,\n    zone_slug,\n)\nfrom custom_components.mxz_coordinator.logic import (\n    HeadSight,\n    HeadWriteMemory,\n    comfort_priority,\n    sensor_health,\n)\nfrom custom_components.mxz_coordinator.plan import Plan, RoomPlan\n\nFAHRENHEIT = \"°F\"\nPLATFORM = \"invented_house\"\n# Home Assistant's climate features of an invented head: a range, a fan, on and off.\nRANGE_HEAD_FEATURES = 2 | 8 | 128 | 256\nCOMFORT_DOMAIN = \"input_boolean\"\n\n\nclass NotModeled(RuntimeError):\n    \"\"\"A product step for a feature the invented house does not have.\"\"\"\n\n\nclass OutOfRange(ValueError):\n    \"\"\"A value Home Assistant's number entity refuses (``out_of_range``).\"\"\"\n\n\ndef climate_id(key: str) -> str:\n    return f\"climate.{key}_head\"\n\n\ndef sensor_id(key: str) -> str:\n    return f\"sensor.{key}_temperature\"\n\n\ndef comfort_id(key: str) -> str:\n    return f\"{COMFORT_DOMAIN}.{key}_comfort\"\n\n\n@dataclass(frozen=True)\nclass Settings:\n    \"\"\"The entry's settings: MXZ's defaults for a °F install, as a new entry has them.\"\"\"\n\n    hold: float = float(DEFAULT_MODE_HYSTERESIS)\n    idle_action: str = DEFAULT_IDLE_ACTION\n    coil_dry_seconds: float = 60.0 * DEFAULT_COIL_DRY_MINUTES\n    fan_boost: bool = DEFAULT_FAN_BOOST_ENABLE\n    accept_head_changes: bool = DEFAULT_ACCEPT_HEAD_CHANGES\n    demand_threshold: float = DEFAULT_DEMAND_THRESHOLD\n    drift: float = DEFAULT_ENGAGE_DEADBAND\n    lost_vote_ttl: float = 60.0 * DEFAULT_LOST_VOTE_TTL\n    comfort_stale_after: float | None = 3600.0 * DEFAULT_COMFORT_STALE_HOURS\n\n    def __post_init__(self) -> None:\n        profile = unit_profile(False)\n        defaults = profile[\"defaults\"]\n        object.__setattr__(self, \"_profile\", profile)\n        object.__setattr__(self, \"clamp_min\", float(defaults[\"clamp_min\"]))\n        object.__setattr__(self, \"clamp_max\", float(defaults[\"clamp_max\"]))\n\n    @property\n    def profile(self) -> dict[str, Any]:\n        return self._profile  # type: ignore[attr-defined,no-any-return]\n\n    @property\n    def limits(self) -> pl.CallLimits:\n        defaults = self.profile[\"defaults\"]\n        return pl.CallLimits(\n            eco=False,\n            eco_cool_max=defaults[\"eco_cool_max\"],\n            eco_heat_min=defaults[\"eco_heat_min\"],\n            heat_lockout=False,\n            heat_lockout_floor=defaults[\"heat_lockout_floor\"],\n            cool_lockout=False,\n            cool_lockout_ceiling=defaults[\"cool_lockout_ceiling\"],\n        )\n\n    @property\n    def setpoints(self) -> pl.SetpointSettings:\n        profile = self.profile\n        return pl.SetpointSettings(\n            clamp_min=self.clamp_min,  # type: ignore[attr-defined]\n            clamp_max=self.clamp_max,  # type: ignore[attr-defined]\n            band=profile[\"setpoint_band\"],\n            step=profile[\"target_step\"],\n            eco_cool=profile[\"eco_cool\"],\n            eco_heat=profile[\"eco_heat\"],\n        )\n\n    @property\n    def ceiling(self) -> int:\n        return FAN_LADDER.index(DEFAULT_FAN_BOOST_MAX)\n\n\nclass InventedHeads:\n    \"\"\"The invented heads and rooms (``invented_house``), and what each head shows.\n\n    ``devices`` is the shared physical state: each head's mode, setpoints and fan, and each\n    room's temperature. ``modelled`` is whether the demo model runs (then a head shows what it\n    is doing, as ``invented_house.climate.InventedHead`` does).\n    \"\"\"\n\n    def __init__(self, house: Mapping[str, Any], devices: dv.Devices, *, modelled: bool) -> None:\n        self.house = house\n        self.devices = devices\n        self.modelled = modelled\n        self.keys: tuple[str, ...] = tuple(room[\"key\"] for room in house[\"rooms\"])\n        spec = house[\"head\"]\n        self._capabilities = {\n            \"hvac_modes\": list(spec[\"hvac_modes\"]),\n            \"min_temp\": round(spec[\"min_temp\"]),\n            \"max_temp\": round(spec[\"max_temp\"]),\n            \"fan_modes\": list(spec[\"fan_modes\"]),\n        }\n        self.native = (float(spec[\"min_temp\"]), float(spec[\"max_temp\"]), FAHRENHEIT)\n\n    def changed(self) -> None:\n        \"\"\"A head or room changed: with the model on, rule 1 picks the outdoor direction again\n        (``invented_house.Bench.changed``).\"\"\"\n        if self.modelled:\n            self.devices.outdoor = model.direction(self.devices, self.devices.outdoor)\n\n    def doing(self, key: str) -> str:\n        return model.action(self.devices.heads[key], self.devices.rooms[key], self.devices.outdoor)\n\n    def shown(self, key: str) -> tuple[str, dict[str, Any]]:\n        \"\"\"The head's state and attributes as Home Assistant shows the invented head.\n\n        Temperatures show at whole degrees (a °F system's precision), as Home Assistant's\n        climate entity renders them.\n        \"\"\"\n        head = self.devices.heads[key]\n        state = head.hvac_mode if head.available else \"unavailable\"\n        if not head.available:\n            return state, {}\n        attributes: dict[str, Any] = {\n            **self._capabilities,\n            \"current_temperature\": None,\n            \"target_temp_high\": _whole(head.target_temp_high),\n            \"target_temp_low\": _whole(head.target_temp_low),\n            \"fan_mode\": head.fan_mode,\n        }\n        if self.modelled:\n            attributes[\"hvac_action\"] = _HVAC_ACTION[self.doing(key)]\n            attributes[\"standby\"] = self.doing(key) == \"standby\"\n        attributes[\"supported_features\"] = RANGE_HEAD_FEATURES\n        return state, attributes\n\n    def reading(self, key: str) -> float:\n        \"\"\"What the room's sensor reports (``invented_house.devices.reading``).\"\"\"\n        return dv.reading(self.devices.rooms[key].temperature)\n\n    def call(self, key: str, service: str, data: Mapping[str, Any]) -> None:\n        \"\"\"A climate service call to the head, as ``InventedHead`` takes it.\"\"\"\n        head = self.devices.heads[key]\n        if service == \"set_hvac_mode\":\n            head.hvac_mode = str(data[\"hvac_mode\"])\n        elif service == \"set_fan_mode\":\n            head.fan_mode = str(data[\"fan_mode\"])\n        elif service == \"set_temperature\":\n            if (mode := data.get(\"hvac_mode\")) is not None:\n                head.hvac_mode = str(mode)\n            if (low := data.get(\"target_temp_low\")) is not None:\n                head.target_temp_low = low\n            if (high := data.get(\"target_temp_high\")) is not None:\n                head.target_temp_high = high\n        else:\n            raise NotModeled(f\"climate.{service}\")\n        self.changed()\n\n\n_HVAC_ACTION = {\n    \"off\": \"off\", \"fan\": \"fan\", \"standby\": \"idle\", \"heating\": \"heating\", \"cooling\": \"cooling\",\n    \"idle\": \"idle\",\n}\n\n\ndef _whole(value: float | None) -> int | None:\n    return None if value is None else round(value)\n\n\n@dataclass\nclass Room:\n    \"\"\"One room as MXZ keeps it between calls.\"\"\"\n\n    key: str\n    name: str\n    slug: str\n    target: float\n    enable: bool\n    comfort: bool = False\n    comfort_at: float = 0.0\n    latch: fl.FanLatch = field(default_factory=lambda: fl.FanLatch(echo=fl.FanEcho()))\n    memories: dict[str, HeadWriteMemory] = field(default_factory=dict)\n    last_run: tuple[str, float] | None = None\n    pending: set[str] = field(default_factory=set)\n    queued: pl.HeadCommand | None = None\n    active: str | None = None\n    disowned: bool = False\n    sight: HeadSight | None = None\n    temp: float | None = None\n    # What the head and the sensor showed at their last report.\n    shown: tuple[str, dict[str, Any]] | None = None\n\n    @property\n    def climate_id(self) -> str:\n        return climate_id(self.key)\n\n\n@dataclass\nclass Log:\n    \"\"\"What the row did, for the page and the tests: each call to a head and each compute.\"\"\"\n\n    calls: list[tuple[float, str, str, dict[str, Any]]] = field(default_factory=list)\n    computes: list[tuple[float, str]] = field(default_factory=list)\n\n\nclass MxzRow:\n    \"\"\"MXZ Coordinator over the invented heads, driven by the page.\"\"\"\n\n    def __init__(\n        self,\n        heads: InventedHeads,\n        *,\n        settings: Settings | None = None,\n        start: float = 0.0,\n        wall: float = 0.0,\n    ) -> None:\n        self.heads = heads\n        self.settings = settings or Settings()\n        self.now = start\n        self.wall0 = wall - start\n        self.created = wall\n        self.log = Log()\n        self.timers: st.Timers | None = None\n        self.running = False\n        self.rooms: list[Room] = []\n        self._computing = False\n        self._dispatch: list[tm.Refresh] | None = None\n\n    # -- the clock -------------------------------------------------------------------------\n    @property\n    def wall(self) -> float:\n        return self.wall0 + self.now\n\n    def due(self) -> float:\n        \"\"\"When MXZ's next timer runs (``sim_timing.due``).\"\"\"\n        return st.due(self._timers())\n\n    def _timers(self) -> st.Timers:\n        if self.timers is None:\n            raise RuntimeError(\"MXZ is not running\")\n        return self.timers\n\n    def waiting(self, name: str, key: Hashable = None) -> bool:\n        \"\"\"Whether this wakeup is armed now, the ones a running compute armed included.\"\"\"\n        if self._computing:\n            return (name, key) in self._waits\n        return self.timers is not None and (name, key) in self.timers.waits\n\n    # -- event 1: a start ------------------------------------------------------------------\n    def start(\n        self, saved: Mapping[str, Any] | None, *, names: Mapping[str, str],\n        comfort: Mapping[str, tuple[bool, float]] | None = None,\n    ) -> None:\n        \"\"\"MXZ starts with Home Assistant, from the room state store's record ``saved``.\n\n        ``names`` gives each room's name by key, in house order. ``comfort`` gives each room's\n        Comfort priority entity as Home Assistant shows it at the start: whether it is on, and\n        the wall time it last changed. That entity is not MXZ's, so a restart does not reset it;\n        a room missing from ``comfort`` has it off since the clock's start. Follows\n        ``MXZCoordinator.__init__``, ``_resume``, the shared-mode select's restore and\n        ``async_setup``: the sights, the mode record and its stamp, every stored value through\n        ``resume``, the startup seeds, the fan records, the startup quiet, the hold-end wakeup,\n        then the first compute.\n        \"\"\"\n        s = self.settings\n        stored = dict(saved or {})\n        state = rs.SavedState(\n            saved_at=stored.get(\"saved_at\"),\n            unit=stored.get(\"unit\"),\n            sections={\n                key: value for key, value in stored.items()\n                if key not in (\"saved_at\", \"unit\") and isinstance(value, dict)\n            },\n        )\n        self.rooms = []\n        for i, key in enumerate(self.heads.keys):\n            room = Room(\n                key=key, name=names[key], slug=zone_slug(i),\n                target=float(s.profile[\"target_default\"]), enable=False,\n            )\n            room.sight = HeadSight(self.now, self.wall, ACTION_VOTE_SETTLE)\n            self.rooms.append(room)\n        record, _unreadable = rs.mode_record(state.section(rs.SECTION_MODE), self.wall)\n        self.stamp_at = pl.mode_change_stamp(record.changed_at, self.now, self.wall)\n        self.stamp_wall = record.changed_at\n        self.mode_data = record.stored()\n        self.starting = tm.startup_quiet(running=False, startup_ran=False)\n        self.latch: dict[str, str] = {}\n        self.startup: dict[str, str | None] = {}\n        self.coasted = False\n        self.plan: Plan | None = None\n        self._applying: Plan | None = None\n        self._computing = False\n        self._waits: set[tuple[str, Hashable]] = set()\n        self._armed: list[tm.Arm | tm.CancelAll] = []\n        self._asked: list[tm.Refresh] = []\n        self._dispatch: list[tm.Refresh] | None = None\n        switches = {KEY_COORDINATOR_ENABLE: False, KEY_ECO_IDLE: False, KEY_HEAT_LOCKOUT: False,\n                    KEY_COOL_LOCKOUT: False}\n        resumed = rs.resume(\n            state,\n            [rs.RoomSlot(room.climate_id, room.slug, self.grid().target_bounds()) for room in self.rooms],\n            unit=FAHRENHEIT, step=s.profile[\"target_step\"], celsius=False,\n            engage_bounds=s.profile[\"engage_bounds\"],\n        )\n        switches.update(resumed.switches)\n        self.coordinator = switches[KEY_COORDINATOR_ENABLE]\n        self.restored_coordinator_on = self.coordinator\n        if switches[KEY_ECO_IDLE] or switches[KEY_HEAT_LOCKOUT] or switches[KEY_COOL_LOCKOUT]:\n            raise NotModeled(\"eco and the season lockouts\")\n        for room, saved_room in zip(self.rooms, resumed.rooms, strict=True):\n            if saved_room.target is not None:\n                room.target = saved_room.target\n            if saved_room.target_range is not None or saved_room.drift is not None:\n                raise NotModeled(\"a dual setpoint or a room's own drift\")\n            if saved_room.enable is not None:\n                seed = rs.resumed_enable(\n                    room.slug, saved_room.enable, False, saved_room.enable_record,\n                    self.latch, self.startup,\n                )\n                room.enable = saved_room.enable\n                self.latch, self.startup = seed.latch, seed.startup\n            if saved_room.fan is not None:\n                fan = saved_room.fan\n                room.latch = fl.restored(\n                    room.latch, fan.held, last=fan.last, prior=fan.prior, older=fan.older,\n                    on_pending=fan.on_pending, ceiling=s.ceiling,\n                )\n            room.memories.update(saved_room.head_writes)\n            room.shown = self.heads.shown(room.key)\n            room.temp = self.heads.reading(room.key)\n            room.comfort, room.comfort_at = (comfort or {}).get(room.key, (False, self.wall0))\n        self.mode, self.by_votes = rs.resumed_mode(record, None, None)\n        self.running = True\n        self.timers, did = st.start(self.now)\n        self._step(self._hold_end_arm())\n        self._settle(did)\n\n    def _hold_end_arm(self) -> tm.Arm:\n        \"\"\"The hold-end wakeup for the hold left now (``MXZCoordinator._arm_hold_end_timer``).\"\"\"\n        elapsed = None if self.stamp_at is None else self.now - self.stamp_at\n        remaining = 0.0 if elapsed is None else max(0.0, self.settings.hold - elapsed)\n        return tm.hold_end_arm(remaining, retired=False)\n\n    # -- the record a stop leaves, and a restart -------------------------------------------\n    def saved(self) -> dict[str, Any]:\n        \"\"\"What the room state store holds at a stop (``MXZCoordinator``'s ``_*_record``).\"\"\"\n        return {\n            \"saved_at\": self.wall,\n            \"unit\": FAHRENHEIT,\n            rs.SECTION_ROOMS: {\n                room.climate_id: {\n                    \"target\": room.target, \"target_low\": None, \"target_high\": None,\n                    \"drift\": None, \"enable\": room.enable, \"hands_off_released\": False,\n                }\n                for room in self.rooms\n            },\n            rs.SECTION_SWITCHES: {\n                KEY_COORDINATOR_ENABLE: self.coordinator, KEY_ECO_IDLE: False,\n                KEY_HEAT_LOCKOUT: False, KEY_COOL_LOCKOUT: False,\n            },\n            rs.SECTION_FAN: {\n                room.climate_id: fl.fan_record(room.latch, room.shown[1].get(\"fan_mode\") if room.shown else None).as_dict()\n                for room in self.rooms\n            },\n            **({rs.SECTION_MODE: self.mode_data} if self.mode_data is not None else {}),\n            rs.SECTION_HEAD_WRITES: {\n                room.climate_id: {name: memory.record() for name, memory in room.memories.items()}\n                for room in self.rooms if room.memories\n            },\n        }\n\n    def restart(self) -> dict[str, Any]:\n        \"\"\"Home Assistant stops and starts: the store is written, MXZ's memory goes, and it\n        starts from the store. The heads keep what they show. Returns the record.\"\"\"\n        record = self.saved()\n        names = {room.key: room.name for room in self.rooms}\n        comfort = {room.key: (room.comfort, room.comfort_at) for room in self.rooms}\n        self.timers = None\n        self.running = False\n        self.start(record, names=names, comfort=comfort)\n        return record\n\n    # -- the plan's act for a head ---------------------------------------------------------\n    def _idle(self, room: Room) -> str:\n        park = pl.idle_for(\n            room.climate_id, self.settings.idle_action, room.last_run, self._mode(room),\n            self.settings.coil_dry_seconds, self.now, dry_waiting=self.waiting(\"dry\", room.climate_id),\n        )\n        for step in park.steps:\n            self._perform(room, step)\n        return park.idle\n\n    def _planned(self, room: Room) -> str | None:\n        plan = self._applying if self._applying is not None else self.plan\n        row = None if plan is None else plan.room(room.slug)\n        return pl.planned_act(\n            active=room.active, paused=False, state=None if plan is None else plan.state,\n            engage=None if row is None else row.engage, enabled=room.enable, eco=False,\n            idle=lambda: self._idle(room),\n        )\n\n    def _mode(self, room: Room) -> str | None:\n        return None if room.shown is None else room.shown[0]\n\n    def _attributes(self, room: Room) -> dict[str, Any]:\n        return {} if room.shown is None else room.shown[1]\n\n    def grid(self) -> gr.Grid:\n        \"\"\"An invented head's grid (``HeadGrid.read``): its native band, no setpoint step.\"\"\"\n        s = self.settings\n        return gr.Grid(\n            system_unit=FAHRENHEIT, target_step=s.profile[\"target_step\"],\n            clamp_min=s.clamp_min, clamp_max=s.clamp_max,  # type: ignore[attr-defined]\n            native=self.heads.native, native_step=0.0, native_unit=None,\n        )\n\n    def _gates(self) -> pl.AdoptGates:\n        return pl.AdoptGates(\n            accept=self.settings.accept_head_changes, retired=False, coordinator=self.coordinator,\n            inhibited=False, eco=False, starting=self.starting, hands_off=False, floor=False,\n            paused=False,\n        )\n\n    def _adoption(self, room: Room, moved: set[str]) -> pl.Adoption | None:\n        return pl.adopt_head_change(pl.head_change(\n            moved, state=self._mode(room), attributes=self._attributes(room), cloud=False,\n            gates=self._gates(), enabled=room.enable, heat_target=room.target,\n            cool_target=room.target, driven=False, step=self.settings.profile[\"target_step\"],\n            memories=room.memories, grid=self.grid(), mode_stale=lambda _m: False,\n            setpoint_stale=lambda _s: False, planned=lambda: self._planned(room),\n        ))\n\n    def _fan_limits(self) -> fl.FanLimits:\n        s = self.settings\n        return fl.FanLimits(\n            boost=s.fan_boost, ceiling=s.ceiling, up_at=s.profile[\"fan_up_at\"],\n            down_at=s.profile[\"fan_down_at\"], eco_idle=False, idle_action=s.idle_action,\n            resumed=self.restored_coordinator_on, age=timedelta(seconds=self.wall - self.created),\n        )\n\n    # -- performing a step -----------------------------------------------------------------\n    def _arm(self, arm: tm.Arm | tm.CancelAll) -> None:\n        if self._computing:\n            self._armed.append(arm)\n            if isinstance(arm, tm.CancelAll):\n                self._waits = {wait for wait in self._waits if wait[0] != arm.name}\n            elif arm.delay is None:\n                self._waits.discard((arm.name, arm.key))\n            else:\n                self._waits.add((arm.name, arm.key))\n        else:\n            self._settle(self._step(arm))\n\n    def _ask(self, refresh: tm.Refresh | None) -> None:\n        if refresh is None:\n            return\n        if self._computing:\n            self._asked.append(refresh)\n        elif self._dispatch is not None:\n            self._dispatch.append(refresh)\n        else:\n            self._settle(self._step(st.Ask(refresh)))\n\n    def _perform(self, room: Room, step: object, old: tuple[str, dict[str, Any]] | None = None) -> None:\n        \"\"\"Do what one returned step says, with the call its docstring names.\"\"\"\n        match step:\n            case pl.LastRun(run):\n                room.last_run = run\n            case tm.Arm() | tm.CancelAll():\n                self._arm(step)\n            case pl.Queue(command, _taken):\n                room.queued = command\n            case pl.FanShown(fan):\n                room.latch.echo.caught_up(fan)\n            case pl.WritesShown():\n                assert old is not None\n                mode, attributes = self._mode(room), self._attributes(room)\n                hw.writes_caught_up(\n                    room.memories, old_mode=old[0], old_attributes=old[1], mode=mode,\n                    attributes=attributes, grid=self.grid(),\n                )\n            case pl.SeedCancelled():\n                self.startup[room.slug] = \"\"\n            case pl.HeadReport(pending, hold, disown, _replan):\n                room.pending = set() if pending is None else set(pending)\n                self._arm(hold)\n                if disown:\n                    room.queued = None\n                    room.disowned = room.active is not None\n            case tm.Refresh():\n                self._ask(step)\n            case fl.KeepLatch(latch):\n                room.latch = latch\n            case fl.WroteFan(token):\n                room.latch.echo.wrote(token)\n            case fl.SendFan(token):\n                self._send(room, \"set_fan_mode\", {\"fan_mode\": token})\n            case fl.EchoCaughtUp():\n                pass  # the product publishes the Fan auto switch here\n            case pl.Pressed(fields):\n                hw.writes_pressed(\n                    room.memories, fields, mode=self._mode(room), attributes=self._attributes(room),\n                    grid=self.grid(),\n                )\n            case pl.SetTarget(number, value):\n                if number != \"target\":\n                    raise NotModeled(f\"a write to {number}\")\n                self.set_target(room.key, value)\n            case pl.SetEnable(on):\n                self.set_enable(room.key, on)\n            case pl.Latch(entry):\n                if entry is None:\n                    self.latch.pop(room.slug, None)\n                else:\n                    self.latch[room.slug] = entry\n            case pl.SeedDropped():\n                self.startup.pop(room.slug, None)\n            case pl.ReleaseEnded():\n                pass  # no room here is a released hands-off room\n            case pl.OffHealRecheck():\n                cancel = pl.off_heal_recheck(\n                    room.climate_id, self.waiting(\"heal\", (room.climate_id, \"off\")), self._mode(room),\n                    enabled=room.enable, eco_idle=False, planned=lambda: self._planned(room),\n                )\n                if cancel is not None:\n                    self._arm(cancel)\n            case _:\n                raise NotModeled(type(step).__name__)\n\n    # -- a call to a head, and the heads' reports ------------------------------------------\n    def _send(self, room: Room, service: str, data: Mapping[str, Any]) -> None:\n        \"\"\"One call to a head (``head_writes.issue_steps``): remember, then send.\"\"\"\n        counted: Mapping[str, Any] = {}\n        for step in hw.issue_steps(data):\n            match step:\n                case hw.RememberWrites(payload):\n                    counted = hw.remember_writes(\n                        room.memories, payload, mode=self._mode(room),\n                        attributes=self._attributes(room), grid=self.grid(),\n                        size=HEAD_WRITES_REMEMBERED,\n                    )\n                case hw.SendCall():\n                    self.log.calls.append((self.now, room.key, service, dict(data)))\n                    self.heads.call(room.key, service, data)\n                    self.world_changed()\n        del counted  # an invented head refuses no call (``writes_refused`` is never needed)\n\n    def world_changed(self) -> None:\n        \"\"\"The invented house wrote its entities: each head, then its room's sensor, in house\n        order (``invented_house.Bench.changed`` dispatches every room's entities with the model\n        on). A head whose state or attributes changed reports (event 6); a sensor whose reading\n        changed asks for a compute (event 3).\n\n        Home Assistant runs each entity's state-change callbacks as it is written, and the\n        compute a callback asks for in a task it creates, after the dispatch. So the reports\n        and readings of one dispatch are all taken before its ask. A dispatch that asks more\n        than once outside a compute raises ``NotModeled``: then the coordinator's reading\n        handler drops a later ask once a compute has read the readings\n        (``MXZCoordinator._on_input_change``), a rule no product function returns. The page's\n        rooms report one at a time (``world.World``), so it never happens there.\n        \"\"\"\n        outside = not self._computing and self._dispatch is None\n        if outside:\n            self._dispatch = []\n        try:\n            for room in self.rooms:\n                shown = self.heads.shown(room.key)\n                if shown != room.shown:\n                    old, room.shown = room.shown, shown\n                    self._report(room, old)\n                reading = self.heads.reading(room.key)\n                if reading != room.temp:\n                    room.temp = reading\n                    self._ask(tm.Refresh.REQUEST)\n        finally:\n            asks, self._dispatch = (self._dispatch, None) if outside else ([], self._dispatch)\n        if len(asks) > 1:\n            raise NotModeled(\n                \"several entities asking for a compute in one dispatch \"\n                \"(MXZCoordinator._on_input_change drops a later reading's ask)\"\n            )\n        for refresh in asks:\n            self._ask(refresh)\n\n    def _report(self, room: Room, old: tuple[str, dict[str, Any]] | None) -> None:\n        \"\"\"Event 6: a head reports a new state (``planner.report_steps``).\"\"\"\n        old_mode, old_attributes = (None, {}) if old is None else old\n        report = pl.ReportedHead(\n            key=room.climate_id, mode=self._mode(room), attributes=self._attributes(room),\n            old_mode=old_mode, old_attributes=old_attributes,\n            accept=self.settings.accept_head_changes, cloud=False, sight=True,\n            released_by_action=False, startup=room.slug in self.startup,\n            owned_off=room.active is None or room.active == MODE_OFF, parking=False,\n            kicking=False, floor_run=False, paused=False, stale=False, allow_dry=False,\n            dry_allowed=False, enabled=room.enable, eco_idle=False, inhibited=False,\n            unresponsive=False, pending=room.pending,\n            holding=self.waiting(\"heal\", (room.climate_id, \"adopt\")),\n            hands_off_head=lambda: False, dry_reported=lambda: False,\n            planned=lambda: self._planned(room), clock=lambda: self.now,\n            adoption=lambda moved: self._adoption(room, moved),\n        )\n        for step in pl.report_steps(report):\n            self._perform(room, step, (old_mode, old_attributes))\n\n    # -- event 5: a delivery to a local head -----------------------------------------------\n    def _deliver(self, room: Room) -> None:\n        c, room.queued = room.queued, None\n        assert c is not None\n        room.active, room.disowned = c.mode, False\n        s = self.settings\n        steps = pl.delivery_steps(\n            c.mode, c.fan, idle_action=s.idle_action, eco=False, inhibited=False,\n            head_state=self._mode(room),\n        )\n\n        def boost(act: str) -> None:\n            for step in fl.fan_boost(\n                lambda: room.latch, self._attributes(room).get(\"fan_mode\"), act, c.delta,\n                boost=s.fan_boost, modes=self._attributes(room).get(\"fan_modes\"),\n                limits=self._fan_limits,\n            ):\n                self._perform(room, step)\n\n        try:\n            for name in steps.order:\n                if room.disowned:\n                    return\n                if name == \"note\":\n                    for step in steps.note(room.climate_id, c.mode, self.now):\n                        self._perform(room, step)\n                elif name == \"handback\":\n                    boost(\"fan_only\")  # the hand-back is the boost step for fan_only\n                elif name == \"setpoints\":\n                    for call in gr.local_calls(\n                        c.mode, c.low, c.high, mode=self._mode(room),\n                        attributes=self._attributes(room), grid=self.grid(), combined=False,\n                    ):\n                        self._send(room, call.service, call.data)\n                        if room.disowned:\n                            return\n                elif (fan := steps.fan(inhibited=False)) == \"drop_rung\":\n                    room.latch = fl.FanLatch(\n                        echo=room.latch.echo, held=room.latch.held, restored=room.latch.restored,\n                        on_pending=room.latch.on_pending, rung=None,\n                    )\n                elif fan == \"boost\":\n                    boost(c.mode)\n        finally:\n            room.active = None\n\n    # -- event 4: a compute ----------------------------------------------------------------\n    def _compute(self) -> st.Computed:\n        s = self.settings\n        self._computing, self._armed, self._asked = True, [], []\n        self._waits = set(self._timers().waits)\n        inputs: list[pl.RoomInput] = []\n        statuses: list[str] = []\n        comforts: list[tuple[float, str]] = []\n        for room in self.rooms:\n            sight = room.sight\n            assert sight is not None\n            mode, attributes = self._mode(room), self._attributes(room)\n            if mode is None or mode == \"unavailable\":\n                raise NotModeled(\"a head out of sight\")\n            sight.observe(mode, attributes.get(\"hvac_action\"), self.now)\n            status = sight.status(self.now, s.lost_vote_ttl)\n            comfort = comfort_priority(\n                COMFORT_DOMAIN, \"on\" if room.comfort else \"off\",\n                age=self.wall - room.comfort_at, stale_after=s.comfort_stale_after,\n            )\n            comforts.append(comfort)\n            statuses.append(status)\n            assert room.temp is not None\n            inputs.append(pl.RoomInput(\n                slug=room.slug, enabled=room.enable, temp=room.temp, sensor_ok=True,\n                target=room.target, heat_target=room.target, cool_target=room.target,\n                heat_drift=s.drift, cool_drift=s.drift, head=mode, paused=False, dry=False,\n                floor=None, safety=False, vote=None, holds=pl.holds(status, False),\n                boost=comfort[0],\n            ))\n        elapsed = None if self.stamp_at is None else self.now - self.stamp_at\n        decision = pl.decide(\n            inputs,\n            pl.Shared(\n                limits=s.limits, demand_threshold=s.demand_threshold, mode=self.mode,\n                elapsed=elapsed, hold=s.hold, resting=None, by_votes=self.by_votes,\n                resume=self.coordinator and self.restored_coordinator_on,\n                accept_head_changes=s.accept_head_changes,\n            ),\n            self.latch, self.startup,\n        )\n        self.latch, self.startup, self.coasted = decision.latch, decision.startup, decision.coasted\n        plan = Plan(\n            rooms=[self._row(room, inputs[i], decision.rooms[i], statuses[i], comforts[i])\n                   for i, room in enumerate(self.rooms)],\n            state=decision.state, standoff=decision.standoff,\n            mode_by_hands_off=decision.by_votes, mode_by_safety=decision.by_safety,\n            mode_by_comfort_priority=decision.by_comfort, mode_by_floor=decision.by_floor,\n            sensors_ok=True, seconds_since_mode_change=None if elapsed is None else int(elapsed),\n            mode_change_allowed=decision.allowed, inhibited=False, idle_action=s.idle_action,\n        )\n        self._applying = plan\n        self.plan = plan\n        sent = False\n        try:\n            shared = pl.ApplyShared(\n                retired=False, coordinator=self.coordinator, standby=None, inhibited=False,\n                eco=False, idle_action=s.idle_action, coil_dry_seconds=s.coil_dry_seconds,\n                clock=self.now, settings=s.setpoints, mode=self.mode, by_votes=self.by_votes,\n                resting=None,\n            )\n            gate = pl.apply_gate(plan, shared)\n            if gate in (None, \"standby\"):\n                rooms = iter(self.rooms)\n                queued: list[Room] = []\n                for part in pl.apply_plan(plan, self._apply_heads(), shared):\n                    if isinstance(part, pl.ModeWriteBack):\n                        self._write_back(part)\n                        continue\n                    room = next(rooms)\n                    for step in part.steps:\n                        self._perform(room, step)\n                    if room.queued is not None:\n                        queued.append(room)\n                sent = bool(queued)\n                for room in queued:\n                    if room.queued is not None:\n                        self._deliver(room)\n            for room, row in zip(self.rooms, plan.rooms, strict=True):\n                row.fan_hold = room.latch.holds\n        finally:\n            self._applying = None\n            self._armed.extend(tm.arms(self._wakeups(plan)))\n            self._computing = False\n        return st.Computed(sent=sent, asked=tuple(self._asked), armed=tuple(self._armed))\n\n    def _apply_heads(self) -> Iterator[pl.ApplyHead]:\n        \"\"\"Each room's head as the apply reads it when it reaches it (``_apply_head``).\"\"\"\n        for room in self.rooms:\n            yield pl.ApplyHead(\n                climate_id=room.climate_id, vane_kick=False,\n                settling=lambda room=room: pl.holds_change(\n                    self.waiting(\"heal\", (room.climate_id, \"adopt\")),\n                    lambda: self._adoption(room, room.pending),\n                ),\n                paused=False, head=self._mode(room), hands_off=None, released=False, busy=False,\n                startup=room.slug in self.startup, enabled=room.enable, target=room.target,\n                heat_target=room.target, cool_target=room.target, floor_clear=None,\n                taken_over=None,\n                coil_dry=lambda room=room: pl.CoilDryMemory(\n                    room.last_run, self.waiting(\"dry\", room.climate_id),\n                ),\n            )\n\n    def _write_back(self, part: pl.ModeWriteBack) -> None:\n        \"\"\"The plan's mode becomes the shared mode, then the stamp, then the record\n        (``MXZCoordinator._write_back_mode``).\"\"\"\n        self.mode, self.by_votes = part.mode, part.by_votes\n        if part.stamp:\n            stamp = pl.stamp_mode_change(lambda: self.now, lambda: self.wall, retired=False, hold=self.settings.hold)\n            self.stamp_at, self.stamp_wall = stamp.at, stamp.wall\n            if stamp.hold_end is not None:\n                self._arm(stamp.hold_end)\n        if part.record:\n            data: dict[str, Any] = {rs.MODE_KEY: self.mode, rs.MODE_AT_KEY: self.wall,\n                                    rs.MODE_BY_VOTES_KEY: self.by_votes}\n            if self.stamp_wall is not None:\n                data[rs.MODE_CHANGE_KEY] = self.stamp_wall\n            self.mode_data = data\n\n    def _row(\n        self, room: Room, given: pl.RoomInput, decided: pl.RoomDecision, status: str,\n        comfort: tuple[float, str],\n    ) -> RoomPlan:\n        \"\"\"The room's plan row from ``decide``'s result and what the compute read.\n\n        The parts other controllers render (the delivery, the head, start points, the vote\n        basis, the reasons) are left empty: the page does not show them.\n        \"\"\"\n        return RoomPlan(\n            slug=room.slug, name=room.name, demand=decided.demand, engage=decided.engage,\n            temp=given.temp, target=room.target, target_range=None, enabled=room.enable,\n            drift=self.settings.drift, drift_heat=given.heat_drift, drift_cool=given.cool_drift,\n            start_points={}, sensor_health=sensor_health(valid=True, max_age=None, evidence_age=None, in_grace=False),\n            sensor_age=None, hands_off=None, hands_off_vote=None, vote_status=status,\n            lost_since=None, vote_basis={}, safety_priority=False,\n            comfort_priority_entity=comfort_id(room.key), comfort_priority=comfort[0],\n            comfort_priority_status=comfort[1], floor_low=None, floor_high=None, floor_want=None,\n            dry={}, opening={}, fan_hold=room.latch.holds, control_reasons=[], floor={},\n            delivery={}, head={},\n        )\n\n    def _wakeups(self, plan: Plan) -> tm.Wakeups:\n        \"\"\"What the wakeups armed after a compute read (``MXZCoordinator._wakeups``).\"\"\"\n        s = self.settings\n        elapsed = None if self.stamp_at is None else self.now - self.stamp_at\n        sights = [room.sight for room in self.rooms if room.sight is not None]\n        return tm.Wakeups(\n            retired=False, clock_retired=False, coordinator=self.coordinator, standby=False,\n            clock=self.now, wall=self.wall,\n            remaining=float(\"-inf\") if elapsed is None else s.hold - elapsed,\n            allowed=plan.mode_change_allowed,\n            held_back=lambda: pl.held_back(\n                plan.rooms, current=pl.arbitration_mode(self.mode), resting=None,\n            ),\n            coasted=self.coasted, fresh=[], sights=sights,\n            rooms=[tm.Watched(sight=sight, by_action=False, released=False) for sight in sights],\n            lost_ttl=s.lost_vote_ttl, action_hold=float(ACTION_VOTE_HOLD),\n            comfort_stale_after=s.comfort_stale_after,\n            comfort=[\n                (COMFORT_DOMAIN, \"on\" if room.comfort else \"off\", self.wall - room.comfort_at)\n                for room in self.rooms\n            ],\n            clouds=[], openings=[],\n        )\n\n    # -- the timers ------------------------------------------------------------------------\n    def _step(self, event: st.Event) -> st.Step:\n        timers, did = st.step(self._timers(), event, self.now)\n        self.timers = timers\n        return did\n\n\n    def _settle(self, did: st.Step | None, after: Sequence[tm.Refresh] = ()) -> None:\n        \"\"\"Run each compute a step asks for, and each one after it. ``after`` is asked once\n        the first of them has ended, or at once if the step asks for none.\"\"\"\n        if did is None or did.compute is None:\n            did, after = self._ask_each(did, after), ()\n        while did is not None and did.compute is not None:\n            self.log.computes.append((self.now, str(did.compute)))\n            computed = self._compute()\n            timers, did = st.step(self._timers(), computed, self.now)\n            self.timers = timers\n            did, after = self._ask_each(did, after), ()\n\n    def _ask_each(self, did: st.Step | None, refreshes: Sequence[tm.Refresh]) -> st.Step | None:\n        \"\"\"Ask each refresh in order after ``did``. Returns the step that starts a compute, if\n        one of them does, else ``did``.\"\"\"\n        for refresh in refreshes:\n            asked = self._step(st.Ask(refresh))\n            if asked.compute is not None:\n                did = asked\n        return did\n\n    def advance(self, until: float) -> bool:\n        \"\"\"Time passes to ``until``; every MXZ timer due by then runs at its own due time.\n\n        Returns whether one ran.\n\n        Home Assistant runs every timer due at one instant before any compute they ask for, and\n        each adopt hold's end as its own task, whose writes to the room yield before the compute\n        they ask for applies. So all the wakeups of one tick run first, each hold end judged and\n        its writes done, and then what they asked for is asked, in order. Each hold end's\n        closing ask comes once the first compute has ended, when its writes return.\n        \"\"\"\n        ran = False\n        while self.running and self.due() <= until:\n            self.now = max(self.now, self.due())\n            ran = True\n            did = self._step(st.Tick())\n            asks: list[tm.Refresh] = []\n            closing: list[tm.Refresh] = []\n            self._dispatch = asks\n            try:\n                for wakeup in did.ran:\n                    if isinstance(wakeup, st.Fire) and (refresh := self._fired(wakeup)) is not None:\n                        closing.append(refresh)\n            finally:\n                self._dispatch = None\n            self._settle(self._ask_each(did, asks), closing)\n        self.now = max(self.now, until)\n        return ran\n\n    def _fired(self, wakeup: st.Fire) -> tm.Refresh | None:\n        \"\"\"What a wakeup does besides the refresh ``timing.WAKEUPS`` names, which the step\n        already asked for (``MXZCoordinator._on_heal_timer``, ``_on_startup_timer``). Returns\n        an adopt hold end's closing ask.\"\"\"\n        if wakeup.name == \"startup\":\n            self.starting = tm.startup_quiet(running=False, startup_ran=True)\n        elif wakeup.name == \"heal\":\n            head, kind = wakeup.key  # type: ignore[misc]\n            room = next(room for room in self.rooms if room.climate_id == head)\n            if kind == \"adopt\":\n                return self._hold_end(room)\n            else:\n                mode = self._mode(room)\n                self._ask(pl.heal_due(\n                    kind, mode, hands_off_head=lambda: False, dry_allowed=lambda: False,\n                    enabled=room.enable, eco_idle=False, planned=lambda: self._planned(room),\n                    stale=lambda: False, coordinator=self.coordinator, inhibited=False,\n                ))\n        return None\n\n    def _hold_end(self, room: Room) -> tm.Refresh:\n        \"\"\"Event 7: the adopt hold ends (``MXZCoordinator._async_adopt_head_change``): the\n        change is judged and its steps done. Returns the compute it asks for last.\"\"\"\n        moved, room.pending = room.pending, set()\n        adoption = self._adoption(room, moved)\n        mode = self._mode(room)\n        end = pl.hold_end(\n            moved, adoption, mode=mode,\n            field=None if mode is None else pl.setpoint_field(\n                mode, features=self._attributes(room).get(\"supported_features\"), cloud=False,\n            ),\n            dual=False,\n        )\n        for step in end.steps:\n            self._perform(room, step)\n        return end.refresh\n\n    # -- event 3: a person's write to a room, and the room's readings ----------------------\n    def _room(self, key: str) -> Room:\n        return next(room for room in self.rooms if room.key == key)\n\n    def target_bounds(self) -> tuple[float, float]:\n        \"\"\"The range the room's target number offers (``Grid.target_bounds``).\"\"\"\n        return self.grid().target_bounds()\n\n    def set_target(self, key: str, value: float) -> None:\n        \"\"\"A person sets the room's target number (``number.set_value``).\n\n        Home Assistant refuses a value outside the number's range before MXZ sees it; so does\n        this, with ``OutOfRange``.\n        \"\"\"\n        room = self._room(key)\n        low, high = self.target_bounds()\n        if not low <= float(value) <= high:\n            raise OutOfRange(f\"{room.name}'s target {value:g} °F is outside {low:g} to {high:g} °F\")\n        room.target = float(value)\n        for step in pl.target_written(\n            room.climate_id, startup=room.slug in self.startup, coordinator=self.coordinator,\n            enabled=room.enable,\n        ):\n            self._perform(room, step)\n        self._ask(tm.Refresh.REQUEST)\n\n    def set_enable(self, key: str, on: bool) -> None:\n        \"\"\"A person turns the room's enable switch on or off.\"\"\"\n        room = self._room(key)\n        was_on, room.enable = room.enable, on\n        for step in pl.enable_written(room.climate_id, was_on=was_on, on=on):\n            self._perform(room, step)\n        self._ask(tm.Refresh.REQUEST)\n\n    def set_comfort(self, key: str, on: bool) -> None:\n        \"\"\"The room's Comfort priority entity turns on or off (``_on_comfort_change``).\"\"\"\n        room = self._room(key)\n        if room.comfort == on:\n            return\n        room.comfort, room.comfort_at = on, self.wall\n        self._ask(tm.Refresh.REQUEST)\n\n    def set_fan_auto(self, key: str, on: bool) -> None:\n        \"\"\"A person turns the room's Fan auto switch on or off (``FanHold.async_set_auto``).\"\"\"\n        room = self._room(key)\n        latch, acted = fl.fan_auto(\n            room.latch, self._attributes(room).get(\"fan_mode\"), on, self.settings.ceiling,\n        )\n        room.latch = latch\n        if acted:\n            self._ask(tm.Refresh.REQUEST)\n\n    def press(self, key: str, **fields: Any) -> None:\n        \"\"\"A person changes the head at its remote (``invented_house``'s ``remote`` service).\"\"\"\n        head = self.heads.devices.heads[key]\n        for name in (\"hvac_mode\", \"target_temp_low\", \"target_temp_high\", \"fan_mode\"):\n            if name in fields:\n                setattr(head, name, fields[name])\n        self.heads.changed()\n        self.world_changed()\n\n    # -- what the page and the tests read --------------------------------------------------\n    def hold_left(self) -> float:\n        \"\"\"Seconds the mode-change hold still holds a flip back (``mode_hold_remaining``).\"\"\"\n        elapsed = None if self.stamp_at is None else self.now - self.stamp_at\n        return 0.0 if elapsed is None else max(0.0, self.settings.hold - elapsed)\n\n    def pending_waits(self) -> dict[str, float]:\n        \"\"\"Each armed wakeup, by name and key, with the seconds until it runs.\"\"\"\n        timers = self._timers()\n        return {\n            f\"{name} {key}\": round(due.at - self.now, 6)\n            for (name, key), due in sorted(timers.waits.items(), key=lambda item: str(item[0]))\n        }\n\n\n    def rooms_view(self) -> list[dict[str, Any]]:\n        out = []\n        for room in self.rooms:\n            out.append({\n                \"key\": room.key, \"target\": room.target, \"enable\": room.enable,\n                \"comfort\": room.comfort, \"fan_held\": room.latch.holds,\n                \"adopting\": self.waiting(\"heal\", (room.climate_id, \"adopt\")),\n            })\n        return out\n\n\ndef plan_view(plan: Plan | None) -> dict[str, Any] | None:\n    \"\"\"The plan's decision as the page shows it and the tests compare it.\"\"\"\n    if plan is None:\n        return None\n    return {\n        \"state\": plan.state,\n        \"standoff\": plan.standoff,\n        \"mode_by_hands_off\": plan.mode_by_hands_off,\n        \"mode_by_safety\": plan.mode_by_safety,\n        \"mode_by_comfort_priority\": plan.mode_by_comfort_priority,\n        \"mode_by_floor\": plan.mode_by_floor,\n        \"sensors_ok\": plan.sensors_ok,\n        \"seconds_since_mode_change\": plan.seconds_since_mode_change,\n        \"mode_change_allowed\": plan.mode_change_allowed,\n        \"idle_action\": plan.idle_action,\n        \"rooms\": [\n            {\n                \"slug\": room.slug, \"demand\": room.demand, \"engage\": room.engage,\n                \"temp\": room.temp, \"target\": room.target, \"enabled\": room.enabled,\n                \"fan_hold\": room.fan_hold, \"sensor_health\": room.sensor_health,\n                \"vote_status\": room.vote_status, \"comfort_priority\": room.comfort_priority,\n                \"comfort_priority_status\": room.comfort_priority_status,\n            }\n            for room in plan.rooms\n        ],\n    }\n\n",
 "world.py": "\"\"\"The simulator's world: the same three invented rooms twice, stock and MXZ, on one clock.\n\nBoth rows follow the invented house's three rules (``invented_house/model.py``): one outdoor\nunit runs one direction, a head in that direction moves its room toward its setpoint at an\ninvented 1 °F a minute, and a room no head moves drifts toward an invented 76 °F. Neither row\nmeasures real equipment.\n\n- The stock row's heads are set by a person and nothing else. It follows only the rule from\n  Mitsubishi's manual for heads on one outdoor unit: \"the unit selected last goes into standby\n  mode.\" It is not stock AUTO.\n- The MXZ row is MXZ Coordinator's own code (``mxz_row.MxzRow``) at its default settings.\n\nEach room moves on its own 5-second tick, a second apart from the room before it, so each room's\nsensor reports on its own, as real sensors do (``mxz_row.MxzRow.world_changed`` says why that\nmatters). The page calls ``preset``, then ``advance`` as time passes and one method per control,\nand draws ``view()``.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nfrom invented_house import devices as dv\nfrom invented_house import model\nfrom mxz_row import InventedHeads, MxzRow, OutOfRange, climate_id, plan_view\n\n# The wall clock at the simulation's start: 2026-11-19 15:00 UTC. Only differences matter.\nWALL = 1_795_100_400.0\nPHASE = 1.0  # seconds between one room's tick and the next room's\n\n\n@dataclass(frozen=True)\nclass Preset:\n    \"\"\"A starting point: each room's temperature, each stock head as a person set it, and\n    what MXZ's store holds at its start (its targets and the last heat/cool change).\"\"\"\n\n    title: str\n    try_this: str\n    temps: dict[str, float]\n    stock_heads: dict[str, dict[str, Any]]\n    stock_outdoor: str | None\n    mode: str\n    changed_ago: float | None = None  # seconds since MXZ's last heat/cool change; None: none\n    targets: dict[str, float] = field(default_factory=lambda: {\"studio\": 70.0, \"loft\": 70.0, \"den\": 70.0})\n\n\ndef _set(mode: str, to: float = 70.0, fan: str = \"auto\") -> dict[str, Any]:\n    return {\"hvac_mode\": mode, \"target_temp_low\": to, \"target_temp_high\": to, \"fan_mode\": fan}\n\n\nPRESETS: dict[str, Preset] = {\n    \"mixed\": Preset(\n        title=\"One room wants cool, two are done heating\",\n        try_this=\"Watch Studio. Stock leaves it waiting while the outdoor unit runs heat. MXZ \"\n                 \"switches the shared mode to cool and steps the fan down as Studio nears 70 °F.\",\n        temps={\"studio\": 76.0, \"loft\": 70.0, \"den\": 70.0},\n        stock_heads={\"studio\": _set(\"cool\"), \"loft\": _set(\"heat\"), \"den\": _set(\"heat\")},\n        stock_outdoor=\"heat\", mode=\"heat\", changed_ago=7200.0,\n    ),\n    \"satisfied\": Preset(\n        title=\"Every room at target\",\n        try_this=\"Each row heats all three rooms to 70 °F. Then the stock heads stay in heat and \"\n                 \"idle; MXZ turns every head off.\",\n        temps={\"studio\": 66.0, \"loft\": 66.0, \"den\": 66.0},\n        stock_heads={key: _set(\"heat\") for key in (\"studio\", \"loft\", \"den\")},\n        stock_outdoor=\"heat\", mode=\"heat\", changed_ago=7200.0,\n    ),\n    \"standoff\": Preset(\n        title=\"A standoff, and Comfort priority\",\n        try_this=\"Studio wants cool and Den wants heat. MXZ gives the standoff to Studio, the first \"\n                 \"room, until Studio is within 3 °F of its target. Turn on Den's Comfort priority \"\n                 \"before then to give it to Den.\",\n        temps={\"studio\": 79.0, \"loft\": 70.0, \"den\": 66.0},\n        stock_heads={\"studio\": _set(\"cool\"), \"loft\": _set(\"off\"), \"den\": _set(\"heat\")},\n        stock_outdoor=\"cool\", mode=\"cool\", changed_ago=7200.0,\n    ),\n    \"mode_wait\": Preset(\n        title=\"The wait between heat and cool\",\n        try_this=\"MXZ switched to heat a minute ago. Studio wants cool, so MXZ waits out the \"\n                 \"10-minute minimum between mode switches first. Watch the count.\",\n        temps={\"studio\": 76.0, \"loft\": 70.0, \"den\": 70.0},\n        stock_heads={\"studio\": _set(\"cool\"), \"loft\": _set(\"heat\"), \"den\": _set(\"heat\")},\n        stock_outdoor=\"heat\", mode=\"heat\", changed_ago=60.0,\n    ),\n    \"fan_hold\": Preset(\n        title=\"A fan speed you pick is kept\",\n        try_this=\"MXZ cools Studio with the fan on high. Pick a speed on Studio's remote in the \"\n                 \"MXZ row: MXZ keeps it. Turn Fan auto back on to hand the fan back.\",\n        temps={\"studio\": 76.0, \"loft\": 70.0, \"den\": 70.0},\n        stock_heads={\"studio\": _set(\"cool\"), \"loft\": _set(\"off\"), \"den\": _set(\"off\")},\n        stock_outdoor=\"cool\", mode=\"cool\", changed_ago=7200.0,\n    ),\n    \"restart\": Preset(\n        title=\"Restart Home Assistant\",\n        try_this=\"MXZ has just switched to cool, so the 10-minute wait runs. Pick a fan speed on \"\n                 \"Studio's remote, then press Restart: the fan you picked and the wait both carry \"\n                 \"over.\",\n        temps={\"studio\": 76.0, \"loft\": 70.0, \"den\": 70.0},\n        stock_heads={\"studio\": _set(\"cool\"), \"loft\": _set(\"heat\"), \"den\": _set(\"heat\")},\n        stock_outdoor=\"heat\", mode=\"heat\", changed_ago=7200.0,\n    ),\n}\n\n\ndef store(preset: Preset, keys: list[str]) -> dict[str, Any]:\n    \"\"\"The room state store's record MXZ starts from: the Coordinator on, every room on at\n    its target, and the last heat/cool change, if any.\"\"\"\n    record: dict[str, Any] = {\n        \"saved_at\": WALL - 1.0,\n        \"unit\": \"°F\",\n        \"switches\": {\"coordinator_enable\": True},\n        \"rooms\": {climate_id(key): {\"target\": preset.targets[key], \"enable\": True} for key in keys},\n    }\n    if preset.changed_ago is not None:\n        changed = WALL - preset.changed_ago\n        record[\"mode\"] = {\"mode\": preset.mode, \"mode_at\": changed, \"mode_by_votes\": False,\n                          \"last_mode_change\": changed}\n    return record\n\n\nclass World:\n    \"\"\"Both rows, the rooms' model and the clock.\"\"\"\n\n    def __init__(self, preset: str) -> None:\n        self.preset = PRESETS[preset]\n        self.house = dv.load_house()\n        self.keys = [room[\"key\"] for room in self.house[\"rooms\"]]\n        self.names = {room[\"key\"]: room[\"name\"] for room in self.house[\"rooms\"]}\n        self.climate = model.Climate(**self.house[\"climate\"])\n        self.now = 0.0\n        self.stock = dv.Devices.fresh(self.house)\n        self.mxz = dv.Devices.fresh(self.house)\n        for devices in (self.stock, self.mxz):\n            for key, temperature in self.preset.temps.items():\n                devices.rooms[key].temperature = temperature\n        for key, head in self.preset.stock_heads.items():\n            self.stock.heads[key] = dv.Head(**head)\n        self.stock.outdoor = self.preset.stock_outdoor\n        self.heads = InventedHeads(self.house, self.mxz, modelled=True)\n        self.heads.changed()\n        self.row = MxzRow(self.heads, start=0.0, wall=WALL)\n        self.row.start(store(self.preset, self.keys), names=self.names)\n        self.restarts = 0\n\n    # -- time ------------------------------------------------------------------------------\n    def _next_tick(self) -> tuple[float, int]:\n        \"\"\"When the next room moves, and which (by house order).\"\"\"\n        tick = self.climate.tick\n        best: tuple[float, int] | None = None\n        for i in range(len(self.keys)):\n            offset = i * PHASE\n            k = max(0, -(-(self.now - offset) // tick))  # the next tick at or after now\n            at = offset + k * tick\n            if at <= self.now:\n                at += tick\n            if best is None or at < best[0]:\n                best = (at, i)\n        assert best is not None\n        return best\n\n    def advance(self, until: float) -> None:\n        \"\"\"Time passes to ``until``: MXZ's timers and each room's tick, in time order.\"\"\"\n        while True:\n            at, i = self._next_tick()\n            if at > until:\n                break\n            self.row.advance(at)\n            self.now = at\n            self._tick(self.keys[i])\n        self.row.advance(until)\n        self.now = until\n\n    def next_wakeup(self) -> float:\n        \"\"\"When MXZ's next timer runs.\"\"\"\n        return self.row.due()\n\n    def _tick(self, key: str) -> None:\n        \"\"\"One room moves by the model's rules, in both rows.\"\"\"\n        minutes = self.climate.tick / 60\n        for devices in (self.stock, self.mxz):\n            one = dv.Devices(heads=devices.heads, rooms={key: devices.rooms[key]}, outdoor=devices.outdoor)\n            model.step(one, self.climate, minutes)\n            devices.outdoor = one.outdoor\n        self.row.world_changed()\n\n    # -- controls --------------------------------------------------------------------------\n    def set_temperature(self, key: str, value: float) -> None:\n        \"\"\"Both rows' room jumps to ``value``, as if the weather changed it.\"\"\"\n        for devices in (self.stock, self.mxz):\n            devices.rooms[key].temperature = float(value)\n        self.row.world_changed()\n\n    def stock_head(self, key: str, mode: str, to: float, fan: str) -> None:\n        \"\"\"A person sets a stock head: its mode, the temperature it runs to, and its fan.\"\"\"\n        self.stock.heads[key] = dv.Head(**_set(mode, float(to), fan))\n        self.stock.outdoor = model.direction(self.stock, self.stock.outdoor)\n\n    def mxz_target(self, key: str, value: float) -> str | None:\n        \"\"\"A person sets an MXZ room's target number. Returns why Home Assistant refused it,\n        or None.\"\"\"\n        try:\n            self.row.set_target(key, float(value))\n        except OutOfRange as refused:\n            return f\"Home Assistant refused it: {refused}.\"\n        return None\n\n    def mxz_enable(self, key: str, on: bool) -> None:\n        self.row.set_enable(key, bool(on))\n\n    def mxz_comfort(self, key: str, on: bool) -> None:\n        self.row.set_comfort(key, bool(on))\n\n    def mxz_fan_auto(self, key: str, on: bool) -> None:\n        self.row.set_fan_auto(key, bool(on))\n\n    def mxz_remote(self, key: str, mode: str | None = None, to: float | None = None,\n                   fan: str | None = None) -> None:\n        \"\"\"A person changes an MXZ room's head at its remote: its mode, the setpoint its mode\n        runs to (the low one in heat, the high one in cool, as on the invented head), or its fan.\"\"\"\n        head = self.mxz.heads[key]\n        fields: dict[str, Any] = {}\n        if mode is not None:\n            fields[\"hvac_mode\"] = mode\n        if to is not None:\n            running = mode or head.hvac_mode\n            fields[\"target_temp_low\" if running == \"heat\" else \"target_temp_high\"] = float(to)\n        if fan is not None:\n            fields[\"fan_mode\"] = fan\n        self.row.press(key, **fields)\n\n    def restart(self) -> None:\n        \"\"\"Home Assistant stops and starts. The heads and rooms carry on.\"\"\"\n        self.row.restart()\n        self.restarts += 1\n\n    # -- what the page draws ---------------------------------------------------------------\n    def view(self) -> str:\n        row = self.row\n        plan = plan_view(row.plan)\n        rooms = {view[\"key\"]: view for view in row.rooms_view()}\n        out: dict[str, Any] = {\n            \"now\": self.now,\n            \"preset\": {\"title\": self.preset.title, \"try_this\": self.preset.try_this},\n            # The range of an invented head's setpoints, which its remote offers.\n            \"head_range\": [self.house[\"head\"][\"min_temp\"], self.house[\"head\"][\"max_temp\"]],\n            \"stock\": {\"outdoor\": self.stock.outdoor, \"rooms\": []},\n            \"mxz\": {\n                \"outdoor\": self.mxz.outdoor,\n                \"mode\": row.mode,\n                \"target_bounds\": list(row.target_bounds()),\n                \"hold_left\": row.hold_left(),\n                \"standoff\": None if plan is None else plan[\"standoff\"],\n                \"by_comfort\": None if plan is None else plan[\"mode_by_comfort_priority\"],\n                \"next\": round(row.due() - self.now, 1),\n                # While MXZ's start is quiet it takes no change made at a head\n                # (timing.startup_quiet); its startup wakeup ends that.\n                \"quiet_for\": row.pending_waits().get(\"startup None\") if row.starting else None,\n                \"waits\": row.pending_waits(),\n                \"restarts\": self.restarts,\n                \"calls\": [\n                    {\"t\": t, \"room\": self.names[key], \"service\": service, \"data\": data}\n                    for t, key, service, data in row.log.calls[-8:]\n                ],\n                \"rooms\": [],\n            },\n        }\n        for i, key in enumerate(self.keys):\n            for side, devices in ((\"stock\", self.stock), (\"mxz\", self.mxz)):\n                head = devices.heads[key]\n                room = devices.rooms[key]\n                entry = {\n                    \"key\": key,\n                    \"name\": self.names[key],\n                    \"temperature\": dv.reading(room.temperature),\n                    \"mode\": head.hvac_mode,\n                    \"low\": head.target_temp_low,\n                    \"high\": head.target_temp_high,\n                    \"fan\": head.fan_mode,\n                    \"doing\": model.action(head, room, devices.outdoor),\n                }\n                if side == \"mxz\":\n                    decided = None if plan is None else plan[\"rooms\"][i]\n                    entry.update(rooms[key])\n                    entry[\"engage\"] = None if decided is None else decided[\"engage\"]\n                    entry[\"demand\"] = None if decided is None else decided[\"demand\"]\n                out[side][\"rooms\"].append(entry)\n        return json.dumps(out)\n",
 "custom_components/__init__.py": "",
 "custom_components/mxz_coordinator/__init__.py": "\"\"\"The simulator's stand-in for the package's __init__.py, which sets up Home Assistant.\n\nThe page loads only the integration's modules that import no Home Assistant\n(tools/simulator_bundle.py).\"\"\"\n",
 "custom_components/mxz_coordinator/cloud.py": "\"\"\"Cloud heads (beta): the per-head write record and setpoint math.\n\nA cloud head reaches Home Assistant through an integration that polls a\nvendor cloud (MELCloud, Kumo Cloud): its reports trail a command by up to\nminutes, a burst of writes can be dropped, and it can't take MXZ's room\nsensor as its own. So MXZ writes it in batches (mode, one setpoint, fan), at\nmost one per write interval, and after each batch holds it \"pending\" for a\nconfirm wait: MXZ re-sends nothing it already sent, and a report of an older\nstate inside that wait is stale, not a person's change. While a room runs, the\nsetpoint is pushed past the target by a drive offset so the head's own\nthermistor doesn't stop it early; the room sensor still decides when the room\nis done. The offset is @mikepell007's (mxz_coordinator_blueprint, MIT).\n\nA generic head (beta: any other climate entity with heat and cool) takes the\nsame path and the same record, with ``generic`` set: only unavailability puts\nit out of control, never silence.\n\nNo Home Assistant dependency, so the math is tested directly.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport operator\nfrom collections.abc import Callable\nfrom dataclasses import dataclass, field\nfrom typing import Protocol\n\nfrom .const import MODE_COOL, MODE_HEAT\n\n# What a cloud row's plan status reads.\nCLOUD_PENDING = \"pending\"\nCLOUD_CONFIRMED = \"confirmed\"\nCLOUD_UNCONFIRMED = \"unconfirmed\"\nCLOUD_NOT_CONTROLLABLE = \"not_controllable\"\n\n\n@dataclass\nclass CloudHead:\n    \"\"\"What MXZ has sent one cloud head, and what it is waiting to see.\n\n    On the monotonic clock, like every other MXZ timer. In memory only: a new\n    coordinator (a restart or a reload) opens one confirm wait of its own\n    (``startup``), in which every report may be a stale poll from before it.\n    \"\"\"\n\n    write_interval: float\n    confirm_wait: float\n    # The end of the current pending window, and whether it is the startup one.\n    window_until: float\n    startup: bool = True\n    # The last batch's (mode, setpoint or None, fan token or None).\n    intent: tuple[str, float | None, str | None] | None = None\n    # What the head showed when that batch went out, and every earlier intent\n    # since the last confirmation: a report of one of these inside the window\n    # is stale.\n    older_modes: set[str] = field(default_factory=set)\n    older_fans: set[str] = field(default_factory=set)\n    older_setpoints: set[float] = field(default_factory=set)\n    # The last fan and setpoint sent since the last confirmation. Not older\n    # states until a later batch sends another: a batch with no fan or no\n    # setpoint leaves that one current.\n    last_fan: str | None = None\n    last_setpoint: float | None = None\n    last_batch: float | None = None\n    # The last fan boost step written, for the one-rung-per-step limit.\n    fan_at: float | None = None\n    # When the next batch may go out, while one waits on the write interval or\n    # a fan step waits on its limit; None otherwise.\n    release_at: float | None = None\n    # Whether the head has been seen holding everything the last batch sent\n    # once its window closed, and when that was (ISO, display only).\n    confirmed: bool = False\n    confirmed_at: str | None = None\n    # Not controllable: unavailable or silent past the limit.\n    unresponsive: bool = False\n    # A generic head (beta): silence never makes it unresponsive.\n    generic: bool = False\n\n    def pending(self, clock: float) -> bool:\n        \"\"\"Whether the head is inside a confirm window now.\"\"\"\n        return clock < self.window_until\n\n    def stale(\n        self,\n        clock: float,\n        *,\n        mode: str | None = None,\n        fan: str | None = None,\n        setpoint: float | None = None,\n        same: Callable[[float, float], bool] = operator.eq,\n    ) -> bool:\n        \"\"\"Whether a report inside the window can be an older state.\n\n        Inside the startup window any report can be. Inside a batch's window,\n        a mode, fan or setpoint the head showed before that batch (or one MXZ\n        sent earlier and has not seen confirmed) is stale. A value the head\n        never had is a real change, window or not, and so is the batch's own\n        setpoint. ``same(reported, older)`` compares setpoints, on the head's\n        grid where the caller knows it.\n        \"\"\"\n        if not self.pending(clock):\n            return False\n        if self.startup:\n            return True\n        return (\n            (mode is not None and mode in self.older_modes)\n            or (fan is not None and fan in self.older_fans)\n            or (\n                setpoint is not None\n                and any(same(setpoint, older) for older in self.older_setpoints)\n                and not (\n                    self.intent is not None and self.intent[1] is not None\n                    and same(setpoint, self.intent[1])\n                )\n            )\n        )\n\n    def sent(\n        self,\n        clock: float,\n        intent: tuple[str, float | None, str | None],\n        shown_mode: str | None,\n        shown_fan: str | None,\n        shown_setpoint: float | None = None,\n    ) -> None:\n        \"\"\"Record one batch: a new window, and the states it supersedes.\n\n        A batch with no fan supersedes no fan: the fan the head shows then,\n        and the last fan MXZ sent even if unconfirmed, is the one it should\n        keep showing, so a report of it is current. The same for a batch\n        with no setpoint.\n        \"\"\"\n        if self.confirmed:\n            self.older_modes.clear()\n            self.older_fans.clear()\n            self.older_setpoints.clear()\n            self.last_fan = None\n            self.last_setpoint = None\n        elif self.intent is not None:\n            self.older_modes.add(self.intent[0])\n        if shown_mode is not None:\n            self.older_modes.add(shown_mode)\n        self.older_modes.discard(intent[0])\n        if intent[2] is not None:\n            self.older_fans.update(f for f in (self.last_fan, shown_fan) if f is not None)\n            self.older_fans.discard(intent[2])\n            self.last_fan = intent[2]\n        if intent[1] is not None:\n            self.older_setpoints.update(\n                v for v in (self.last_setpoint, shown_setpoint) if v is not None\n            )\n            self.older_setpoints.discard(intent[1])\n            self.last_setpoint = intent[1]\n        self.intent = intent\n        self.last_batch = clock\n        self.window_until = clock + self.confirm_wait\n        self.startup = False\n        self.release_at = None\n        self.confirmed = False\n\n    def refused(self, clock: float) -> None:\n        \"\"\"The last batch raised, so it is not one to wait on.\n\n        The next batch goes out as soon as the write interval allows, which\n        still counts from the refused one: that is the rate the user set.\n        ``release_at`` is that moment (``clock`` if it has already come), so\n        the plan can wake for it with nothing else happening. The window\n        stays open, so a late report of an older state is still stale.\n        \"\"\"\n        self.intent = None\n        self.release_at = clock + self.wait_for_slot(clock)\n\n    def wait_for_slot(self, clock: float) -> float:\n        \"\"\"Seconds until the write interval lets the next batch out (0 = now).\"\"\"\n        if self.last_batch is None:\n            return 0.0\n        return max(0.0, self.last_batch + self.write_interval - clock)\n\n    def status(self, clock: float) -> str:\n        \"\"\"The plan's word for this head now.\"\"\"\n        if self.unresponsive:\n            return CLOUD_NOT_CONTROLLABLE\n        if self.pending(clock) and (self.startup or self.intent is not None):\n            return CLOUD_PENDING\n        return CLOUD_CONFIRMED if self.confirmed else CLOUD_UNCONFIRMED\n\n\nclass CloudRecords(Protocol):\n    \"\"\"Where a controller looks up a head's cloud write record (``heads.HeadDrivers``).\"\"\"\n\n    def cloud(self, climate_id: str) -> CloudHead | None:\n        \"\"\"This head's cloud write record; None for a local head.\"\"\"\n        ...\n\n\ndef drive_setpoint(*, act: str, target: float, offset: float) -> float:\n    \"\"\"The setpoint a running cloud head gets: past the target by ``offset``.\n\n    Heat drives above the target and cool below it; ``offset`` 0 is the bare\n    target. Any other act has no setpoint to drive and returns ``target``.\n    \"\"\"\n    if act == MODE_HEAT:\n        return target + offset\n    if act == MODE_COOL:\n        return target - offset\n    return target\n",
 "custom_components/mxz_coordinator/const.py": "\"\"\"Constants for the MXZ Coordinator integration.\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nDOMAIN = \"mxz_coordinator\"\n\n# climate is last of the platforms it drives, so the number/switch siblings are\n# registered first. button carries no state of its own and follows them all, as\n# does binary_sensor (only a room with a door/window pause has one).\nPLATFORMS: list[str] = [\n    \"number\", \"switch\", \"select\", \"sensor\", \"climate\", \"button\", \"binary_sensor\",\n]\n\n# --- Config-entry keys (collected in the config flow; household-specific) ---\nCONF_PRIMARY_CLIMATE = \"primary_climate\"\nCONF_SECONDARY_CLIMATE = \"secondary_climate\"\nCONF_PRIMARY_SENSOR = \"primary_sensor\"\nCONF_SECONDARY_SENSOR = \"secondary_sensor\"\nCONF_NOTIFY_SERVICE = \"notify_service\"\n\n# Optional vane `select` entities, mirrored onto the native thermostats so the\n# single-target tile keeps vane control (replaces the echavet proxy's vane mode).\nCONF_PRIMARY_VANE_VERTICAL = \"primary_vane_vertical\"\nCONF_PRIMARY_VANE_HORIZONTAL = \"primary_vane_horizontal\"\nCONF_SECONDARY_VANE_VERTICAL = \"secondary_vane_vertical\"\nCONF_SECONDARY_VANE_HORIZONTAL = \"secondary_vane_horizontal\"\n\n# Optional per-zone \"airflow\" sensor: the actual blower speed some firmwares\n# expose (CN105/ESPHome heads publish a `stage` text_sensor decoded from the\n# 0x09 power packet). Mirrored onto the tile so it shows REAL airflow while the\n# fan is handed to the firmware's own `auto` (display only — see climate.py).\nCONF_PRIMARY_STAGE = \"primary_stage\"\nCONF_SECONDARY_STAGE = \"secondary_stage\"\n\n# --- N-zone config (entry VERSION 2) ---\n# entry.data[\"zones\"] = ordered list of zone dicts; LIST ORDER = standoff priority\n# (index 0 = highest, the \"primary wins\" generalization).\nCONF_ZONES = \"zones\"\nZONE_NAME = \"name\"\nZONE_CLIMATE = \"climate\"\nZONE_SENSOR = \"sensor\"\nZONE_VANE_VERTICAL = \"vane_vertical\"\nZONE_VANE_HORIZONTAL = \"vane_horizontal\"\nZONE_STAGE_SENSOR = \"stage_sensor\"\n# Optional per-sensor reporting cadence (room-sensor freshness). The three\n# durations are in MINUTES (like coil_dry_minutes), positive and finite; each is\n# per SENSOR, never inferred from another room or from recent history.\n#   report_interval  the cadence the sensor's own documentation promises (P)\n#   max_age          an explicit maximum age, overriding the derived 3P\n#   startup_grace    an explicit startup grace, overriding the derived max_age\n# A room with NEITHER report_interval NOR max_age has an unknown cadence: its\n# age is shown and never enforced. There is no universal cutoff.\nZONE_REPORT_INTERVAL = \"report_interval\"\nZONE_MAX_AGE = \"max_age\"\nZONE_STARTUP_GRACE = \"startup_grace\"\n# The sensor's EVIDENCE BASIS: what this source can prove about a reading being\n# current. It is INDEPENDENT of the cadence above and defaults to `unknown` — a\n# duration alone never buys enforcement, because it says how often the source\n# claims to report, not whether its writes are reports.\n#   unknown           (default) age is shown, never enforced\n#   ha_state_write    the source contract guarantees that EVERY accepted write,\n#                     including the first one after setup or reload, is a\n#                     current acquisition and can never replay a restored or\n#                     cached value. Then the HA write itself is the evidence.\n#   sample_timestamp  the source publishes a trustworthy marker as an entity\n#                     attribute: either a sample TIME\n#                     (`sample_timestamp_attribute`) or a monotonically\n#                     advancing sample SEQUENCE (`sample_sequence_attribute`).\n#                     Exactly one is named, and only an ADVANCING marker is\n#                     evidence — repeated cache writes carrying the same marker\n#                     move no deadline and recover nothing.\n# A user or integration can still misstate that external contract, and a\n# generic monitor cannot detect the mistake (docs/MIGRATION.md says so).\nZONE_EVIDENCE_BASIS = \"evidence_basis\"\n# Opt-in per room; absent = off, so every entry stored before this option\n# existed is opted out.\n# Off: a disabled room's head is held off every cycle, as it always has been.\n# On: disabling sends off until the head is seen off, then the coordinator\n# leaves that head alone until the room is enabled again (someone can run it\n# from its own remote), and its observed heat/cool is a low-priority vote.\nZONE_HANDS_OFF = \"hands_off\"\n# Per room, what a released hands-off head's heat/cool vote follows. Stored\n# only as VOTE_BASIS_ACTION; the default (VOTE_BASIS_MODE) removes the key, so\n# a room that never chose stores exactly what it stored before this existed.\n# mode: the head votes the heat or cool it is set to, as it always has.\n# action: that vote counts only while the head's own hvac_action says it is\n# running that way (heating in heat, cooling in cool), and for\n# ACTION_VOTE_HOLD after it stops. A head never seen reporting an\n# hvac_action since MXZ started votes by its mode.\nZONE_HANDS_OFF_VOTE_BASIS = \"hands_off_vote_basis\"\nVOTE_BASIS_MODE = \"mode\"\nVOTE_BASIS_ACTION = \"action\"\nVOTE_BASES = (VOTE_BASIS_MODE, VOTE_BASIS_ACTION)\n# Seconds an action-basis vote still counts after its head stops running:\n# rides out the short idle gaps an inverter shows near its setpoint, and a\n# head's slow hvac_action reports. Fixed 10-minute hold.\nACTION_VOTE_HOLD = 600\n# Seconds after a head's hvac_mode is seen to change (any change: MXZ's own\n# off on release, a remote, anything) during which its report of running is\n# not yet a run for an action-basis vote: it counts only if the head still\n# reports running when this ends. On hardware (2026-10-28 18:30, after MXZ ran\n# a test head in heat and parked it off) a remote's cool was answered by\n# \"cooling\" 0.11 s after the head showed cool (0.29 s after the call), a stale\n# report that lasted 5.3 s, until idle; its real cooling began 100 s later.\n# Every real start seen after a mode change that day came 10.6 to 16.7 s after\n# the call. 15 s is almost three times the stale report's 5.3 s, and holds a\n# real start back by at most about 4 s.\nACTION_VOTE_SETTLE = 15\n# Optional per-zone binary_sensor: \"this zone is asserting a safety override\n# right now\" (e.g. a freeze/overheat floor). Unset = this zone's Demand never\n# carries PRIORITY_SAFETY. Settable on any zone regardless of enable/hands_off\n# -- a coordinated room's own demand or a hands-off room's vote can both be\n# marked safety; see logic.arbitrate().\nZONE_SAFETY_PRIORITY_ENTITY = \"safety_priority_entity\"\n# Optional per-room Comfort priority entity. When rooms want opposite modes, a\n# room whose entity reads \"on\" (1) or a higher number moves ahead of rooms with\n# less, within its own rank only: freeze floors, Safety priority rooms,\n# overheat ceilings and the mode-switch wait always come first, and a real\n# demand still beats a hands-off vote (see logic.arbitrate()). Stored only\n# when set; no key = no boost, so every room stored before this existed, and\n# every room left blank, decides exactly as before. The idea is @csingley's\n# comfort priority rank in ha-climate-zone-sequencer (f911e4a, see NOTICE).\nZONE_COMFORT_PRIORITY_ENTITY = \"comfort_priority_entity\"\n# The domains it accepts: on/off entities (\"on\" = 1, anything else 0) and\n# number entities (their own value; negative, NaN, infinity and text are 0).\nCOMFORT_ONOFF_DOMAINS = (\"binary_sensor\", \"input_boolean\")\nCOMFORT_NUMBER_DOMAINS = (\"number\", \"input_number\", \"sensor\")\nCOMFORT_DOMAINS = (*COMFORT_ONOFF_DOMAINS, *COMFORT_NUMBER_DOMAINS)\n# Why a room's comfort priority is what it is (the plan row's\n# comfort_priority_status). Only \"on\" and \"number\" can carry a boost.\nCOMFORT_NOT_SET = \"not_set\"\nCOMFORT_ON = \"on\"\nCOMFORT_OFF = \"off\"\nCOMFORT_NUMBER = \"number\"\nCOMFORT_UNAVAILABLE = \"unavailable\"\nCOMFORT_UNKNOWN = \"unknown\"\nCOMFORT_MISSING = \"missing\"\nCOMFORT_NOT_A_NUMBER = \"not_a_number\"\n# An on/off entity that has read \"on\" for longer than the stale limit.\nCOMFORT_STALE = \"stale\"\nZONE_SAMPLE_TIMESTAMP_ATTR = \"sample_timestamp_attribute\"\nZONE_SAMPLE_SEQUENCE_ATTR = \"sample_sequence_attribute\"\n# Optional per-room freeze floor / overheat ceiling, in the system unit, acting\n# only while the room is disabled. Absent = none: every entry stored before\n# these keys existed has no floor, and a blank field stores no key.\nZONE_FLOOR_LOW = \"floor_low\"\nZONE_FLOOR_HIGH = \"floor_high\"\n# Optional per-room uneven drift: this room's own \"Let it get cooler by\" /\n# \"Let it get warmer by\" (the global CONF_DRIFT_* sides, for one room). Absent =\n# none: every entry stored before these keys existed is unchanged, and a blank\n# field stores no key. Clamped on load into the profile's engage_bounds.\nZONE_DRIFT_COOLER_BY = \"drift_cooler_by\"\nZONE_DRIFT_WARMER_BY = \"drift_warmer_by\"\n# Opt-in per room: separate Heat to and Cool to instead of one target. Stored\n# only while on (True); turning it off removes the key, so a room that never\n# opted in, or opted out again, stores exactly what it stored before.\nZONE_DUAL_SETPOINT = \"dual_setpoint\"\n# Opt-in per room: Allow Dry mode. Stored only while on (True); off removes\n# the key, so every entry stored before this option existed is opted out, and\n# a head put in dry is put back as it always was (BANNED_MODES).\n# On, while the room is enabled: a head a person puts in dry is left in it (no\n# heal, no mode, setpoint, fan or vane writes) and the room's temperature goal\n# pauses. The head is a cool vote at hands-off rank (dry runs the outdoor unit\n# the cooling way), which a cool lockout blocks. If another room wins heat, MXZ\n# parks the head at its idle action and sends one notice; it never puts dry\n# back. Leaving dry starts the coil-dry run as leaving cool does. The room\n# page shows it only for a head that lists dry.\n# On, for a head that lists dry (3.16.0): the room's MXZ thermostat offers Dry\n# too. Picking it enables the room and sends the head dry once, the only time\n# MXZ sends dry; from then on it is the person's dry above. Heat/Cool takes the\n# head back to the plan; Off disables the room. A head that drops dry from its\n# list, or the option turned off, ends it with one notice.\nZONE_ALLOW_DRY = \"allow_dry\"\n# Door/window pause (opt-in, per room; idea from @mikepell007's MIT blueprint\n# mxz_coordinator_blueprint). A room names ONE opening entity: a binary_sensor,\n# or a group of them (on = open). With the pause on, an opening that reads open\n# for the open delay pauses the room: its head goes straight to off (no\n# coil-dry run) and it drops out of the shared-mode vote. When it has read\n# closed for the close delay the room resumes. Unavailable or unknown never\n# starts a pause. Stored only in the room's record; no key is no feature, so\n# every entry stored before it existed behaves exactly as before.\nZONE_OPENING_ENTITY = \"opening_entity\"\n# The pause itself, stored only while on (a sensor can stay configured with\n# the pause off).\nZONE_OPENING_PAUSE = \"opening_pause_enable\"\n# Seconds open before the pause and closed before the resume; stored only\n# where they differ from the defaults.\nZONE_OPENING_OPEN_DELAY = \"opening_open_delay\"\nZONE_OPENING_CLOSE_DELAY = \"opening_close_delay\"\nDEFAULT_OPENING_OPEN_DELAY = 60\nDEFAULT_OPENING_CLOSE_DELAY = 120\nOPENING_OPEN_DELAY_BOUNDS = (0, 1800)\nOPENING_CLOSE_DELAY_BOUNDS = (0, 3600)\n# Phone notices on pause, resume and override, stored only while on. They go\n# through the room's own notify service when one is set, else the entry's.\nZONE_OPENING_NOTIFY = \"opening_notify\"\nZONE_OPENING_NOTIFY_SERVICE = \"opening_notify_service\"\n# At most one pause/resume pair of notices per room in this many seconds, so\n# a door that flaps can't flood a phone.\nOPENING_NOTIFY_SECONDS = 600\n# A room's opening state (logic.opening_state). PAUSED and CLOSING are the\n# paused room: off, no vote. OVERRIDDEN is a person running the room anyway\n# (a manual change on its head, or its Window Override switch) until the\n# opening reads closed.\nOPENING_CLOSED = \"closed\"\nOPENING_OPENING = \"opening\"\nOPENING_PAUSED = \"paused\"\nOPENING_CLOSING = \"closing\"\nOPENING_OVERRIDDEN = \"overridden\"\nOPENING_PAUSED_STATES = (OPENING_PAUSED, OPENING_CLOSING)\n# What the room thermostat says about it.\nOPENING_REASON_PAUSED = \"door/window open\"\nOPENING_REASON_OVERRIDDEN = \"window open, manual override\"\n# How long a Dry picked on the room thermostat counts as the head's dry before\n# the head reports it (seconds; a cloud room waits its confirm wait if that is\n# longer). Past it, with no dry seen, the plan has the head again.\nDRY_PICK_WAIT = 60\n# Per room: how MXZ reaches the head (beta). Stored only as HEAD_TYPE_CLOUD or\n# HEAD_TYPE_GENERIC, or as HEAD_TYPE_LOCAL where the head's platform suggested\n# cloud and the user kept local (in setup, or by switching a cloud or generic\n# room back); no key reads local, so every entry stored before this option\n# existed, and every CN105 room, stores exactly what it stored before.\n# local: today's path, unchanged (ESPHome/CN105 heads, and any other head).\n# cloud: a head behind a cloud integration that polls (MELCloud, Kumo Cloud).\n# MXZ sends it the mode on its own call, then one setpoint pushed past the\n# target by the drive offset, at most one write batch per write interval, and\n# reads its reports for a confirm wait after each batch (see coordinator.py).\n# generic: any other Home Assistant climate entity that offers heat and cool\n# (a window AC, another brand's mini-split, a HomeKit-bridged unit), opted in\n# by the user and never suggested. It takes the cloud path above, with\n# shorter timing defaults, and only \"unavailable\" puts it out of control:\n# a push-only head can stay silent for hours while idle. A 1-head entry is\n# allowed only when its head is generic (it has its own compressor).\n# An ESPHome head is always local, whatever is stored.\nZONE_HEAD_TYPE = \"head_type\"\nHEAD_TYPE_LOCAL = \"local\"\nHEAD_TYPE_CLOUD = \"cloud\"\nHEAD_TYPE_GENERIC = \"generic\"\nHEAD_TYPES = (HEAD_TYPE_LOCAL, HEAD_TYPE_CLOUD, HEAD_TYPE_GENERIC)\n# The head types that take the cloud write path (setpoint offset, write\n# interval, confirm wait).\nOFFSET_HEAD_TYPES = (HEAD_TYPE_CLOUD, HEAD_TYPE_GENERIC)\n# Entity platforms the setup flow suggests cloud for (the room page doesn't);\n# the user confirms. melcloud is Home Assistant's own; kumo is dlarrick/hass-kumo;\n# kumo_cloud is jjustinwilson/comfort_HA (manifest domains, read 2026-10-29).\nCLOUD_PLATFORMS = (\"melcloud\", \"kumo\", \"kumo_cloud\")\n# A cloud room's tunables, stored only while the room is cloud and only when\n# set to something other than the default (blank or the default stores no key,\n# so the default follows the system unit). The drive offset is in the unit\n# stored with it (ZONE_DRIVE_OFFSET_UNIT, the system unit when it was set) and\n# is converted into the system unit after a °F/°C switch; one stored without a\n# unit is in the system unit. The two times are seconds.\nZONE_DRIVE_OFFSET = \"drive_offset\"\nZONE_DRIVE_OFFSET_UNIT = \"drive_offset_unit\"\nZONE_WRITE_INTERVAL = \"write_interval\"\nZONE_CONFIRM_WAIT = \"confirm_wait\"\n# Setpoint drive offset: while a cloud room runs, its head gets target + offset\n# in heat and target - offset in cool, so the head's own thermistor doesn't\n# stop it early; the room sensor still decides when the room is done. From\n# @mikepell007's mxz_coordinator_blueprint (MIT). 0 sends the bare target.\nDEFAULT_DRIVE_OFFSET_F = 2.0\nDEFAULT_DRIVE_OFFSET_C = 1.0\nDRIVE_OFFSET_MAX_F = 6.0\nDRIVE_OFFSET_MAX_C = 3.0\n# At most one write batch per cloud head per this many seconds; a newer\n# intent waiting out the interval replaces the older one.\nDEFAULT_WRITE_INTERVAL = 60\nWRITE_INTERVAL_BOUNDS = (30, 300)\n# After a batch, a cloud head is pending this many seconds: MXZ re-sends\n# nothing it already sent and reads a report of an older state as stale.\nDEFAULT_CONFIRM_WAIT = 90\nCONFIRM_WAIT_BOUNDS = (30, 600)\n# A generic head's defaults: the low end of both bounds. A generic head is\n# usually local or push-based, so it reports back sooner than a polled cloud.\nGENERIC_WRITE_INTERVAL = WRITE_INTERVAL_BOUNDS[0]\nGENERIC_CONFIRM_WAIT = CONFIRM_WAIT_BOUNDS[0]\n# A cloud head's fan boost moves one rung at most per this many seconds.\nCLOUD_FAN_STEP_SECONDS = 300\n# A cloud head unavailable this long is not controllable: no writes, its\n# room's call doesn't count (unless Safety priority is on), and a repair issue\n# says so. One that is available but sends no report at all (not even an\n# unchanged one) is the same after CLOUD_SILENT_SECONDS: Home Assistant's own\n# MELCloud integration polls every 15 minutes (since 2026.2; 2024.12 polled\n# every 60 s), so a quiet MELCloud head is silent for 15 minutes at a time,\n# and that limit is two missed polls and five minutes more.\n# A generic head (beta) goes out only by CLOUD_STALE_SECONDS unavailable:\n# silence alone never counts, because a push-only head reports nothing while\n# nothing changes.\nCLOUD_STALE_SECONDS = 900\nCLOUD_SILENT_SECONDS = 2100\n# The setpoint step a cloud head that publishes none is rounded to, per\n# system unit.\nCLOUD_STEP_F = 1.0\nCLOUD_STEP_C = 0.5\n# hass.data key of the options flow's one-shot handoff to the reload it\n# triggers (unless that save is applied in place, which drops it):\n# {(entry_id, head): {\"seed_range\": True} | {\"target\": t}}.\nDUAL_HANDOFF_KEY = \"mxz_coordinator_dual_handoff\"\n# The values the room page accepts, per unit system: (low min, low max, high\n# min, high max). A floor outside these is rejected, never clamped.\nFLOOR_RANGE_F = (35.0, 65.0, 75.0, 100.0)\nFLOOR_RANGE_C = (2.0, 18.0, 24.0, 38.0)\n# The unit the entry's saved temperatures and differences (coordinator's\n# _SAVED_TEMPERATURES, _SAVED_DRIFTS, CONF_DEMAND_THRESHOLD) and each room's\n# ZONE_FLOOR_LOW/HIGH and ZONE_DRIFT_COOLER_BY/WARMER_BY were last converted to,\n# from the first °F/°C switch on. A load whose system unit differs converts them\n# again. An entry that has never seen a switch has no such key, and is never\n# written for this.\nCONF_SAVED_TEMP_UNIT = \"saved_temp_unit\"\n# The no-progress cap (decision 11): this long actually driving the head\n# without one step of new best reading ends the run as `blind`.\nFLOOR_STALL_SECONDS = 2 * 3600\n# A stalled run re-arms one step past its worst reading in this much of the\n# driving before the stall (P9), not since its last gain: a dip earlier in\n# the window cannot push the re-arm line far past the stall.\nFLOOR_REARM_SECONDS = 3600\n# A hands-off room that yielded a run to a person re-arms after this long\n# (or once the room reaches the clear line).\nFLOOR_YIELD_SECONDS = 4 * 3600\n# At most one floor notice per room in this long, whatever the kind (P5).\nFLOOR_NOTICE_SECONDS = 3600\nEVIDENCE_UNKNOWN = \"unknown\"\nEVIDENCE_HA_WRITE = \"ha_state_write\"\nEVIDENCE_SAMPLE_TIMESTAMP = \"sample_timestamp\"\n# The bases a setup form may offer; anything else reads as `unknown`.\nEVIDENCE_BASES = (EVIDENCE_UNKNOWN, EVIDENCE_HA_WRITE, EVIDENCE_SAMPLE_TIMESTAMP)\n# What a NEW room stores when setup or Reconfigure creates it (3.16.0): a\n# freeze floor in the system unit, and a 6 h maximum age (minutes) on the\n# ha_state_write basis. Written into the room once, at creation, as ordinary\n# values the room page shows, edits and clears. Nothing reads these at\n# runtime: a room without the keys (every room stored before 3.16.0, or one\n# whose values were cleared) has no floor and an unknown cadence.\nNEW_ROOM_FLOOR_LOW_F = 45.0\nNEW_ROOM_FLOOR_LOW_C = 7.0\nNEW_ROOM_MAX_AGE = 360.0\n# The setup flow and Reconfigure take one head only when it is generic (beta).\nMIN_ZONES = 2\nMAX_ZONES = 8\n\n# The maximum age derived from a reporting interval: a room goes stale at the\n# THIRD due instant, so two missed due reports are tolerated and no more.\nSTALE_MISSED_REPORTS = 3\n\n# Room-sensor health (per-zone plan key and `zones` view field).\n#   healthy          fresh qualifying evidence, deadline still in the future\n#   awaiting_report  provisionally eligible during the startup grace; the\n#                    current value is NOT evidence this incarnation witnessed\n#   stale            the configured maximum age was reached: no automatic demand\n#   invalid          missing/unavailable/non-numeric/non-finite (M13's reader)\n#   cadence_unknown  no cadence configured: age is shown, never enforced\n# How far a room's head vote can be trusted right now (the plan's vote_status).\n# live: the head is in sight. stale: out of sight (unavailable or gone), its\n# last-known vote still counts. expired: out of sight for the whole TTL, so\n# that vote no longer counts. unknown: not seen since MXZ started.\nVOTE_LIVE = \"live\"\nVOTE_STALE = \"stale\"\nVOTE_EXPIRED = \"expired\"\nVOTE_UNKNOWN = \"unknown\"\n\nHEALTH_HEALTHY = \"healthy\"\nHEALTH_AWAITING = \"awaiting_report\"\nHEALTH_STALE = \"stale\"\nHEALTH_INVALID = \"invalid\"\nHEALTH_CADENCE_UNKNOWN = \"cadence_unknown\"\n# The states that make a room ineligible for automatic demand. One continuous\n# run of them is ONE unhealthy episode, however the subtype changes inside it.\nHEALTH_UNHEALTHY = (HEALTH_STALE, HEALTH_INVALID)\n# The states in which an unchanged report can still change something: an\n# unhealthy room recovers on one, and a provisional room replaces its startup\n# grace with that report's own evidence deadline. A healthy or unknown-cadence\n# room learns nothing from one, so its writes never wake the coordinator.\nHEALTH_REPORT_SENSITIVE = (HEALTH_STALE, HEALTH_INVALID, HEALTH_AWAITING)\n# The eligible states a recovery can land in: an enforcement-capable room comes\n# back to `healthy`, an unknown-basis one only to `cadence_unknown`.\nHEALTH_ELIGIBLE = (HEALTH_HEALTHY, HEALTH_CADENCE_UNKNOWN)\n\n\ndef zone_slug(index: int) -> str:\n    \"\"\"Stable per-zone slug used in unique_ids and plan keys.\n\n    Zones 0/1 keep the legacy \"primary\"/\"secondary\" slugs so existing 2-zone\n    installs migrate with ZERO entity-registry churn; zones beyond get zone_N\n    (1-based, so the third zone is ``zone_3``).\n    \"\"\"\n    if index == 0:\n        return \"primary\"\n    if index == 1:\n        return \"secondary\"\n    return f\"zone_{index + 1}\"\n\n# --- Options keys (tunable constants; were hardcoded in the YAML package) ---\nCONF_DEMAND_THRESHOLD = \"demand_threshold\"\nCONF_ENGAGE_DEADBAND = \"engage_deadband\"\n# Optional uneven drift: how far below target before heat starts, and above\n# target before cool starts. No default and no key when blank: blank means\n# CONF_ENGAGE_DEADBAND, so an install that never sets them runs as before.\nCONF_DRIFT_COOLER_BY = \"drift_cooler_by\"\nCONF_DRIFT_WARMER_BY = \"drift_warmer_by\"\nCONF_MODE_HYSTERESIS = \"mode_hysteresis\"\n# Optional: how long, in minutes, a head MXZ has lost sight of (unavailable or\n# gone) keeps its last-known vote. No key when blank: blank means\n# DEFAULT_LOST_VOTE_TTL, so an install that never sets it stores nothing.\nCONF_LOST_VOTE_TTL = \"lost_vote_ttl\"\n# Optional: how many hours an on/off Comfort priority entity may read \"on\"\n# (by Home Assistant's own last_changed) before it stops counting. 0 = no\n# limit. No key when blank: blank means DEFAULT_COMFORT_STALE_HOURS. Never\n# applies to number entities.\nCONF_COMFORT_STALE_HOURS = \"comfort_priority_stale_hours\"\nCONF_ECO_COOL_MAX = \"eco_cool_max\"\nCONF_ECO_HEAT_MIN = \"eco_heat_min\"\nCONF_CLAMP_MIN = \"clamp_min\"\nCONF_CLAMP_MAX = \"clamp_max\"\nCONF_RESTING_MODE_BIAS = \"resting_mode_bias\"\nCONF_HEAT_LOCKOUT_FLOOR = \"heat_lockout_floor\"\nCONF_COOL_LOCKOUT_CEILING = \"cool_lockout_ceiling\"\n# Optional local-weather seasonal changeover (auto-drives the lockout switches).\nCONF_CHANGEOVER_ENTITY = \"changeover_entity\"\nCONF_CHANGEOVER_HEAT_ABOVE = \"changeover_heat_above\"\nCONF_CHANGEOVER_COOL_BELOW = \"changeover_cool_below\"\n# Accept changes made at the head: a setpoint or on/off set at a head (its remote\n# or its own app) is adopted by the room instead of written over. On by default,\n# so an entry with no key has it on; False in its options makes MXZ the only\n# writer. The head's heat/cool choice is never adopted: the plan keeps the shared\n# mode. From @BHSPitMonkey's fork (Discussion #103).\nCONF_ACCEPT_HEAD_CHANGES = \"accept_head_changes\"\nDEFAULT_ACCEPT_HEAD_CHANGES = True\n\n# Optional delta-proportional \"fan boost\" (Tesla-style: bigger off-target -> faster fan).\nCONF_FAN_BOOST_ENABLE = \"fan_boost_enable\"\nCONF_FAN_BOOST_MAX = \"fan_boost_max\"\n\n# --- Defaults (match packages/mxz_coordinator.yaml exactly) ---\nDEFAULT_DEMAND_THRESHOLD = 3.0  # S — off-target °F before the SHARED MODE may flip\nDEFAULT_ENGAGE_DEADBAND = 1.0  # D — off-target °F before a head actively runs\nDEFAULT_MODE_HYSTERESIS = 600  # seconds minimum dwell before a heat<->cool flip\n# Minutes a lost head's last-known vote still counts (stale), then it expires.\n# The default of @csingley's ha-climate-zone-sequencer (DEFAULT_LAST_KNOWN_TTL).\nDEFAULT_LOST_VOTE_TTL = 30\nLOST_VOTE_TTL_BOUNDS = (1, 240)  # minutes, the UI's and the load clamp's range\nDEFAULT_COMFORT_STALE_HOURS = 12\nCOMFORT_STALE_HOURS_BOUNDS = (0, 168)  # hours, the UI's and the load clamp's range\nDEFAULT_ECO_COOL_MAX = 78.0  # away/eco cool extreme\nDEFAULT_ECO_HEAT_MIN = 50.0  # away/eco heat extreme\nDEFAULT_CLAMP_MIN = 59  # firmware min setpoint\nDEFAULT_CLAMP_MAX = 88  # firmware max setpoint\nDEFAULT_HEAT_LOCKOUT_FLOOR = 58.0  # heat-lockout safety floor: heat below this even if locked\nDEFAULT_COOL_LOCKOUT_CEILING = 80.0  # cool-lockout safety ceiling: cool above this even if locked\nDEFAULT_CHANGEOVER_HEAT_ABOVE = 68.0  # forecast daily high (°F) at/above -> heat-lockout on\nDEFAULT_CHANGEOVER_COOL_BELOW = 50.0  # forecast daily high (°F) at/below -> cool-lockout on\nCHANGEOVER_INTERVAL_MINUTES = 60  # how often to re-read the changeover weather signal\n\n# --- Fan boost: drive the head's fan speed by how far the room is off-target ---\n# The head's raw HA fan_modes list is UNSORTED. True airflow slowest->fastest is\n#   quiet < low < medium < MIDDLE < high   (trap: \"middle\" is FASTER than \"medium\").\n# \"auto\" is the firmware's own weak ramp we override. MAX = \"high\".\nFAN_AUTO = \"auto\"\nFAN_QUIET = \"quiet\"\nFAN_LOW = \"low\"\nFAN_MEDIUM = \"medium\"\nFAN_MIDDLE = \"middle\"\nFAN_HIGH = \"high\"\n# Ascending true airflow speed; idx 0..4.\nFAN_LADDER = (FAN_QUIET, FAN_LOW, FAN_MEDIUM, FAN_MIDDLE, FAN_HIGH)\n# Older fan writes a head still behind may yet show, kept per head beyond the\n# last two: enough for a slow head to lag down the whole ladder and back, twice.\n# Past it the oldest goes, and a report of that one would read as a pick.\nFAN_OLDER_WRITES = 4 * len(FAN_LADDER)\n# The same bound for what MXZ remembers of its mode and setpoint writes, per head\n# and per mode or setpoint (logic.HeadWriteMemory).\nHEAD_WRITES_REMEMBERED = FAN_OLDER_WRITES + 2\n# delta (°F off-target) >= up_at[i] to step UP into rung i+1\nFAN_BOOST_UP_AT = (1.0, 2.0, 3.0, 4.0)\n# up_at - 0.5 hysteresis; leave rung i once delta < down_at[i-1]\nFAN_BOOST_DOWN_AT = (0.5, 1.5, 2.5, 3.5)\n# ON by default since v2.10.0/v3.0.0 (opt-out via the Configure dialog) — it's simply a\n# better experience than the firmware's weak \"auto\" ramp. An explicitly-saved\n# False in an entry's options is always honored.\nDEFAULT_FAN_BOOST_ENABLE = True\nDEFAULT_FAN_BOOST_MAX = FAN_HIGH\n\n# --- Airflow (stage) sensor -> settable fan token, for LIVE display only ------\n# CN105/ESPHome heads publish the actual blower speed as a `stage` text_sensor\n# (decoded from the 0x09 power packet — see echavet MitsubishiCN105ESPHome\n# README ~line 902, \"actual fan speed of the indoor unit\"). It reports SEVEN\n# granular stages, but the head only accepts FIVE settable speeds, so this map\n# is approximate & monotonic (7-vs-5 mismatch: two stages collapse onto `quiet`,\n# and DIFFUSE — the low-airflow wide-throw mode — maps to `low`, not a top rung).\n# Values arrive uppercase from ESPHome; we normalize case/whitespace before\n# lookup. Used ONLY to make the tile honest while the fan is in firmware `auto`;\n# it never influences what the coordinator commands.\nSTAGE_TO_FAN = {\n    \"IDLE\": FAN_QUIET,\n    \"LOW\": FAN_QUIET,\n    \"GENTLE\": FAN_LOW,\n    \"MEDIUM\": FAN_MEDIUM,\n    \"MODERATE\": FAN_MIDDLE,\n    \"HIGH\": FAN_HIGH,\n    \"DIFFUSE\": FAN_LOW,\n}\n\n# Resting-mode bias: which shared mode to settle on when NO room is calling.\n#   \"last\" (default) -> hold whatever was last called (original behavior).\n#   \"cool\"/\"heat\"    -> always rest in that mode, so the system won't sit idle in\n#                       the wrong mode for the season. A genuine opposite demand\n#                       (room past its demand threshold) still flips the mode; the\n#                       bias only sets the *neutral* resting mode, it never blocks a call.\nRESTING_BIAS_LAST = \"last\"\nRESTING_BIAS_COOL = \"cool\"\nRESTING_BIAS_HEAT = \"heat\"\nRESTING_BIAS_OPTIONS = (RESTING_BIAS_LAST, RESTING_BIAS_COOL, RESTING_BIAS_HEAT)\nDEFAULT_RESTING_MODE_BIAS = RESTING_BIAS_LAST\n\n# --- External inhibit / low-power standby (grid-down, load-shed, DR) ----------\n# An optional watched entity (a grid-status binary_sensor, a load-shed switch, a\n# \"vacation\" boolean, ...): while it reads ``inhibit_active_state`` the\n# coordinator parks its heads in a low-power hold and self-restores on release.\n# Orthogonal to the enable kill-switch, so there is NO prior state to snapshot.\n# A dropout of the watched entity (unavailable/unknown/missing) reads as NOT\n# held — fail toward normal coordination; a stuck sensor must never park the\n# house.\nCONF_INHIBIT_ENTITY = \"inhibit_entity\"\nCONF_INHIBIT_ACTIVE_STATE = \"inhibit_active_state\"\nCONF_INHIBIT_ACTION = \"inhibit_action\"\nINHIBIT_ACTION_OFF = \"off\"  # zero draw, no protection\nINHIBIT_ACTION_FAN_ONLY = \"fan_only\"  # circulate only\nINHIBIT_ACTION_ECO = \"eco\"  # protection-only band: low draw AND freeze-safe\nINHIBIT_ACTION_OPTIONS = (\n    INHIBIT_ACTION_OFF,\n    INHIBIT_ACTION_FAN_ONLY,\n    INHIBIT_ACTION_ECO,\n)\nDEFAULT_INHIBIT_ACTION = INHIBIT_ACTION_ECO  # freeze-safe beats lowest-draw\nDEFAULT_INHIBIT_ACTIVE_STATE = \"on\"  # grid sensors are often inverted -> \"off\"\n\n# --- Idle action: how a non-running head parks ---------------------------------\n# A satisfied room (or a standoff loser parked by a shared-mode mismatch) parks\n# by this action. fan_only keeps air moving; on a wet coil after cooling, that\n# airflow carries the coil smell into the room — \"off\" stops the fan and lets\n# the head close its vanes instead. NOTE: \"off\" is NOT a tighter refrigerant seal; MXZ outdoor\n# units bleed refrigerant through idle heads either way (oil return, and the\n# SW5-7/8 dip options) — the only thing this changes is airflow.\n# \"off_after_dry\" idles in fan_only for a coil-dry period after ACTIVE COOLING\n# (heat leaves no wet coil), then powers off — so the coil isn't sealed wet.\n# Its label is \"Dry the coil (fan only), then off\": it is not the heads' own\n# Dry (dehumidify) mode (see ZONE_ALLOW_DRY), though leaving that mode starts\n# this run too, as leaving cool does.\n# New entries default to off_after_dry. Entries saved before that default\n# (which never stored a choice) migrate to an explicit fan_only, so an upgrade\n# does not change how an existing install idles (see async_migrate_entry).\nCONF_IDLE_ACTION = \"idle_action\"\nIDLE_ACTION_FAN_ONLY = \"fan_only\"  # circulate (the original default)\nIDLE_ACTION_OFF = \"off\"  # fan stops, vanes close\nIDLE_ACTION_OFF_AFTER_DRY = \"off_after_dry\"  # dry the coil first, then off\nIDLE_ACTION_OPTIONS = (\n    IDLE_ACTION_FAN_ONLY,\n    IDLE_ACTION_OFF,\n    IDLE_ACTION_OFF_AFTER_DRY,\n)\nDEFAULT_IDLE_ACTION = IDLE_ACTION_OFF_AFTER_DRY\nCONF_COIL_DRY_MINUTES = \"coil_dry_minutes\"\nDEFAULT_COIL_DRY_MINUTES = 10\n\nTARGET_DEFAULT = 70\n\n# Eco setpoint edges when a head runs in eco (from the actuator script)\nECO_COOL_HIGH = 78\nECO_COOL_LOW = 76\nECO_HEAT_HIGH = 61\nECO_HEAT_LOW = 59\n\n# --- Unit profiles -----------------------------------------------------------\n# The coordinator operates entirely in the Home Assistant SYSTEM temperature\n# unit (room sensors and head setpoints already arrive in that unit). The\n# decision math in logic.py is pure-numeric, so the only unit-dependent things\n# are DEFAULT tunables, the setpoint band width, the eco edges, the target\n# default, and the display resolution. A °F system is byte-for-byte unchanged\n# (the °F profile reproduces every legacy DEFAULT_*); a °C system gets clean\n# round metric values and 0.5° resolution instead of nonsensical °F numbers.\n_UNIT_PROFILE_FAHRENHEIT = {\n    \"target_default\": float(TARGET_DEFAULT),  # 70 °F\n    \"target_step\": 1.0,\n    \"setpoint_band\": 2.0,  # cool -> (t-2, t); heat -> (t, t+2)\n    \"eco_cool\": (float(ECO_COOL_LOW), float(ECO_COOL_HIGH)),  # (76, 78)\n    \"eco_heat\": (float(ECO_HEAT_LOW), float(ECO_HEAT_HIGH)),  # (59, 61)\n    \"fan_up_at\": FAN_BOOST_UP_AT,  # (1, 2, 3, 4) °F off-target\n    \"fan_down_at\": FAN_BOOST_DOWN_AT,  # (0.5, 1.5, 2.5, 3.5) °F hysteresis\n    \"engage_bounds\": (0.5, 5.0),  # UI + load clamp for the re-engage drift\n    \"dual_min_gap\": 2.0,  # a dual-setpoint room's least Cool to - Heat to\n    \"defaults\": {\n        CONF_DEMAND_THRESHOLD: DEFAULT_DEMAND_THRESHOLD,\n        CONF_ENGAGE_DEADBAND: DEFAULT_ENGAGE_DEADBAND,\n        CONF_ECO_COOL_MAX: DEFAULT_ECO_COOL_MAX,\n        CONF_ECO_HEAT_MIN: DEFAULT_ECO_HEAT_MIN,\n        CONF_CLAMP_MIN: DEFAULT_CLAMP_MIN,\n        CONF_CLAMP_MAX: DEFAULT_CLAMP_MAX,\n        CONF_HEAT_LOCKOUT_FLOOR: DEFAULT_HEAT_LOCKOUT_FLOOR,\n        CONF_COOL_LOCKOUT_CEILING: DEFAULT_COOL_LOCKOUT_CEILING,\n        CONF_CHANGEOVER_HEAT_ABOVE: DEFAULT_CHANGEOVER_HEAT_ABOVE,\n        CONF_CHANGEOVER_COOL_BELOW: DEFAULT_CHANGEOVER_COOL_BELOW,\n    },\n}\n_UNIT_PROFILE_CELSIUS = {\n    \"target_default\": 21.0,  # ~70 °F\n    \"target_step\": 0.5,  # mini-splits accept 0.5 °C steps\n    \"setpoint_band\": 1.0,  # cool -> (t-1, t); heat -> (t, t+1)\n    \"eco_cool\": (24.0, 26.0),\n    \"eco_heat\": (15.0, 16.0),\n    \"fan_up_at\": (0.5, 1.0, 1.5, 2.0),  # °C off-target\n    \"fan_down_at\": (0.25, 0.75, 1.25, 1.75),  # °C hysteresis\n    \"engage_bounds\": (0.25, 2.5),  # UI + load clamp for the re-engage drift\n    \"dual_min_gap\": 1.0,  # a dual-setpoint room's least Cool to - Heat to\n    \"defaults\": {\n        CONF_DEMAND_THRESHOLD: 1.5,\n        CONF_ENGAGE_DEADBAND: 0.5,\n        CONF_ECO_COOL_MAX: 26.0,\n        CONF_ECO_HEAT_MIN: 10.0,\n        CONF_CLAMP_MIN: 15,\n        CONF_CLAMP_MAX: 31,\n        CONF_HEAT_LOCKOUT_FLOOR: 14.0,\n        CONF_COOL_LOCKOUT_CEILING: 27.0,\n        CONF_CHANGEOVER_HEAT_ABOVE: 20.0,\n        CONF_CHANGEOVER_COOL_BELOW: 10.0,\n    },\n}\n\n\ndef unit_profile(celsius: bool) -> dict[str, Any]:\n    \"\"\"Return the tunable/resolution profile for the HA system temperature unit.\"\"\"\n    return _UNIT_PROFILE_CELSIUS if celsius else _UNIT_PROFILE_FAHRENHEIT\n\n# Vane \"kick\": a vane change while a head is OFF can't physically move the\n# louvre (and the firmware forgets the position on power-up), so the\n# coordinator briefly runs the head in fan_only to apply it, then hands the\n# head back to the plan (off again in eco/away).\nVANE_KICK_SPINUP = 8  # s after fan_only before commanding the vane\nVANE_KICK_APPLY = 20  # s for the louvre to travel before switching back off\n# Cap on how long unload/reload waits for a cancelled kick to unwind. A kick\n# awaits another integration's climate/select service, and a handler that\n# defers cancellation must not hang Home Assistant's config-entry unload.\nVANE_KICK_RETIRE_TIMEOUT = 5  # s\n\n# Self-heal debounce windows (YAML `for:` durations)\nBAND_DRIFT_DELAY = 20  # head in heat_cool/auto/dry this long -> re-apply\nOFF_WHILE_ENABLED_DELAY = 30  # head off while enabled this long -> re-apply\n# At most one heal notice per head in this long; every heal is still logged.\nHEAL_NOTICE_SECONDS = 3600\nADOPT_DELAY = 5  # a change made at a head holds this long (s) -> adopted\nSTARTUP_RECOVER_DELAY = 40  # after HA start, wait this long then recompute\n\n# A seed with no fan-hold restore data reads a fan_only idle token as our own\n# only on an entry at least this old (s) whose coordinator was restored ON; a\n# younger entry may be a first-ever compute that must honor a pre-install pick.\nIDLE_SEED_MIN_ENTRY_AGE = 600\n\n# Modes a head must never sit in (drift); the coordinator owns these transitions.\nBANNED_MODES = (\"heat_cool\", \"auto\", \"dry\")\n\n# Recompute trigger event (kept for echavet mitsubishi_climate_proxy interop)\nEVENT_RECOMPUTE = \"mxz_recompute\"\nSERVICE_RECOMPUTE = \"recompute\"\n\n# Plan \"state\" / engage sentinel values\nMODE_COOL = \"cool\"\nMODE_HEAT = \"heat\"\nMODE_FAN_ONLY = \"fan_only\"\nMODE_OFF = \"off\"\nMODE_DRY = \"dry\"  # a head's own Dry (dehumidify); MXZ never sends it\nDEMAND_NEUTRAL = \"neutral\"\nENGAGE_SATISFIED = \"satisfied\"\n\n# Every per-zone entity suffix the platforms register, so one room's unique_ids\n# are f\"{entry_id}_{zone_slug(index)}_{suffix}\". Two callers need this list to be\n# complete: the setup prune (a missing suffix removes and recreates that record\n# on EVERY setup, spending the room's custom name, area and disabled flag on HA\n# 2024.12) and the reorder move (a missing suffix leaves that one setting behind\n# on the old priority slot). tests/test_registry_lifecycle.py and\n# tests/test_room_rename_reorder.py pin it against what the platforms register.\nZONE_ENTITY_SUFFIXES = (\n    \"target\", \"drift\", \"drift_follow_global\", \"enable\", \"thermostat\", \"fan_auto\",\n)\n# The per-zone suffixes only a dual-setpoint room registers (its Heat to and\n# Cool to numbers). Kept apart so a room that isn't opted in provides, and\n# keeps, exactly the set above: the setup prune adds these to a room's valid\n# set only while it's opted in (so turning it off removes them), and the\n# reorder move carries them with every room that has them.\nDUAL_ZONE_ENTITY_SUFFIXES = (\"target_low\", \"target_high\")\n# The per-zone suffixes only a room with a door/window pause registers (its\n# Window Override switch and its paused binary_sensor), kept apart the same way.\nOPENING_ZONE_ENTITY_SUFFIXES = (\"window_override\", \"paused_open\")\n\n# Global helper entity keys (used for unique_id suffixes and translation keys).\n# Per-zone entities build theirs from zone_slug() instead, and translate through\n# the generic zone_* keys with the zone's name substituted in.\nKEY_COORDINATOR_ENABLE = \"coordinator_enable\"\nKEY_ECO_IDLE = \"eco_idle\"\nKEY_HEAT_LOCKOUT = \"heat_lockout\"\nKEY_COOL_LOCKOUT = \"cool_lockout\"\nKEY_SHARED_MODE = \"shared_mode\"\nKEY_PLAN = \"plan\"\n\nUNAVAILABLE_STATES = (\"unknown\", \"unavailable\", \"none\", \"\")\n",
 "custom_components/mxz_coordinator/fan_latch.py": "\"\"\"The manual fan hold's decision: whether a fan speed a head shows is a person's pick.\n\nStandard library only, so the simulator and the tests call it without Home Assistant.\n``fan_hold.FanHold`` reads the head, the settings and the clock, calls these, and keeps the\nresult. A person's pick latches the head, and MXZ makes no fan write to it until it is handed\nback, on the room's Fan auto switch or by the head reading \"auto\". MXZ's own writes, which a\nhead can show late, never latch it (``FanEcho``).\n\nOne head's state is a ``FanLatch``. Each head report is first passed to\n``FanLatch.echo.caught_up``, then ``observe_fan`` reads the speed for the next fan write, and\n``fan_step`` reads it and says what a delivery writes.\nA start's record comes back through ``restored`` and a Fan auto gesture through ``fan_auto``.\nWhat the room state store and the Fan auto switch keep of a head's hold is a ``FanRecord``,\nwhich ``fan_record`` builds.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections import deque\nfrom collections.abc import Callable, Iterable, Sequence\nfrom dataclasses import dataclass, replace\nfrom datetime import timedelta\nfrom typing import Any, Self\n\nfrom .const import (\n    FAN_AUTO,\n    FAN_LADDER,\n    FAN_OLDER_WRITES,\n    IDLE_ACTION_FAN_ONLY,\n    IDLE_SEED_MIN_ENTRY_AGE,\n    MODE_COOL,\n    MODE_FAN_ONLY,\n    MODE_HEAT,\n)\nfrom .logic import fan_for_delta\n\n# Echo baselines, including adopted observations and held user tokens; these\n# historical attribute names do NOT prove command delivery or token ownership.\n# Dual-channel persistence is a workaround for the frozen lifecycle read oracle:\n# clean states must not read extra data. Unavailable states use extra data.\n# Publish memory changes synchronously to keep clean/extra snapshots coherent.\n# Neither channel is a delivery journal or an arbitrary-crash guarantee.\nATTR_LAST_FAN_COMMAND = \"last_fan_command\"\nATTR_PRIOR_FAN_COMMAND = \"prior_fan_command\"\nATTR_OLDER_FAN_COMMANDS = \"older_fan_commands\"\nATTR_FAN_ON_PENDING = \"fan_on_pending\"\n\n\ndef stored_token(value: Any) -> str | None:\n    \"\"\"A restored fan token, or None for anything that is not one.\"\"\"\n    return value if isinstance(value, str) else None\n\n\ndef older_tokens(value: Any) -> tuple[str, ...]:\n    \"\"\"Restored older echo baselines; anything but a list of tokens is none.\"\"\"\n    if not isinstance(value, list) or not all(isinstance(token, str) for token in value):\n        return ()\n    return tuple(value)\n\n\ndef pending_handback(data: Any, held: bool) -> bool:\n    \"\"\"Only a well-formed explicit instruction can override token inference.\"\"\"\n    return (\n        held is False and data.get(ATTR_FAN_ON_PENDING) is True\n        and all(data.get(key) is None or isinstance(data.get(key), str)\n                for key in (ATTR_LAST_FAN_COMMAND, ATTR_PRIOR_FAN_COMMAND))\n    )\n\n\n@dataclass(frozen=True)\nclass FanRecord:\n    \"\"\"A head's fan hold as a start reads it (``FanHold.record``).\n\n    MXZ's room state store keeps it as the head's ``fan`` record, and the Fan\n    auto switch carries the same beside its state (``fan_hold.FanHoldRestoreData``,\n    this record as Home Assistant's restore data).\n\n    ``held`` is the one bool that decides a restart: the switch's own state\n    cannot always carry it. The switch is unavailable while the head is\n    missing from the state machine, so a head whose integration is unloaded\n    or failed at shutdown leaves ``unavailable`` persisted — not an answer to\n    \"was this room held?\". HA stores extra restore data beside the state\n    whatever the state says, so the hold survives the outage that hid it.\n\n    ``last``/``prior`` are the coordinator's echo memory for the head, the\n    last two commanded or adopted tokens (None before any baseline). They\n    permit bounded echo tolerance, not proof that a token came from us.\n    Readers before this field ignore it; a record without it restores the\n    bool alone.\n\n    ``older`` is that memory's older end, only while the head was behind at the\n    stop, oldest first. Absent otherwise, so most records keep their old shape.\n\n    ``on_pending`` is earned only by explicit ON with no usable speed. It\n    survives a saved restart and is consumed once by the first usable report,\n    or cancelled by later OFF. It is not own-command or delivery provenance.\n    Legacy/malformed instructions are absent; held truth always takes priority.\n    \"\"\"\n\n    held: bool\n    last: str | None = None\n    prior: str | None = None\n    on_pending: bool = False\n    older: tuple[str, ...] = ()\n\n    def as_dict(self) -> dict[str, Any]:\n        \"\"\"Serialize for the restore store.\"\"\"\n        data: dict[str, Any] = {\n            \"held\": self.held,\n            ATTR_LAST_FAN_COMMAND: self.last,\n            ATTR_PRIOR_FAN_COMMAND: self.prior,\n        }\n        # Absent means false, preserving the legacy payload when no explicit\n        # handback awaits a report. Contradictory held truth always wins.\n        if self.on_pending is True and self.held is False:\n            data[ATTR_FAN_ON_PENDING] = True\n        if self.older:\n            data[ATTR_OLDER_FAN_COMMANDS] = list(self.older)\n        return data\n\n    @classmethod\n    def from_dict(cls, data: dict[str, Any]) -> Self | None:\n        \"\"\"Rebuild from the store; anything but a clean bool is no answer.\n\n        A token that is not a string is no memory, not a different answer.\n        \"\"\"\n        held = data.get(\"held\")\n        if not isinstance(held, bool):\n            return None\n        return cls(\n            held,\n            stored_token(data.get(ATTR_LAST_FAN_COMMAND)),\n            stored_token(data.get(ATTR_PRIOR_FAN_COMMAND)),\n            pending_handback(data, held),\n            older_tokens(data.get(ATTR_OLDER_FAN_COMMANDS)),\n        )\n\n\nclass FanEcho:\n    \"\"\"The fan speeds MXZ wrote to one head that the head may still show.\n\n    ``last`` is the last speed commanded or adopted, and ``prior`` the one\n    before it: a head can briefly still show that one, so a speed is a\n    person's only if it is neither. A head can lag further than that (F1,\n    docs/formal/PARKED-FINDINGS.md): ``older`` holds the speeds MXZ wrote that\n    this head may yet show, in the order written, a speed written twice\n    appearing twice. Its reports drop what came before them, so a head caught\n    up leaves the last write alone in it (see ``caught_up``). ``None`` means no\n    memory yet, and an empty ``older`` no older write.\n\n    The latch sets its own baseline by starting a new one: a hold, an adopted\n    speed, a stamp of ``auto``, a restore.\n    \"\"\"\n\n    def __init__(\n        self, last: str | None = None, prior: str | None = None, older: Iterable[str] = (),\n    ) -> None:\n        self.last = last\n        self.prior = prior\n        self.older: deque[str] = deque(older, maxlen=FAN_OLDER_WRITES + 2)\n\n    def wrote(self, token: str) -> None:\n        \"\"\"Roll the memory for a fan speed MXZ is sending.\n\n        A rewrite of the token already commanded rolls nothing (see\n        ``FanHold._async_write``). With no memory yet, as after a start or a\n        hold, it starts from the two before this one, which the head may still\n        show (F1's cost, docs/formal/PARKED-FINDINGS.md). ``auto`` counts like a\n        speed in it: a later report of ``auto`` may be that first one.\n        \"\"\"\n        last = self.last\n        if token == last:\n            return\n        prev = self.prior\n        self.prior = token if last is None else last\n        self.last = token\n        if last is None:\n            return\n        memory = self.older\n        if not memory:\n            memory.extend(dict.fromkeys(written for written in (prev, last) if written is not None))\n        memory.append(token)\n\n    def own(self, observed: str) -> bool:\n        \"\"\"Whether a speed the head shows can be one MXZ wrote: never a person's pick.\n\n        One of the last two, or an older write the head's reports haven't\n        passed yet. ``auto`` is not asked about: its report releases a hold\n        whatever is remembered.\n        \"\"\"\n        if observed in (self.last, self.prior):\n            return True\n        return observed in self.older_commands()\n\n    def caught_up(self, observed: Any) -> bool:\n        \"\"\"A head's report: the writes before it are behind the head for good.\n\n        A head shows its writes in order, so it can't show those again, and a\n        pick of one from here is a pick. A speed written more than once counts as\n        its earliest write left: this report may be that one, with the rest of\n        the writes still coming. A report of ``prior`` drops nothing, which is\n        wider than it has to be and only for a head still one write behind.\n\n        A report of the last command with no other write left has caught up, and\n        the memory stays as that one write. The next write adds to it, so a speed\n        the head has passed doesn't come back. That can't tell a head that jumped\n        straight to the last of two writes of a speed, so the writes between\n        stay echoes until a report rules them out (F1's cost,\n        docs/formal/PARKED-FINDINGS.md).\n\n        Returns whether the memory changed.\n        \"\"\"\n        memory = self.older\n        if not memory or observed not in memory:\n            return False\n        changed = False\n        if observed == self.last or observed != self.prior:\n            changed = memory[0] != observed\n            while memory[0] != observed:\n                memory.popleft()\n        return changed\n\n    def older_commands(self) -> list[str]:\n        \"\"\"The older writes this adds to the last two, oldest first, each once.\n\n        Never one of the last two, and never auto.\n        \"\"\"\n        skip = (self.last, self.prior, FAN_AUTO)\n        return [token for token in dict.fromkeys(self.older) if token not in skip]\n\n\n@dataclass(frozen=True, slots=True)\nclass FanLatch:\n    \"\"\"One head's manual fan hold, as a decision reads it and leaves it.\n\n    ``held`` is None until something decides it, which reads as not held.\n    ``restored`` is a start's held-or-not truth, not yet read against a speed\n    the head shows. ``on_pending`` is a Fan auto on given while the head showed\n    no speed, waiting for its first one. ``rung`` is the boost ladder's index,\n    None when none is kept.\n    \"\"\"\n\n    echo: FanEcho\n    held: bool | None = None\n    restored: bool | None = None\n    on_pending: bool = False\n    rung: int | None = None\n\n    @property\n    def holds(self) -> bool:\n        \"\"\"Whether the head counts as held: a start's truth not yet read wins over the latch.\n\n        The Fan auto switch shows this (off is held), and a stop saves it.\n        \"\"\"\n        return self.restored if self.restored is not None else self.held is True\n\n\n@dataclass(frozen=True, slots=True)\nclass FanLimits:\n    \"\"\"What the decision reads of the settings and the clock.\n\n    ``boost`` is whether fan boost is on. ``ceiling`` is the highest ladder\n    index boost may write. ``resumed`` is whether this entry's coordinator\n    switch came back on at the start, and ``age`` how long the entry has\n    existed (None when it doesn't know).\n    \"\"\"\n\n    boost: bool\n    ceiling: int\n    up_at: tuple[float, ...]\n    down_at: tuple[float, ...]\n    eco_idle: bool\n    idle_action: str\n    resumed: bool\n    age: timedelta | None\n\n\ndef observe_fan(\n    latch: FanLatch, observed: str, act: str, delta: float, limits: FanLimits\n) -> FanLatch:\n    \"\"\"Read the speed a head shows (``observed``, never None) for the manual fan hold.\n\n    ``act`` is the mode this head is run in and ``delta`` how far its room is\n    off target; the returned latch's ``held`` says whether MXZ leaves the fan\n    alone. The report was passed to ``latch.echo.caught_up`` first, as every\n    head report is. The hold moves off that OBSERVED speed:\n\n    * a pending restore (the first speed observed after a restart, reload or\n      standby release) is reconciled by ``reconcile_restored_hold``:\n      restored truth beats token guessing\n    * observed \"auto\"                 -> released (user handed control back)\n    * observed token MXZ can't have written -> latched (a user departure;\n      ``FanEcho.own`` absorbs the echo race where the head still reports\n      the token we wrote one cycle ago, or an older write the head's\n      reports haven't passed yet)\n    * no echo memory yet (first compute with nothing restored): a\n      non-\"auto\" reading seeds LATCHED, mirroring the engage-latch's \"resume\n      from the head's own state\" — a manual pick that predates the restart\n      is honored — UNLESS the reading is a speed the ladder would hold at\n      the current delta, which is our own boost speed echoing back (see\n      ``seed_matches_boost``), or our own fan_only idle on an established\n      entry (see ``seed_is_own_idle``).\n\n    A hold ends ONLY on a gesture: the Fan-auto switch, or an observed \"auto\".\n    Room drift, target changes, and slider moves between speeds never release\n    one, at any speed including max.\n\n    History, because this rule got simpler twice: through v2.17.0 a slider-set\n    hold at the head's top token ALSO merged back into auto on any cycle where\n    the ladder would have commanded max anyway — a hold releasing itself with\n    no user gesture. Through v2.18.0 a *departure* to that top token was\n    likewise read as \"hand it back\", because HomeKit's fan slider has no\n    \"auto\" stop and a user who latched a zone from Apple Home had no on-slider\n    way out. The per-zone Fan-auto switch bridges to HomeKit as a plain toggle\n    and is that way out, so both readings of \"max means give it back\" are\n    gone: max now holds like any other speed.\n\n    Because the coordinator only sees observed state per cycle — not events —\n    a re-gesture to the SAME token the head already reports is invisible; that\n    limitation is accepted.\n    \"\"\"\n    if latch.on_pending:\n        return adopt(replace(latch, on_pending=False, restored=None), observed, limits.ceiling)\n    if latch.restored is not None:\n        return reconcile_restored_hold(\n            replace(latch, restored=None), observed, latch.restored, act, limits\n        )\n\n    echo = latch.echo\n    if observed == FAN_AUTO:\n        # Observed auto releases everything.\n        if echo.last is None:\n            # Baseline stamp: without it a head idle-at-auto since startup\n            # keeps an empty command memory (the return-to-auto write is\n            # idempotency-skipped), so a LATER live pick would arrive as an\n            # ambiguous seed instead of a clean departure.\n            echo = FanEcho(FAN_AUTO, FAN_AUTO)\n        return replace(latch, held=False, echo=echo)\n\n    seeding = echo.last is None\n    departed = not seeding and not echo.own(observed)\n    if not (seeding or departed):\n        # A standing hold: no gesture this cycle, so nothing changes.\n        return latch\n\n    # A seed at exactly the speed the ladder would command right now is our\n    # own boost speed echoing back, not a manual pick -> adopt it and keep\n    # driving. A DEPARTURE never adopts: every slider move is a hold.\n    if seeding:\n        if seed_is_own_idle(observed, act, limits):\n            # Baseline stamped so a slow echo of this token isn't a\n            # departure; the return-to-auto write then proceeds.\n            return replace(latch, held=False, echo=FanEcho(observed, observed))\n        idx = seed_matches_boost(observed, act, delta, limits)\n        if idx is not None:\n            return adopt(latch, observed, idx)\n\n    # Seed latched (not at auto, not our rung); a departure always latches.\n    return hold_at(latch, observed)\n\n\ndef fan_record(latch: FanLatch, observed: str | None) -> FanRecord:\n    \"\"\"What a start needs back of a head's hold and echo memory (``FanHold.record``).\n\n    ``observed`` is the speed the head shows (None for none, or no head). ``held``\n    is ``FanLatch.holds``. ``older`` is the older writes in the order written, so\n    a last-two speed written earlier too keeps that place and a late report of it\n    isn't read as the last write. The trailing last two are left out: the restore\n    puts them back. So is a leading auto, which the head is showing or has\n    passed, and which MXZ won't write again while it's showing.\n\n    ``older`` is empty for a head showing the last write with no older speed\n    left to read as an echo. That's what a prompt head looks like, and its record\n    keeps its old shape. A head in the same state that was really showing an\n    earlier write of that speed loses its place (F1's limits,\n    docs/formal/PARKED-FINDINGS.md).\n    \"\"\"\n    echo = latch.echo\n    older = list(echo.older)\n    if not echo.older_commands() and observed == echo.last:\n        older = []\n    for written in (echo.last, echo.prior):\n        if older and older[-1] == written:\n            older.pop()\n    while older and older[0] == FAN_AUTO:\n        del older[0]\n    return FanRecord(\n        held=latch.holds,\n        last=echo.last,\n        prior=echo.prior,\n        on_pending=latch.on_pending,\n        older=tuple(older),\n    )\n\n\ndef fan_read(\n    latch: FanLatch,\n    observed: str | None,\n    act: str,\n    *,\n    modes: Sequence[str] | None,\n    limits: FanLimits,\n) -> FanLatch:\n    \"\"\"The manual fan hold read on a head MXZ sends no fan, and nothing written.\n\n    A head paused for an open door or window (``act`` off), or one a person runs in dry\n    under Allow Dry (``act`` dry). ``observed`` is the speed it shows and ``modes`` the\n    speeds it lists; the report was passed to ``latch.echo.caught_up`` first. MXZ set no\n    speed there, so the read has no delta. With boost off, no fan list, no ``auto`` in it,\n    or no speed showing, nothing is read.\n    \"\"\"\n    if not limits.boost or not modes or FAN_AUTO not in modes or observed is None:\n        return latch\n    return observe_fan(latch, observed, act, 0.0, limits)\n\n\ndef fan_step(\n    latch: FanLatch,\n    observed: str | None,\n    act: str,\n    delta: float,\n    *,\n    modes: Sequence[str] | None,\n    limits: FanLimits,\n) -> tuple[FanLatch, str | None]:\n    \"\"\"One delivery's fan boost step at a head: the latch it leaves, and the token to write.\n\n    ``observed`` is the speed the head shows and ``modes`` the speeds it lists;\n    the report was passed to ``latch.echo.caught_up`` first. ``act`` is the mode\n    the delivery runs and ``delta`` how far the room is off target. None is no\n    write. The caller rolls the echo memory as it writes the token\n    (``FanEcho.wrote``).\n\n    With boost off, no fan list, no ``auto`` in it, or no speed showing, nothing\n    is read or written. Otherwise ``observe_fan`` reads the hold first, because\n    a hold also stops the hand-back to ``auto``. A head held gets no write. A\n    head in cool or heat outside eco idle gets the ladder rung for ``delta``,\n    from the rung it keeps; fan_only or eco idle gets ``auto`` and drops the\n    rung; off drops the rung and gets no write. No write goes out for a token\n    the head doesn't list (the ladder could otherwise only ratchet up on a head\n    with no way back down) or one it already shows.\n    \"\"\"\n    if not limits.boost or not modes or FAN_AUTO not in modes or observed is None:\n        return latch, None\n    latch = observe_fan(latch, observed, act, delta, limits)\n    if latch.held is True:\n        return latch, None\n    if act in (MODE_COOL, MODE_HEAT) and not limits.eco_idle:\n        rung = fan_for_delta(\n            delta=delta,\n            cur_idx=0 if latch.rung is None else latch.rung,\n            up_at=limits.up_at,\n            down_at=limits.down_at,\n            max_idx=limits.ceiling,\n        )\n        latch = replace(latch, rung=rung)\n        token = FAN_LADDER[rung]\n    elif act == MODE_FAN_ONLY or limits.eco_idle:\n        latch = replace(latch, rung=None)\n        token = FAN_AUTO\n    else:\n        return replace(latch, rung=None), None\n    if token not in modes or observed == token:\n        return latch, None\n    return latch, token\n\n\n@dataclass(frozen=True, slots=True)\nclass EchoCaughtUp:\n    \"\"\"The head's report of a speed put MXZ's earlier fan writes behind it\n    (``FanEcho.caught_up`` changed the memory): the hold is published.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass KeepLatch:\n    \"\"\"The hold :func:`fan_step` left is kept, and published.\"\"\"\n\n    latch: FanLatch\n\n\n@dataclass(frozen=True, slots=True)\nclass WroteFan:\n    \"\"\"``token`` is remembered as MXZ's own (``FanEcho.wrote``), and published, before it goes\n    out: the head's report of it can come back while the write is running.\"\"\"\n\n    token: str\n\n\n@dataclass(frozen=True, slots=True)\nclass SendFan:\n    \"\"\"The head is sent ``set_fan_mode`` with ``token``.\"\"\"\n\n    token: str\n\n\ntype BoostStep = EchoCaughtUp | KeepLatch | WroteFan | SendFan\n\n\ndef fan_boost(\n    latch: Callable[[], FanLatch],\n    observed: str | None,\n    act: str,\n    delta: float,\n    *,\n    boost: bool,\n    modes: Sequence[str] | None,\n    limits: Callable[[], FanLimits],\n) -> tuple[BoostStep, ...]:\n    \"\"\"A local delivery's fan boost step at a head (``\"boost\"``, or the hand-back), in order.\n\n    ``observed`` is the speed the head shows (None with no state) and ``modes`` the speeds it\n    lists. Nothing at all with fan boost off (``boost``); with no fan list or no ``auto`` in it\n    (no way to release a hold or return a satisfied head to auto: the head's fan is left\n    entirely alone, as a ladder could only ratchet it up); or with no speed showing (a head\n    still loading: nothing to reconcile a restored hold or the latch against, and a write would\n    override a speed nobody can see; restored truth stays pending and a standing hold stands).\n\n    Otherwise the head's hold (``latch``, read now) takes the report first\n    (``FanEcho.caught_up``), then :func:`fan_step` decides, with ``limits`` read after that. Its\n    hold is kept, and a token to send is remembered before it is sent.\n    \"\"\"\n    if not boost or not modes or FAN_AUTO not in modes or observed is None:\n        return ()\n    held = latch()\n    caught = held.echo.caught_up(observed)\n    held, token = fan_step(held, observed, act, delta, modes=modes, limits=limits())\n    return (\n        *((EchoCaughtUp(),) if caught else ()),\n        KeepLatch(held),\n        *((WroteFan(token), SendFan(token)) if token is not None else ()),\n    )\n\n\ndef reconcile_restored_hold(\n    latch: FanLatch, observed: str, held: bool, act: str, limits: FanLimits\n) -> FanLatch:\n    \"\"\"Consume a restored hold truth (``held``) against the first speed the head reports.\n\n    The Fan-auto switch restores the held/not-held bool and, for a zone that\n    was not held, the previous incarnation's command/observation baselines\n    (already in the echo memory, see ``restored``). The token itself is\n    always taken from the OBSERVED head.\n\n    * observed \"auto\": released — including a hold the user let go of during\n      the outage. Restored command memory stays, so a late report of a\n      pre-restart token is still read as our own echo, not a departure.\n    * held: still held, at the observed token (same token: the hold simply\n      survived; different non-auto token: the user moved the hold during the\n      outage — theirs either way).\n    * not held: boost was driving. A token boost could never have written —\n      outside the ladder, above the ceiling — holds, even if remembered:\n      memory can contain user picks. An in-ceiling ladder token is ours\n      when there is no memory, when it is remembered, or when the\n      room is idling in fan_only under idle_action fan_only (#25): such a\n      head can report a speed of its own while idling, and a hold there never\n      self-corrects because the room never reads a clean \"auto\". Otherwise\n      (an active room, another idle action) a nonmatching token\n      conservatively holds; a stale dump can cause a false hold, so this is\n      NOT proof of a manual gesture. The documented edge: a pick made while\n      HA itself was down is indistinguishable from residue wherever the\n      token is read as ours. Never a fixed-point guess: a mere change of\n      delta is not a manual gesture. An active room resumes the ladder from\n      the observed rung.\n    \"\"\"\n    echo = latch.echo\n    if observed == FAN_AUTO:\n        if echo.last is None:\n            echo = FanEcho(FAN_AUTO, FAN_AUTO)\n        return replace(latch, held=False, echo=echo)\n    if held:\n        return hold_at(latch, observed)\n    remembered = echo.own(observed)\n    ours = (\n        observed in FAN_LADDER\n        and FAN_LADDER.index(observed) <= limits.ceiling\n        and (\n            echo.last is None\n            or remembered\n            or (act == MODE_FAN_ONLY and limits.idle_action == IDLE_ACTION_FAN_ONLY)\n        )\n    )\n    if not ours:\n        return hold_at(latch, observed)\n    if not remembered:\n        # Baseline stamped so a slow echo of this token isn't a departure.\n        echo = FanEcho(observed, observed)\n    rung = latch.rung\n    if act in (MODE_COOL, MODE_HEAT) and observed in FAN_LADDER:\n        rung = min(FAN_LADDER.index(observed), limits.ceiling)\n    return replace(latch, held=False, echo=echo, rung=rung)\n\n\ndef hold_at(latch: FanLatch, observed: str) -> FanLatch:\n    \"\"\"Latch the head at the token it reports, as a STANDING hold.\n\n    Records the held token as the command baseline so the zone stays held\n    next cycle (the same trick a Fan auto off uses). Without this\n    the identical reading re-reads as a fresh seed/departure every cycle and\n    the latch decision is re-litigated forever — which is how the v2.18.0\n    \"standing merge\" removal was defeated for slider holds: the departure\n    branch kept re-running the max handback, so a max hold still released\n    itself on drift.\n    \"\"\"\n    return replace(latch, held=True, echo=FanEcho(observed, observed))\n\n\ndef adopt(latch: FanLatch, observed: str, rung: int) -> FanLatch:\n    \"\"\"Release the latch and adopt the observed token into the boost's memory.\n\n    Rolls prior, records the observed token as the last command, and pins\n    the rung so the ladder continues from where the head actually is: the\n    natural ramp proceeds idempotently under DOWN_AT hysteresis, and the head\n    doesn't read as a fresh departure and re-latch once the ladder steps off\n    that token. ``rung`` is the ladder index to resume from — the seed adopt\n    passes the index it matched; the Fan-auto switch passes the ceiling, which\n    only ever ramps down from there.\n    \"\"\"\n    last = latch.echo.last\n    return replace(\n        latch, held=False, echo=FanEcho(observed, observed if last is None else last), rung=rung,\n    )\n\n\ndef seed_matches_boost(observed: str, act: str, delta: float, limits: FanLimits) -> int | None:\n    \"\"\"Ladder index if a seed reading is our own boost speed, else ``None``.\n\n    The latch seeds from whatever the head reports on the first compute after\n    a restart, and a head boost had been driving is reporting OUR speed — not\n    a manual pick. Latching that parks the zone silently (Fan auto reads OFF,\n    boost stops driving it) until a human hands it back, after EVERY restart\n    that catches a room conditioning — including the weekly update.\n\n    So: while actively conditioning, if the observed token is a rung the\n    ladder would STAY on at the current delta — a fixed point under the\n    UP_AT/DOWN_AT hysteresis — it's a speed the boost could legitimately\n    have parked the head at, so it's ours: adopt it and keep driving. The\n    hysteresis makes this a BAND, not a single value (as a room closes in,\n    DOWN_AT holds the fan a rung or two above what a cold read would pick;\n    that is the boost's normal resting state, not a manual hold). Checking\n    only the cold read (cur_idx=0) — as v2.19.0/beta.18 did — matched just\n    the bottom rung of that band, so a restart mid-ramp-down still parked\n    the head as \"held\".\n\n    A real manual hold that predates the restart reads as a token OUTSIDE\n    the band — above the boost ceiling, or past a hysteresis edge — so it\n    still latches. The accepted tradeoff: a hold deliberately placed inside\n    the band is indistinguishable from the boost's own speed and is lost to\n    adoption. Only reachable on a seed — a departure is always a hold.\n    \"\"\"\n    if act not in (MODE_COOL, MODE_HEAT) or limits.eco_idle:\n        return None\n    if observed not in FAN_LADDER:\n        return None\n    obs_idx = FAN_LADDER.index(observed)\n    if obs_idx > limits.ceiling:\n        return None  # above the boost ceiling: never ours\n    idx = fan_for_delta(\n        delta=delta,\n        cur_idx=obs_idx,\n        up_at=limits.up_at,\n        down_at=limits.down_at,\n        max_idx=limits.ceiling,\n    )\n    return obs_idx if idx == obs_idx else None\n\n\ndef seed_is_own_idle(observed: str, act: str, limits: FanLimits) -> bool:\n    \"\"\"True if a seed with no restore data is our own fan_only idle (#25).\n\n    idle_action=\"fan_only\" drives a satisfied head to \"auto\" every cycle,\n    yet a real head can report a concrete token while idling that way.\n    Seeding that as a hold never self-corrects: unlike an active seed, the\n    zone never leaves fan_only for a clean \"auto\" reading. So on a restart\n    of an ESTABLISHED coordinator — this entry's own coordinator switch\n    restored ON (it was running before), and the entry at least\n    ``IDLE_SEED_MIN_ENTRY_AGE`` old — an in-ceiling ladder token boost\n    could have written is read as ours. A first-ever compute (fresh\n    install or re-added entry: nothing restored ON; or a first live\n    enable, however long after install) keeps honoring a pre-install\n    manual pick (S10). The accepted edge: a pick made while the zone\n    idled in fan_only, followed by a restart that loses the Fan-auto\n    restore, is indistinguishable and is not held.\n    \"\"\"\n    if (\n        act != MODE_FAN_ONLY\n        or limits.idle_action != IDLE_ACTION_FAN_ONLY\n        or not limits.resumed\n        or observed not in FAN_LADDER\n        or FAN_LADDER.index(observed) > limits.ceiling\n    ):\n        return False\n    return limits.age is not None and limits.age >= timedelta(seconds=IDLE_SEED_MIN_ENTRY_AGE)\n\n\ndef restored(\n    latch: FanLatch,\n    held: bool,\n    *,\n    last: str | None,\n    prior: str | None,\n    older: Iterable[str],\n    on_pending: bool,\n    ceiling: int,\n) -> FanLatch:\n    \"\"\"A start's record of the head's hold, waiting for the first speed it reports.\n\n    It replaces any record restored before. ``held`` is the pre-restart truth,\n    which ``observe_fan`` reconciles against the observed head state.\n\n    ``last``/``prior`` are command/adopted-observation baselines from the\n    previous incarnation, when the record carried them. For a zone that was\n    NOT held they re-arm the echo tolerance across the restart, so a head that\n    reports a pre-restart token late — after a provisional ``auto``, or once\n    its missing speed arrives — is read as our own echo, not as a departure. A\n    held zone's memory is the held token itself: the seed records it from the\n    observed head, so nothing is carried for it (a hold released during the\n    outage stays released, and a later non-auto report on it is a new hold\n    either way).\n\n    ``older`` is the same for a head that was further behind at the stop\n    (``FanHold.older_record``). Only speeds boost could write are taken back:\n    anything else is no echo.\n\n    Only a strictly parsed fresh not-held record can carry an explicit waiting\n    Fan auto on (``on_pending``). It adopts ONE first usable report, including\n    a user token above the ceiling, just like a live Fan auto on; it proves no\n    own echo.\n    \"\"\"\n    echo = FanEcho()\n    if not held and last is not None:\n        # Memory includes adopted user tokens, not just our commands.\n        # S11b wins even when an impossible token is reported AFTER a\n        # provisional auto. Such a token cannot arm restored echo tolerance.\n        def eligible(token: str) -> str:\n            if token in FAN_LADDER and FAN_LADDER.index(token) <= ceiling:\n                return token\n            return FAN_AUTO\n\n        command = eligible(last)\n        before = eligible(last if prior is None else prior)\n        kept = [token for token in older if eligible(token) == token]\n        last_two = dict.fromkeys((before, command))\n        echo = FanEcho(command, before, (*kept, *last_two) if kept else ())\n    return replace(\n        latch, echo=echo, restored=held, on_pending=on_pending is True and held is False,\n    )\n\n\ndef fan_auto(\n    latch: FanLatch, observed: str | None, on: bool, ceiling: int\n) -> tuple[FanLatch, bool]:\n    \"\"\"A Fan auto gesture against the speed the head shows: the new latch, and whether it acted.\n\n    ON  -> release the latch and ADOPT the head's current observed token into\n           the boost memory, so the still-at-manual-speed head doesn't read as\n           a fresh departure and immediately re-latch. With no speed showing it\n           waits for the first one (``on_pending``).\n    OFF -> latch at whatever the head is doing right now (a deliberate hold).\n           Latching \"at auto\" is meaningless, so an observed ``auto`` is\n           ignored (the switch stays ON), and so is no speed with no Fan auto\n           on waiting. With one waiting, OFF cancels it without guessing a\n           token: the first non-auto report becomes the held speed, and an\n           observed auto still releases as usual. The echo memory is seeded\n           with the observed token so the observation treats the hold as\n           already accounted for, not a new departure. The hold sticks at any\n           speed, max included, until the switch (or an observed ``auto``)\n           releases it.\n\n    A gesture replaces a restored truth still waiting for a speed. With fan\n    boost disabled the fan machinery is inert: OFF still records the latch (it\n    simply has no effect until boost is re-enabled), and ON still clears it —\n    the switch stays honest either way. Ignored, nothing is published.\n    \"\"\"\n    if on:\n        latch = replace(latch, restored=None, on_pending=False)\n        if observed is not None:\n            return adopt(latch, observed, ceiling), True\n        return replace(latch, held=False, on_pending=True), True\n    if observed is None or observed == FAN_AUTO:\n        if observed is None and latch.on_pending:\n            return replace(latch, on_pending=False, restored=True, held=True), True\n        if observed == FAN_AUTO:\n            latch = replace(latch, restored=None)\n        return latch, False\n    last = latch.echo.last\n    return replace(\n        latch,\n        restored=None,\n        echo=FanEcho(observed, observed if last is None else last),\n        held=True,\n        on_pending=False,\n    ), True\n",
 "custom_components/mxz_coordinator/grid.py": "\"\"\"What a head accepts, and what a local head is sent for a command. No Home Assistant.\n\n``heads.HeadGrid`` reads a head's live entity into a :class:`Grid`: its native band and unit,\nits setpoint step, and the system's unit, target step and clamp band. The grid holds the\nrules every caller reads it by: the band the head will accept in the system unit\n(:meth:`Grid.safe_band`), a command clamped into it, the bounds a room's target may take, and\nwhether a setpoint is already where a command would put it on the head's own grid.\n:func:`local_calls` is the service calls a local head gets for one command; ``LocalDriver``\nsends them in order. :func:`convert` is Home Assistant's ``TemperatureConverter`` for °C and\n°F (``tests/test_grid.py`` compares the two on every supported release).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport math\nfrom collections.abc import Mapping\nfrom dataclasses import dataclass\nfrom typing import Any, NamedTuple\n\nfrom .const import MODE_COOL, MODE_HEAT\nfrom .logic import as_float\nfrom .units import UNIT_C, UNIT_F, snap_to_step\n\n# ClimateEntityFeature.TARGET_TEMPERATURE_RANGE.\n_RANGE = 2\n\n\ndef convert(value: float, from_unit: str, to_unit: str) -> float:\n    \"\"\"A temperature in ``from_unit`` in ``to_unit``, as Home Assistant converts it.\n\n    The same unit returns the value as it is. °C and °F only: anything else raises\n    ``ValueError``.\n    \"\"\"\n    if from_unit == to_unit:\n        return value\n    if from_unit == UNIT_C and to_unit == UNIT_F:\n        return value * 1.8 + 32.0\n    if from_unit == UNIT_F and to_unit == UNIT_C:\n        return (value - 32.0) / 1.8\n    raise ValueError(f\"no conversion from {from_unit!r} to {to_unit!r}\")\n\n\n@dataclass(frozen=True, slots=True)\nclass Grid:\n    \"\"\"What one head accepts, read off its live entity (#10).\n\n    ``native``: the head's unrounded native (min, max, unit), None if unknown. ``shown_band``:\n    the min and max its state shows, in the system unit (None for no state, an edge of None\n    for one it lacks), read only when ``native`` is unknown. ``native_step`` and\n    ``native_unit``: its setpoint step and unit (0.0 and None when it has none readable).\n    ``system_unit``, ``target_step``, ``clamp_min`` and ``clamp_max``: MXZ's.\n    \"\"\"\n\n    system_unit: str\n    target_step: float\n    clamp_min: float\n    clamp_max: float\n    native: tuple[float, float, str] | None = None\n    shown_band: tuple[float | None, float | None] | None = None\n    native_step: float = 0.0\n    native_unit: str | None = None\n\n    def safe_band(self) -> tuple[float, float] | None:\n        \"\"\"The head's operating band as system-unit edges it will ACCEPT.\n\n        Convert the head's native limits into the system unit and snap the ceiling DOWN / the\n        floor UP to our step, so every edge round-trips back through HA's unit conversion\n        still inside the native band (78.8 °F -> 78 °F, which converts to 25.56 °C <= the\n        26.0 °C native max). For a head already native to the system unit this is a no-op on\n        whole values. Falls back to the display-rounded band the state shows when the native\n        one isn't known (keeps the common same-unit case correct).\n        \"\"\"\n        temp_unit = self.system_unit\n        native = self.native\n        lo: float | None\n        hi: float | None\n        if native is not None:\n            nmin, nmax, nunit = native\n            lo = convert(nmin, nunit, temp_unit)\n            hi = convert(nmax, nunit, temp_unit)\n        else:\n            if self.shown_band is None:\n                return None\n            lo, hi = self.shown_band\n            if lo is None or hi is None:\n                return None\n        step = self.target_step or 1.0\n        # +/-1e-9 absorbs float noise so an exact 26.0/0.5 doesn't fall a step.\n        safe_low = math.ceil(lo / step - 1e-9) * step\n        safe_high = math.floor(hi / step + 1e-9) * step\n        if native is not None and nunit != temp_unit:\n            # Verify each snapped edge round-trips through the SAME conversion HA's validator\n            # performs: the noise epsilon can promote an edge a float-ulp past the true native\n            # limit (a 78.8 °F native max in a °C system snaps to 26.0 °C, which converts back\n            # to 78.800…01). One extra step inward always clears a 1-ulp overshoot.\n            if convert(safe_high, temp_unit, nunit) > nmax:\n                safe_high -= step\n            if convert(safe_low, temp_unit, nunit) < nmin:\n                safe_low += step\n        if safe_low > safe_high:\n            return None  # degenerate band (narrower than a step) -> don't clamp\n        return (safe_low, safe_high)\n\n    def clamp(self, low: float, high: float) -> tuple[float, float]:\n        \"\"\"Clamp (low, high) into the head's accept-able band; pass through if unknown.\"\"\"\n        band = self.safe_band()\n        if band is None:\n            return (low, high)\n        safe_low, safe_high = band\n        return (\n            min(max(low, safe_low), safe_high),\n            min(max(high, safe_low), safe_high),\n        )\n\n    def target_bounds(self) -> tuple[float, float]:\n        \"\"\"UI setpoint bounds for a zone: [clamp_min, clamp_max] narrowed to the head's own\n        accept-able band, so the number/thermostat facade never offers a target the head\n        would reject (#10). If the head band is unknown or disjoint from the clamp band, fall\n        back to the plain clamp band.\n        \"\"\"\n        lo, hi = float(self.clamp_min), float(self.clamp_max)\n        band = self.safe_band()\n        if band is None:\n            return (lo, hi)\n        safe_low, safe_high = band\n        lo, hi = max(lo, safe_low), min(hi, safe_high)\n        if lo > hi:\n            return (float(self.clamp_min), float(self.clamp_max))\n        return (lo, hi)\n\n    def already_at(self, reported: float | None, desired: float) -> bool:\n        \"\"\"True if sending ``desired`` would leave the head's setpoint unchanged.\n\n        A head can only hold setpoints on its own native grid. A °C-native 0.5 °C head\n        (ESPHome CN105) in a °F system latches 18.0 °C for a commanded 64 °F (17.78 °C) and\n        reports it back as 64.4 °F, displayed 64.5 °F. That is the closest it can get to\n        64 °F, so comparing whole °F never matches and every cycle re-sends a value that\n        changes nothing.\n\n        So compare on the head's grid: convert ``desired`` to the native unit and snap it to\n        the native step (the value the head will latch); the head already holds it when\n        ``reported`` converts back to within half a native step. The reported value's display\n        rounding (at most 0.14 °C at 0.5 °F precision) and the raw commanded value the head\n        publishes just before its echo (at most 0.22 °C from the grid for a whole °F) both\n        stay inside that half step; a head one native step off does not. With no known native\n        unit/step, fall back to half our own step.\n\n        Known limits: this assumes the head rounds to the nearest step, as the CN105 does; a\n        head that truncated to its grid would still re-send. It also assumes the entity\n        displays at 0.5 °F or finer; at whole-°F display precision a one-step move on a\n        0.5 °C head can read as already there (the old whole-°F check had the same blind\n        spot).\n        \"\"\"\n        if reported is None:\n            return False\n        step, unit = self.native_step, self.native_unit\n        if step <= 0 or unit not in (UNIT_C, UNIT_F):\n            return abs(reported - desired) < self.target_step / 2\n        # Half up, as the CN105 firmware rounds (round() is half to even).\n        latched = math.floor(convert(desired, self.system_unit, unit) / step + 0.5) * step\n        held = convert(reported, self.system_unit, unit)\n        return abs(held - latched) < step / 2\n\n    def target_for_setpoint(self, shown: float) -> float:\n        \"\"\"The target on our step that leaves this head where a person put it.\n\n        18.5 °C on a CN105 reads 65.5 °F here, whose nearest whole °F is 66, and 66 °F would\n        move the head on to 19 °C. So the nearest target the head would hold ``shown`` for, a\n        step either side if need be; with none, the nearest.\n        \"\"\"\n        step = self.target_step or 1.0\n        nearest = snap_to_step(shown, step)\n        return next(\n            (\n                target for target in (nearest, nearest - step, nearest + step)\n                if self.already_at(shown, target)\n            ),\n            nearest,\n        )\n\n\nclass Call(NamedTuple):\n    \"\"\"One climate service call to a head: the service and its data (no entity id).\"\"\"\n\n    service: str\n    data: dict[str, Any]\n\n\ndef _mode_and_setpoints(\n    act: str, mode: str | None, setpoints: dict[str, float], *, combined: bool\n) -> tuple[Call, ...]:\n    \"\"\"Cool/heat and its setpoint(s) the way this head will honor them.\n\n    An ESPHome head (the CN105) applies the hvac_mode HA passes along inside set_temperature,\n    so it gets one combined call. Other integrations may drop it: Kumo Cloud heads through\n    comfort_HA parked in fan_only never woke. So a mode change on those goes first as its own\n    set_hvac_mode, then set_temperature carries only the setpoint(s). A failed mode call\n    raises before the setpoint write and the next compute retries. ``combined`` is a head\n    that takes the one call (ESPHome, or one with no registry entry, which can't be\n    identified); a head already in the mode always does.\n    \"\"\"\n    if mode == act or combined:\n        return (Call(\"set_temperature\", {\"hvac_mode\": act, **setpoints}),)\n    return (Call(\"set_hvac_mode\", {\"hvac_mode\": act}), Call(\"set_temperature\", setpoints))\n\n\ndef local_calls(\n    act: str,\n    low: float,\n    high: float,\n    *,\n    mode: str | None,\n    attributes: Mapping[str, Any] | None,\n    grid: Grid,\n    combined: bool,\n) -> tuple[Call, ...]:\n    \"\"\"The calls a local head is sent for ``act`` with setpoints (``low``, ``high``), in order.\n\n    ``mode`` and ``attributes`` are what the head shows (None for no state). None at all when\n    the head already shows the command on its own grid.\n\n    Heat and cool are clamped, edge by edge, to what THIS head will actually accept: the\n    global clamp band can exceed an individual head's, and HA validates set_temperature by\n    converting our (system-unit) value into the head's NATIVE unit and range-checking there,\n    so a °C-native head whose native max is 26.0 °C rejects 79 °F (26.11 °C) even though it\n    REPORTS max_temp = 79 °F (78.8 rounded up). Clamping in the head's native band (rounded\n    toward the safe interior) keeps a head-exceeding target from erroring every cycle /\n    degrading the zone (#10). A head without a setpoint range (single-setpoint, common on MXZ\n    indoor units) rejects target_temp_low/high, so it gets the one setpoint it accepts (#6):\n    the clamped room target, the high edge in cool and the low edge in heat. fan_only and off\n    are a set_hvac_mode alone (a bare temperature throws).\n    \"\"\"\n    if act in (MODE_COOL, MODE_HEAT):\n        low, high = grid.clamp(low, high)\n        features = int(attributes.get(\"supported_features\") or 0) if attributes is not None else 0\n        if not features & _RANGE:\n            setpoint = high if act == MODE_COOL else low\n            cur = as_float(attributes.get(\"temperature\")) if attributes is not None else None\n            if mode == act and grid.already_at(cur, setpoint):\n                return ()\n            return _mode_and_setpoints(act, mode, {\"temperature\": setpoint}, combined=combined)\n        cur_low = as_float(attributes.get(\"target_temp_low\")) if attributes is not None else None\n        cur_high = as_float(attributes.get(\"target_temp_high\")) if attributes is not None else None\n        if mode == act and grid.already_at(cur_low, low) and grid.already_at(cur_high, high):\n            return ()\n        return _mode_and_setpoints(\n            act, mode, {\"target_temp_low\": low, \"target_temp_high\": high}, combined=combined,\n        )\n    if mode == act:\n        return ()\n    return (Call(\"set_hvac_mode\", {\"hvac_mode\": act}),)\n",
 "custom_components/mxz_coordinator/head_writes.py": "\"\"\"MXZ's memory of its own mode and setpoint writes to one head, field by field. No Home Assistant.\n\nEach field MXZ writes (``HEAD_WRITE_FIELDS``) has its own ``logic.HeadWriteMemory``. A write is\nremembered just before it goes out (:func:`issue_steps`, :func:`remember_writes`), a call the head\nrefuses takes back what it counted (:func:`writes_refused`), a head's report passes the writes\nbefore it (:func:`writes_caught_up`), and a person's change the adopt hold took replaces what the\nhead last showed (:func:`writes_pressed`). A report of a setpoint compares with a write on the head's own\ngrid (``grid.Grid.already_at``); the mode compares as it is.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport operator\nfrom collections.abc import Callable, Collection, Mapping, MutableMapping\nfrom dataclasses import dataclass\nfrom typing import Any\n\nfrom .const import UNAVAILABLE_STATES\nfrom .grid import Grid\nfrom .logic import HeadWriteMemory, as_float\n\nHEAD_WRITE_MODE = \"hvac_mode\"\nHEAD_WRITE_FIELDS = (HEAD_WRITE_MODE, \"temperature\", \"target_temp_low\", \"target_temp_high\")\n\n\ndef field_shown(mode: str | None, attributes: Mapping[str, Any] | None, name: str) -> Any:\n    \"\"\"What a head showing ``mode`` and ``attributes`` shows for this field; None if nothing\n    usable (no state, or unavailable).\"\"\"\n    if mode is None or mode in UNAVAILABLE_STATES:\n        return None\n    if name == HEAD_WRITE_MODE:\n        return mode\n    return as_float((attributes or {}).get(name))\n\n\ndef same_as(name: str, grid: Grid) -> Callable[[Any, Any], bool]:\n    \"\"\"How a report of this field compares with a write of it.\"\"\"\n    return operator.eq if name == HEAD_WRITE_MODE else grid.already_at\n\n\ndef remember_writes(\n    memories: MutableMapping[str, HeadWriteMemory],\n    payload: Mapping[str, Any],\n    *,\n    mode: str | None,\n    attributes: Mapping[str, Any] | None,\n    grid: Grid,\n    size: int,\n) -> dict[str, Any]:\n    \"\"\"Keep each field a call's ``payload`` writes, while the head shows ``mode`` and\n    ``attributes``; return the fields that counted a copy (``HeadWriteMemory.wrote``), which a\n    refusal takes back.\"\"\"\n    counted: dict[str, Any] = {}\n    for name in HEAD_WRITE_FIELDS:\n        if name in payload:\n            remembered = memories.setdefault(name, HeadWriteMemory(size))\n            if remembered.wrote(\n                payload[name], field_shown(mode, attributes, name), same_as(name, grid),\n            ):\n                counted[name] = payload[name]\n    return counted\n\n\ndef writes_refused(memories: Mapping[str, HeadWriteMemory], counted: Mapping[str, Any]) -> None:\n    \"\"\"The head refused a call: the copies it counted (:func:`remember_writes`) will never\n    show (``HeadWriteMemory.refused``).\"\"\"\n    for name, value in counted.items():\n        if name in memories:\n            memories[name].refused(value)\n\n\n@dataclass(frozen=True, slots=True)\nclass RememberWrites:\n    \"\"\"MXZ's write memory keeps each mode and setpoint field ``payload`` writes\n    (:func:`remember_writes`), and what it counted, for a refusal.\"\"\"\n\n    payload: Mapping[str, Any]\n\n\n@dataclass(frozen=True, slots=True)\nclass SendCall:\n    \"\"\"The call goes to the head. One the head refuses never shows: the copies\n    :class:`RememberWrites` counted are taken back (:func:`writes_refused`).\"\"\"\n\n\ndef issue_steps(payload: Mapping[str, Any]) -> tuple[RememberWrites, SendCall]:\n    \"\"\"One call to a head with ``payload``, in order: its writes are remembered first, because\n    the head's report can arrive while the call runs, then it is sent.\"\"\"\n    return (RememberWrites(payload), SendCall())\n\n\ndef writes_caught_up(\n    memories: Mapping[str, HeadWriteMemory],\n    *,\n    old_mode: str | None,\n    old_attributes: Mapping[str, Any] | None,\n    mode: str | None,\n    attributes: Mapping[str, Any] | None,\n    grid: Grid,\n) -> None:\n    \"\"\"A head's report: the writes before what it shows now are behind it for good\n    (``HeadWriteMemory.caught_up``), for each field it shows; ``moved`` is whether the field\n    changed since the report before.\"\"\"\n    for name, memory in memories.items():\n        shown = field_shown(mode, attributes, name)\n        if shown is not None:\n            memory.caught_up(\n                shown, same_as(name, grid),\n                moved=shown != field_shown(old_mode, old_attributes, name),\n            )\n\n\ndef writes_pressed(\n    memories: Mapping[str, HeadWriteMemory],\n    names: Collection[str],\n    *,\n    mode: str | None,\n    attributes: Mapping[str, Any] | None,\n    grid: Grid,\n) -> None:\n    \"\"\"A person's change the adopt hold took (``planner.AdoptEnd.seen``): for each of these\n    fields, what the head shows replaces what it last showed (``HeadWriteMemory.pressed``).\"\"\"\n    for name in names:\n        if name in memories:\n            memories[name].pressed(field_shown(mode, attributes, name), same_as(name, grid))\n\n\ndef write_is_own(\n    memories: Mapping[str, HeadWriteMemory], name: str, shown: Any, grid: Grid\n) -> bool:\n    \"\"\"Whether MXZ's own writes of this field explain what the head shows.\"\"\"\n    memory = memories.get(name)\n    return memory is not None and memory.own(shown, same_as(name, grid))\n",
 "custom_components/mxz_coordinator/logic.py": "\"\"\"Pure decision math for MXZ Coordinator — no Home Assistant dependency.\n\nMirrors the Jinja in the YAML package's ``sensor.mxz_plan`` and the setpoint/action\nmath in ``script.mxz_coordinate``. Kept HA-free so the validated truth table can be\nunit-tested directly.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport math\nimport operator\nfrom collections import deque\nfrom collections.abc import Callable\nfrom dataclasses import dataclass, replace\nfrom typing import Any\n\nfrom .const import (\n    COMFORT_MISSING,\n    COMFORT_NOT_A_NUMBER,\n    COMFORT_NOT_SET,\n    COMFORT_NUMBER,\n    COMFORT_OFF,\n    COMFORT_ON,\n    COMFORT_ONOFF_DOMAINS,\n    COMFORT_STALE,\n    COMFORT_UNAVAILABLE,\n    COMFORT_UNKNOWN,\n    ECO_COOL_HIGH,\n    ECO_COOL_LOW,\n    ECO_HEAT_HIGH,\n    ECO_HEAT_LOW,\n    ENGAGE_SATISFIED,\n    EVIDENCE_HA_WRITE,\n    EVIDENCE_SAMPLE_TIMESTAMP,\n    FLOOR_REARM_SECONDS,\n    HEALTH_AWAITING,\n    HEALTH_CADENCE_UNKNOWN,\n    HEALTH_HEALTHY,\n    HEALTH_INVALID,\n    HEALTH_STALE,\n    MODE_COOL,\n    MODE_FAN_ONLY,\n    MODE_HEAT,\n    MODE_OFF,\n    OPENING_CLOSED,\n    OPENING_CLOSING,\n    OPENING_OPENING,\n    OPENING_OVERRIDDEN,\n    OPENING_PAUSED,\n    OPENING_PAUSED_STATES,\n    STALE_MISSED_REPORTS,\n    VOTE_EXPIRED,\n    VOTE_LIVE,\n    VOTE_STALE,\n    VOTE_UNKNOWN,\n)\n\n# Home Assistant's own state strings (homeassistant.const), spelled out here\n# so this module stays importable without Home Assistant.\nSTATE_ON = \"on\"\nSTATE_OFF = \"off\"\nSTATE_UNAVAILABLE = \"unavailable\"\nSTATE_UNKNOWN = \"unknown\"\n\n\ndef room_call(\n    *,\n    temp: float,\n    target: float,\n    enabled: bool,\n    eco: bool,\n    sensor_ok: bool,\n    band: float | None = None,\n    eco_cool_max: float,\n    eco_heat_min: float,\n    neutral: str,\n    heat_lockout: bool = False,\n    heat_lockout_floor: float = 0.0,\n    cool_lockout: bool = False,\n    cool_lockout_ceiling: float = 200.0,\n    heat_band: float | None = None,\n    cool_band: float | None = None,\n    heat_target: float | None = None,\n    cool_target: float | None = None,\n) -> str:\n    \"\"\"Per-room call for one band (demand uses S/'neutral', engage uses D/'satisfied').\n\n    Mirrors the primary/secondary_demand and primary/secondary_engage attributes.\n\n    ``band`` is how far the room may sit off target either way. ``heat_band``\n    (below target) and ``cool_band`` (above target) replace it for one side\n    each; a side left None uses ``band``. Every side needs a value.\n\n    ``heat_target`` / ``cool_target`` are a dual-setpoint room's Heat to and\n    Cool to: the heat side measures from the first and the cool side from the\n    second. Either left None uses ``target``, so a single-target room is the\n    case where both equal ``target``.\n\n    ``heat_lockout`` holds off the heat call (the room idles instead of heating — e.g.\n    to let passive solar warm it in summer) UNLESS the room has dropped below\n    ``heat_lockout_floor``, a safety floor so a genuinely cold room still gets heat.\n    ``cool_lockout`` is the mirror for the cold season: it holds off the cool call\n    (let the room drift down on its own) UNLESS it rises above ``cool_lockout_ceiling``.\n    The eco extremes are unaffected; the two lockouts are independent.\n    \"\"\"\n    heat_band = band if heat_band is None else heat_band\n    cool_band = band if cool_band is None else cool_band\n    if heat_band is None or cool_band is None:\n        raise TypeError(\"room_call needs band, or both heat_band and cool_band\")\n    if not enabled:\n        return MODE_OFF\n    if not sensor_ok:\n        return neutral\n    # The comparisons read the same edges the plan shows (call_edges), so the\n    # displayed start points and the decision cannot disagree.\n    heat_below, cool_above = call_edges(\n        target=target, heat_band=heat_band, cool_band=cool_band, eco=eco,\n        heat_target=heat_target, cool_target=cool_target,\n        eco_cool_max=eco_cool_max, eco_heat_min=eco_heat_min,\n        heat_lockout=heat_lockout, heat_lockout_floor=heat_lockout_floor,\n        cool_lockout=cool_lockout, cool_lockout_ceiling=cool_lockout_ceiling,\n    )\n    if temp > cool_above:\n        return MODE_COOL\n    if temp < heat_below:\n        return MODE_HEAT\n    return neutral\n\n\ndef call_edges(\n    *,\n    target: float,\n    heat_band: float,\n    cool_band: float,\n    eco: bool,\n    eco_cool_max: float,\n    eco_heat_min: float,\n    heat_lockout: bool,\n    heat_lockout_floor: float,\n    cool_lockout: bool,\n    cool_lockout_ceiling: float,\n    heat_target: float | None = None,\n    cool_target: float | None = None,\n) -> tuple[float, float]:\n    \"\"\"The two edges :func:`room_call` compares a reading to: (heat_below, cool_above).\n\n    An enabled room with a usable reading calls cool iff ``temp > cool_above``\n    (checked first), else heat iff ``temp < heat_below``. One function decides\n    both the call and the start points the plan shows, so they can't drift.\n\n    * Eco: the eco extremes, whatever the target, bands, or lockouts.\n    * Otherwise ``heat_target - heat_band`` / ``cool_target + cool_band``,\n      where each per-side target left None is ``target`` (a single-target\n      room; a dual-setpoint room passes its Heat to and Cool to).\n    * A lockout moves its side's edge out to the safety line: cool is held off\n      while ``temp <= cool_lockout_ceiling`` and heat while\n      ``temp >= heat_lockout_floor``, and with strict comparisons \"past the\n      comfort edge AND past the line\" is exactly \"past the farther of the two\".\n      The comfort edge is max()'s/min()'s FIRST argument, so a NaN on either\n      side resolves as the original two comparisons did.\n\n    Holding cool off can only leave a reading in the heat region if the two\n    regions overlap: the cool comfort edge below the heat comfort edge\n    (negative bands, or a Heat to above Cool to). The cool-first order\n    answers \"hold\" for a reading past the cool edge, so there heat starts\n    only AT OR BELOW the cool comfort edge. As a strict edge that is the\n    next double above it, which the plan's six-place rounding shows as the\n    cool edge itself. No caller passes this: drift is clamped positive, the\n    demand band is at least the drift, the latch passes 0, and a\n    dual-setpoint room's Heat to is always below its Cool to.\n    \"\"\"\n    if eco:\n        return eco_heat_min, eco_cool_max\n    heat_from = target if heat_target is None else heat_target\n    cool_from = target if cool_target is None else cool_target\n    heat_below = heat_from - heat_band\n    cool_above = cool_from + cool_band\n    if cool_lockout and cool_above < heat_below:\n        heat_below = math.nextafter(cool_above, math.inf)\n    if heat_lockout:\n        heat_below = min(heat_below, heat_lockout_floor)\n    if cool_lockout:\n        cool_above = max(cool_above, cool_lockout_ceiling)\n    return heat_below, cool_above\n\n\ndef engage_with_latch(\n    *,\n    prior: str | None,\n    band: float | None = None,\n    neutral: str,\n    heat_band: float | None = None,\n    cool_band: float | None = None,\n    **call_kwargs: Any,\n) -> str:\n    \"\"\"Per-room engage with run-to-target hysteresis.\n\n    The engage deadband exists so a satisfied room COASTS instead of flip-\n    flopping — it was never meant to truncate the approach. Without a latch,\n    a room cooling toward 63 would stop at 64 (target + band) and never reach\n    the number the user actually set.\n\n    * Not engaged (``prior`` is None): a room must drift PAST ``band`` to\n      engage — unchanged behavior.\n    * Engaged (``prior`` is cool|heat): the room runs all the way TO its\n      target — satisfied means exactly the number the user set. Crossing the target — or a lockout / eco / disable /\n      sensor dropout, all still evaluated via :func:`room_call` — disengages\n      it back to ``neutral`` to coast until it drifts past ``band`` again.\n    * A direction flip while engaged (overshoot, opened window) never\n      whiplashes: anything other than continuing in ``prior``'s direction\n      disengages to ``neutral`` first.\n\n    Eco mode bypasses the latch entirely (protection extremes are already a\n    wide band; run-to-extreme would defeat their purpose).\n\n    ``heat_band`` / ``cool_band`` split ``band`` by side exactly as in\n    :func:`room_call`. They only move where a run STARTS: every run still ends\n    at the target, whichever side's drift started it.\n\n    A dual-setpoint room passes ``heat_target`` / ``cool_target`` through\n    ``call_kwargs``: a heat run then ends at Heat to and a cool run at Cool\n    to (band 0 measured from each side's own target), then the room coasts.\n    \"\"\"\n    if prior in (MODE_COOL, MODE_HEAT) and not call_kwargs.get(\"eco\"):\n        # Engaged phase: band 0 on both sides — the room runs exactly TO its\n        # target, then coasts. The re-engage drift (``band``, or its per-side\n        # split) is the only tunable here.\n        raw = room_call(band=0.0, neutral=neutral, **call_kwargs)\n        if raw == prior or raw == MODE_OFF:\n            return raw\n        return neutral  # target reached / lockout / direction flip -> coast\n    return room_call(\n        band=band, heat_band=heat_band, cool_band=cool_band, neutral=neutral,\n        **call_kwargs,\n    )\n\n\ndef freshness_window(\n    *,\n    report_interval: Any,\n    max_age: Any,\n    startup_grace: Any,\n) -> tuple[float, float] | None:\n    \"\"\"Resolve one sensor's ``(maximum_age, startup_grace)``, or None.\n\n    Same duration unit in and out (the coordinator passes minutes). ``None``\n    means the sensor's cadence is UNKNOWN — no age cutoff applies to it, which\n    is the honest default for a change-only or uncontracted source. There is no\n    universal fallback interval to invent one from.\n\n    * ``report_interval`` (P) alone -> ``3P``: stale at the third due instant.\n    * an explicit ``max_age`` wins over that derivation, and must be at least\n      P: a window narrower than one report would park a healthy room on its\n      first quiet interval.\n    * ``max_age`` alone is enough: a documented maximum age needs no cadence.\n    * ``startup_grace`` defaults to the resolved maximum age.\n\n    An input that is set must be a real, finite, positive number. A profile\n    with one that is not — or with a maximum age shorter than its interval —\n    is INVALID as a whole, and an invalid profile is no profile: ``None``,\n    exactly as if nothing had been configured. Nothing in it is read as\n    unset, raised, rounded or otherwise coerced into a cutoff the person did\n    not write (the caller reports the rejection once).\n    \"\"\"\n    durations: list[float | None] = []\n    for value in (report_interval, max_age, startup_grace):\n        if value is not None and (value := _positive(value)) is None:\n            return None\n        durations.append(value)\n    interval, window, grace = durations\n    if window is None:\n        window = None if interval is None else interval * STALE_MISSED_REPORTS\n    elif interval is not None and window < interval:\n        return None\n    if window is None:\n        return None\n    return (window, window if grace is None else grace)\n\n\ndef evidence_contract(\n    *,\n    basis: Any,\n    sample_timestamp_attribute: Any,\n    sample_sequence_attribute: Any,\n) -> tuple[str, str | None, bool] | None:\n    \"\"\"Resolve one sensor's evidence basis, or None when nothing is trusted.\n\n    Returns ``(basis, marker_attribute, marker_is_a_time)``. ``None`` is both\n    the default and the answer to every unrecognised or unusable declaration:\n    an untrusted source shows its age and is never enforced, however precise\n    its configured cadence is.\n\n    ``ha_state_write`` is a claim about the SOURCE, not about Home Assistant:\n    it may be declared only where every accepted write — including the first\n    one after setup or reload — is a current acquisition. ``sample_timestamp``\n    needs exactly one marker attribute named; naming both is ambiguous, and an\n    ambiguous marker is not trustworthy evidence.\n    \"\"\"\n    if basis == EVIDENCE_HA_WRITE:\n        return (EVIDENCE_HA_WRITE, None, False)\n    if basis == EVIDENCE_SAMPLE_TIMESTAMP:\n        stamp = _attribute(sample_timestamp_attribute)\n        sequence = _attribute(sample_sequence_attribute)\n        if stamp is not None and sequence is None:\n            return (EVIDENCE_SAMPLE_TIMESTAMP, stamp, True)\n        if sequence is not None and stamp is None:\n            return (EVIDENCE_SAMPLE_TIMESTAMP, sequence, False)\n    return None\n\n\ndef _attribute(name: Any) -> str | None:\n    \"\"\"``name`` as a usable attribute name, else None.\"\"\"\n    return name if isinstance(name, str) and name else None\n\n\ndef sample_evidence(\n    *,\n    marker: float | None,\n    last: float | None,\n    now: float,\n    receipt: float | None,\n    marker_is_a_time: bool,\n) -> tuple[float | None, float | None]:\n    \"\"\"One marker observation -> ``(marker to remember, evidence time)``.\n\n    Pure, and the whole of the marker contract. ``marker`` is the trusted\n    marker carried by this write (a POSIX sample time, or a sample sequence\n    number, compared exactly as the number it is — an integer sequence is\n    never rounded through a float); ``last`` is the last marker accepted for\n    this sensor.\n\n    * a missing, equal or older marker is a cached or replayed write: it is\n      diagnostic only, moves no deadline and recovers nothing;\n    * a sample TIME later than the evaluation clock is not evidence either —\n      it is a clock fault, and accepting it would grant a free window;\n    * an accepted sample time IS the evidence time, so a genuinely old sample\n      arrives already aged and recovers nothing;\n    * a sample SEQUENCE has no wall-clock meaning, so its evidence time is the\n      HA receipt time of the write that carried the advance. The first\n      sequence seen is a baseline only: nothing has advanced yet.\n    \"\"\"\n    if marker is None or (last is not None and marker <= last):\n        return (last, None)\n    if marker_is_a_time:\n        if marker > now:\n            return (last, None)\n        return (marker, marker)\n    if last is None or receipt is None:\n        return (marker, None)\n    return (marker, min(receipt, now))\n\n\ndef finite_number(value: Any) -> bool:\n    \"\"\"Whether a stored value is a finite number (a bool is not one).\"\"\"\n    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)\n\n\ndef as_float(value: Any) -> float | None:\n    \"\"\"Best-effort float() of a state attribute for idempotency comparison.\"\"\"\n    try:\n        return float(value)\n    except (ValueError, TypeError):\n        return None\n\n\ndef bounded(value: float | None, default: float, bounds: tuple[float, float]) -> float:\n    \"\"\"A stored setting inside ``bounds``; None (not set) is ``default``.\"\"\"\n    if value is None:\n        return float(default)\n    return float(min(max(value, bounds[0]), bounds[1]))\n\n\ndef _positive(value: Any) -> float | None:\n    \"\"\"``value`` as a finite positive float, else None (unset or unusable).\"\"\"\n    if isinstance(value, bool) or not isinstance(value, (int, float)):\n        return None\n    number = float(value)\n    if not math.isfinite(number) or number <= 0:\n        return None\n    return number\n\n\ndef sensor_health(\n    *,\n    valid: bool,\n    max_age: float | None,\n    evidence_age: float | None,\n    in_grace: bool,\n) -> str:\n    \"\"\"Classify one room sensor. Pure; the whole freshness decision lives here.\n\n    Evaluation order is validity, then basis, then age — M13's value handling\n    precedes every age question, so freshness can never make a bad value good.\n\n    ``max_age`` is None for every sensor that is not enforcement-capable: no\n    trusted evidence basis, or no maximum age. Such a room is\n    ``cadence_unknown`` — its age is shown and no cutoff exists for it.\n\n    ``evidence_age`` is how long ago this incarnation witnessed a qualifying\n    report, or ``None`` when it has witnessed none. A report qualifies when it\n    is a state write of a valid value that this incarnation saw; it is FRESH —\n    the word every recovery rule turns on — when its own deadline is still in\n    the future, so a backlog flush delivering an already-aged report recovers\n    nothing. A negative age is a write stamped in the future: not evidence.\n\n    ``in_grace`` is the bounded startup grace. It makes a configured room\n    provisionally eligible while it awaits its first witnessed report; it never\n    claims the current value is fresh, and it never excuses an invalid one.\n    \"\"\"\n    if not valid:\n        return HEALTH_INVALID\n    if max_age is None:\n        return HEALTH_CADENCE_UNKNOWN\n    if evidence_age is not None and 0.0 <= evidence_age < max_age:\n        return HEALTH_HEALTHY\n    if in_grace:\n        return HEALTH_AWAITING\n    return HEALTH_STALE\n\n\ndef season_lockouts(\n    *, outdoor_high: float | None, heat_above: float, cool_below: float\n) -> tuple[bool, bool]:\n    \"\"\"Derive (heat_lockout, cool_lockout) from the local outdoor daily-high temp.\n\n    The decision is driven by *local weather*, not the calendar: pass the forecast\n    daily high (from a weather entity) or an outdoor temperature reading.\n\n    * high >= ``heat_above`` -> warm season -> heat_lockout on (don't actively heat).\n    * high <= ``cool_below`` -> cold season -> cool_lockout on (don't actively cool).\n    * in between (shoulder season) -> neither -> normal heat + cool.\n\n    The gap between the two thresholds is the hysteresis band — the forecast has to\n    swing across the whole shoulder zone to flip a lockout, so it won't chatter.\n    ``None`` (no signal — weather unavailable) yields no lockout (safe: normal auto).\n    \"\"\"\n    if outdoor_high is None:\n        return (False, False)\n    if outdoor_high >= heat_above:\n        return (True, False)\n    if outdoor_high <= cool_below:\n        return (False, True)\n    return (False, False)\n\n\ndef shared_mode(\n    *,\n    demands: list[str],\n    current: str,\n    allowed: bool,\n    resting: str | None = None,\n) -> str:\n    \"\"\"Choose the shared mode (cool|heat). Mirrors the mxz_plan state template.\n\n    ``demands`` is one demand per zone in PRIORITY ORDER (index 0 = highest).\n    ``current`` must already be normalized to cool|heat (cold start -> cool).\n    ``allowed`` is the hysteresis gate. In a standoff (some zones calling cool\n    while others call heat) the HIGHEST-PRIORITY calling zone wins — the N-zone\n    generalization of \"the primary room wins\".\n\n    ``resting`` biases the mode used when NO room is calling. ``None`` (or any\n    non cool|heat value) keeps the original behavior — rest at ``current`` (the\n    last called mode). Set it to cool|heat to always settle there when idle; a\n    genuine opposite demand still flips the mode (the bias only changes the\n    neutral fallback, gated by the same hysteresis as any other flip).\n    \"\"\"\n    rest = resting if resting in (MODE_COOL, MODE_HEAT) else current\n    any_cool = MODE_COOL in demands\n    any_heat = MODE_HEAT in demands\n    standoff = any_cool and any_heat\n\n    if standoff:\n        proposed = next(\n            (d for d in demands if d in (MODE_COOL, MODE_HEAT)), current\n        )\n    elif any_cool:\n        proposed = MODE_COOL\n    elif any_heat:\n        proposed = MODE_HEAT\n    else:\n        proposed = rest\n\n    still = (current == MODE_COOL and any_cool) or (current == MODE_HEAT and any_heat)\n    if proposed != current and allowed and (standoff or not still):\n        return proposed\n    return current\n\n\n# Demand.priority tiers: lower sorts first / wins a standoff. These are the\n# ONLY thing that encodes \"a real demand beats a vote\" -- it falls out of\n# comparing (PRIORITY_VOTE, i) > (PRIORITY_DEMAND, j) for any i, j, not a\n# hardcoded rule, which is what lets PRIORITY_SAFETY override either kind\n# without a special case (see arbitrate()'s docstring).\nPRIORITY_SAFETY = -1\nPRIORITY_DEMAND = 0\nPRIORITY_VOTE = 1\n# A tripped freeze floor (a disabled room's heat at its floor) outranks every\n# other want, a PRIORITY_SAFETY one included: freeze first. A tripped overheat\n# ceiling sits at PRIORITY_SAFETY with its room index, so it settles against a\n# safety room by room order. Nothing else ever carries this tier.\nPRIORITY_FLOOR_HEAT = -2\n\n\n@dataclass(frozen=True)\nclass Demand:\n    \"\"\"One zone's current want for the shared compressor's direction this tick.\n\n    ``direction`` is :data:`MODE_COOL`, :data:`MODE_HEAT`, or ``None`` (wants nothing).\n    ``priority`` is ``(tier, configured_index)``; lower sorts first.\n    ``read_only`` is True for an advisory want (a vote): it is never sent to the\n    voting head, though a safety vote that wins can still park another room's\n    head (see :class:`Grant`). False for a coordinated room's own demand.\n    ``boost`` is the room's Comfort priority (0 = none; higher sorts first\n    within the same tier). :func:`arbitrate` ignores it at PRIORITY_SAFETY and\n    above, and reads anything not a positive finite number as 0.\n    \"\"\"\n\n    direction: str | None\n    priority: tuple[int, int]\n    read_only: bool = False\n    boost: float = 0.0\n\n\ndef comfort_boost(demand: Demand) -> float:\n    \"\"\"The Comfort priority :func:`arbitrate` actually sorts ``demand`` by.\n\n    0 for any entry at PRIORITY_SAFETY or above (a freeze floor, a Safety\n    priority room, an overheat ceiling): those settle by room order alone,\n    whatever a caller put on them. 0 too for anything that isn't a positive\n    finite number, so a boost can raise an entry and never push it down.\n    \"\"\"\n    boost = demand.boost\n    if demand.priority[0] <= PRIORITY_SAFETY or isinstance(boost, bool):\n        return 0.0\n    if not isinstance(boost, (int, float)) or not math.isfinite(boost) or boost <= 0:\n        return 0.0\n    return float(boost)\n\n\ndef _rank(demand: Demand) -> tuple[int, float, int]:\n    \"\"\"Sort key: (tier, -comfort priority, room index); lower sorts first.\"\"\"\n    return (demand.priority[0], -comfort_boost(demand), demand.priority[1])\n\n\ndef comfort_priority(\n    domain: str | None,\n    state: str | None,\n    *,\n    age: float | None = None,\n    stale_after: float | None = None,\n) -> tuple[float, str]:\n    \"\"\"A Comfort priority entity's reading as ``(boost, status)``.\n\n    ``domain`` is the entity's domain, or None when no entity is set.\n    ``state`` is its state string, or None when the entity doesn't exist.\n    ``age`` is seconds since its state last changed (None = unknown, read as\n    fresh). ``stale_after`` is the stale limit in seconds (None = no limit).\n\n    An on/off entity (``COMFORT_ONOFF_DOMAINS``) is 1 while exactly \"on\" and\n    0 otherwise; an \"on\" older than ``stale_after`` is 0 and ``stale``. Any\n    other domain is read as a number: its own value, where negative is 0 and\n    NaN, infinity or text are 0 and ``not_a_number``. The stale limit never\n    applies to a number. Unavailable, unknown and missing are 0. A reading\n    can only ever raise a room, never lower it.\n    \"\"\"\n    if domain is None:\n        return 0.0, COMFORT_NOT_SET\n    if state is None:\n        return 0.0, COMFORT_MISSING\n    if state == STATE_UNAVAILABLE:\n        return 0.0, COMFORT_UNAVAILABLE\n    if state == STATE_UNKNOWN:\n        return 0.0, COMFORT_UNKNOWN\n    if domain in COMFORT_ONOFF_DOMAINS:\n        if state != STATE_ON:\n            return 0.0, COMFORT_OFF\n        if stale_after is not None and age is not None and age >= stale_after:\n            return 0.0, COMFORT_STALE\n        return 1.0, COMFORT_ON\n    try:\n        value = float(state)\n    except (TypeError, ValueError):\n        return 0.0, COMFORT_NOT_A_NUMBER\n    if not math.isfinite(value):\n        return 0.0, COMFORT_NOT_A_NUMBER\n    return max(value, 0.0), COMFORT_NUMBER\n\n\ndef comfort_stale_in(\n    domain: str | None,\n    state: str | None,\n    *,\n    age: float | None,\n    stale_after: float | None,\n) -> float | None:\n    \"\"\"Seconds until a counting \"on\" goes stale, or None when nothing will.\n\n    The recheck moment for :func:`comfort_priority`: positive only for an\n    on/off entity reading \"on\" with a known age under a set limit.\n    \"\"\"\n    if (\n        domain not in COMFORT_ONOFF_DOMAINS or state != STATE_ON\n        or stale_after is None or age is None or age >= stale_after\n    ):\n        return None\n    return stale_after - age\n\n\n@dataclass(frozen=True)\nclass Grant:\n    \"\"\"The arbitrated outcome for one tick.\n\n    ``read_only`` is True only when THIS tick's answer differs from what it\n    would be considering commanding Demands alone (an advisory want is the\n    reason the answer moved, not merely that one happens to be active) AND\n    the ordinary vote gate was open: no commanding Demand had a direction\n    and no room was engaged. Such a flip runs no coordinated head into a\n    reversal, so it is exempt from the dwell stamp. A safety vote that moves\n    the answer while a coordinated room is calling or engaged mid-run parks\n    that room's head, so it reads False and is stamped like any other flip.\n    Once the answer settles (nothing is actively changing it any more), this\n    reads False again, even while a vote is still what the settled answer\n    agrees with -- there is nothing left to exempt from the dwell clock once\n    nothing is proposing a change.\n\n    ``by_safety`` is True while a PRIORITY_SAFETY (or freeze floor) Demand\n    with a direction is active and that direction is the answer. It does not\n    claim the safety tier changed the answer: the same answer may follow from\n    order or the dwell alone.\n    \"\"\"\n\n    direction: str\n    read_only: bool\n    by_safety: bool\n\n\ndef arbitrate(\n    demands: list[Demand],\n    *,\n    engaged: bool,\n    current: str,\n    allowed: bool,\n    resting: str | None = None,\n    running: bool = False,\n) -> Grant:\n    \"\"\":func:`shared_mode`, generalized over a priority-ordered Demand list.\n\n    Reproduces the original ``shared_mode_with_votes``'s precedence exactly\n    as the degenerate case where every Demand sits at PRIORITY_DEMAND or\n    PRIORITY_VOTE and none at PRIORITY_SAFETY. What it fixes: today's \"a\n    real demand always fully preempts every vote, unconditionally\" was a\n    hardcoded wall, not a priority relationship -- so a hands-off zone's\n    safety-tier vote could never preempt an enabled zone's merely-comfort\n    demand, no matter how urgently it needed to. Here a PRIORITY_SAFETY\n    Demand -- from EITHER a coordinated room or a hands-off vote -- outranks\n    every ordinary Demand structurally, because ``(-1, i) < (0, j)`` always,\n    not via a special case, and participates regardless of ``engaged`` or\n    whether anything else is commanding.\n\n    ``engaged`` mirrors the original gate's other half: a room mid-run\n    toward its target (its own demand back inside the band, but still\n    engaged) must not have the mode taken from it by a mere vote, even\n    though its demand itself has gone quiet. It only ever suppresses an\n    ORDINARY vote (PRIORITY_VOTE, read_only) -- never a safety one.\n\n    ``running`` is narrower: a room is engaged in ``current`` itself, so its\n    head is running toward its target in the shared mode. Resting mode then\n    waits: with nothing calling, the mode stays ``current`` until that run\n    ends, and only then rests. It changes nothing else: a real call for the\n    other mode or a safety want still decides as before (an ordinary vote is\n    already shut out, since a running room is engaged), and a person's pick\n    never comes through here. A room engaged in the other mode is not\n    running (its head is parked) and does not keep the mode.\n\n    A tripped floor is one more commanding Demand: a freeze floor at\n    PRIORITY_FLOOR_HEAT (ahead of every safety want), an overheat ceiling at\n    PRIORITY_SAFETY. A standoff goes to the first ranked direction, so heat\n    from a floor beats cool from a ceiling whatever their rooms' order, and\n    two trips of one kind settle by room order.\n\n    Comfort priority (``Demand.boost``) orders entries inside one tier only:\n    the key is ``(tier, -boost, room index)``, so a boosted lower room's\n    demand wins a standoff against an unboosted higher one, and a boosted\n    vote wins among votes. It never crosses a tier, so a boosted vote still\n    can't beat a real demand, and it is ignored at PRIORITY_SAFETY and above\n    (:func:`comfort_boost`). It changes only which direction is proposed;\n    ``allowed`` still holds every flip. All boosts 0 is exactly the old order.\n    \"\"\"\n    if running:\n        resting = None  # rest where the run is until it ends\n    ranked = sorted(demands, key=_rank)\n    commanding = [d for d in ranked if not d.read_only]\n    safety_votes = [\n        d for d in ranked if d.read_only and d.priority[0] <= PRIORITY_SAFETY\n    ]\n    ordinary_votes = [\n        d for d in ranked if d.read_only and d.priority[0] > PRIORITY_SAFETY\n    ]\n    commanding_silent = not any(d.direction for d in commanding)\n    gate_open = commanding_silent and not engaged\n    active = sorted(\n        commanding + safety_votes + (ordinary_votes if gate_open else []),\n        key=_rank,\n    )\n    full = shared_mode(\n        demands=[d.direction for d in active if d.direction],\n        current=current, allowed=allowed, resting=resting,\n    )\n    by_safety = any(\n        d.direction == full and d.priority[0] <= PRIORITY_SAFETY for d in active\n    )\n    if not any(d.read_only and d.direction for d in active):\n        return Grant(direction=full, read_only=False, by_safety=by_safety)\n    plain = shared_mode(\n        demands=[d.direction for d in active if d.direction and not d.read_only],\n        current=current, allowed=allowed, resting=resting,\n    )\n    # Exempt from the dwell stamp only when the vote gate was open: no\n    # commanding room calling AND none still engaged mid-run. A safety vote\n    # that takes the mode from a calling room or from an engaged run that is\n    # coasting inside its band parks a running head -- a real reversal the\n    # coordinator causes -- so it stamps like any other flip.\n    read_only = full != plain and gate_open\n    return Grant(direction=full, read_only=read_only, by_safety=by_safety)\n\n\n# One door/window reading: open, closed, or neither (unknown).\nOPEN_READ = \"open\"\nCLOSED_READ = \"closed\"\n\n\ndef opening_reading(state: str | None) -> str | None:\n    \"\"\"An opening entity's state as a reading: on is open, off is closed.\n\n    Anything else (unavailable, unknown, a missing entity, any other text) is\n    no reading at all, and no reading never starts a pause.\n    \"\"\"\n    if state == STATE_ON:\n        return OPEN_READ\n    if state == STATE_OFF:\n        return CLOSED_READ\n    return None\n\n\ndef opening_state(\n    *,\n    raw: str | None,\n    since: float,\n    now: float,\n    open_delay: float,\n    close_delay: float,\n    prior: str,\n    override: bool,\n) -> str:\n    \"\"\"A room's door/window state now. Pure; the whole pause decision lives here.\n\n    ``raw`` is the reading (:func:`opening_reading`), held since ``since``\n    (seconds, the same clock as ``now``). ``prior`` is the state the last\n    evaluation found. ``override`` is a person running the room anyway: a\n    manual change on its head during a pause, or its Window Override switch.\n\n    * Open for the open delay pauses (PAUSED); open for less is OPENING, and\n      a close then is CLOSED again with no pause.\n    * A paused room that reads closed is CLOSING until it has read closed for\n      the close delay, then CLOSED (resume). Opening again while CLOSING is\n      PAUSED, and the close delay starts over at the next closed reading.\n    * No reading (unavailable, unknown, missing) never starts a pause: an\n      unpaused room is CLOSED. A paused room stays PAUSED: no reading is not\n      proof that the opening closed.\n    * An override is OVERRIDDEN while the opening is not closed: the room is\n      never paused then. A closed reading ends it at once (CLOSED), so the\n      next opening pauses again. An override with no pause to override (the\n      room was CLOSED or OPENING, and there is no reading) leaves the room\n      CLOSED.\n    \"\"\"\n    paused = prior in OPENING_PAUSED_STATES\n    if raw == CLOSED_READ:\n        if paused and not override:\n            return OPENING_CLOSED if now - since >= close_delay else OPENING_CLOSING\n        return OPENING_CLOSED\n    if override:\n        if raw == OPEN_READ or paused or prior == OPENING_OVERRIDDEN:\n            return OPENING_OVERRIDDEN\n        return OPENING_CLOSED\n    if raw == OPEN_READ:\n        if paused:\n            return OPENING_PAUSED\n        return OPENING_PAUSED if now - since >= open_delay else OPENING_OPENING\n    return OPENING_PAUSED if paused else OPENING_CLOSED\n\n\ndef opening_due(\n    *, state: str, since: float, open_delay: float, close_delay: float\n) -> float | None:\n    \"\"\"When ``state`` next changes by time alone, or None when it can't.\n\n    The end of the open delay while OPENING, the end of the close delay while\n    CLOSING (the room's resume time); nothing else changes without a reading.\n    \"\"\"\n    if state == OPENING_OPENING:\n        return since + open_delay\n    if state == OPENING_CLOSING:\n        return since + close_delay\n    return None\n\n\nclass HeadWriteMemory:\n    \"\"\"MXZ's own writes of one setting to one head, in order, until reports pass them.\n\n    The rule of the fan memory (F1, docs/formal/PARKED-FINDINGS.md), for a head's\n    mode and each of its setpoints: a head shows its writes in order, so a report\n    of a remembered value is MXZ's own and ends every write older than it. A report\n    of a value not remembered is a person's. The first value is what the head last\n    showed, and the rest are writes it hasn't shown yet.\n\n    Each value also counts its copies: the writes of it the head hasn't been seen\n    to show. A head that takes a copy while it already shows the value shows\n    nothing new, so a copy is known to be behind the head only once a report\n    passes it.\n\n    ``same(reported, written)`` compares a report with a write. A head can hold a\n    setpoint only on its own grid, so for a setpoint it isn't equality. Its costs\n    are F1's: while a head is behind, a person's pick of one of these older values\n    reads as MXZ's own; a value written twice stays remembered, with the writes\n    between, until a report rules them out; and a value MXZ wrote again before the\n    head showed it keeps its last copy, so once a person's value replaces it, a\n    press back to it reads as MXZ's own until a later write of MXZ's shows.\n    \"\"\"\n\n    def __init__(self, size: int) -> None:\n        self._size = size\n        self._entries: deque[list[Any]] = deque(maxlen=size)  # [value, copies]\n\n    @property\n    def values(self) -> tuple[Any, ...]:\n        \"\"\"What is remembered, oldest first.\"\"\"\n        return tuple(value for value, _ in self._entries)\n\n    def record(self) -> list[list[Any]]:\n        \"\"\"What a store keeps: each value with its copies, oldest first.\"\"\"\n        return [list(entry) for entry in self._entries]\n\n    @classmethod\n    def restored(cls, size: int, record: Any) -> HeadWriteMemory | None:\n        \"\"\"The memory ``record`` keeps, or None if it isn't one.\"\"\"\n        if not isinstance(record, list) or not record:\n            return None\n        memory = cls(size)\n        for entry in record[-size:]:\n            if not (\n                isinstance(entry, list) and len(entry) == 2\n                and (isinstance(entry[0], str) or finite_number(entry[0]))\n                and type(entry[1]) is int and entry[1] >= 0\n            ):\n                return None\n            memory._entries.append([entry[0], entry[1]])\n        return memory\n\n    def wrote(\n        self, value: Any, shown: Any = None, same: Callable[[Any, Any], bool] = operator.eq\n    ) -> bool:\n        \"\"\"A write is going out while the head shows ``shown`` (None: nothing known).\n\n        What the head shows before a write stays remembered until it reports a\n        later one: until then the same report can come again. A rewrite of the\n        last value is one more copy of it, not a new place in the order. A write\n        of what the head shows adds nothing when the shown value is the last one\n        remembered and no value before it counts a copy: as far as the memory\n        knows, nothing else of MXZ's is still to come, so the head shows nothing\n        new for it and no report could ever count it off. In every other case it\n        counts a copy, as any write does. Returns whether the write counted a\n        copy.\n        \"\"\"\n        if shown is not None and not self.own(shown, same):\n            self.seen(shown)\n        if (\n            shown is not None and same(shown, value) and same(shown, self._entries[-1][0])\n            and not any(copies for _, copies in list(self._entries)[:-1])\n        ):\n            return False\n        if self._entries and self._entries[-1][0] == value:\n            self._entries[-1][1] += 1\n        else:\n            self._entries.append([value, 1])\n        return True\n\n    def refused(self, value: Any) -> None:\n        \"\"\"The head refused a write that counted a copy: it will never show that copy.\n\n        The copy is taken back, so no press of the value waits on it. The value\n        stays remembered, as the base kept it: a refused call can still have\n        gone through, and its late report is MXZ's own.\n        \"\"\"\n        for entry in reversed(self._entries):\n            if entry[0] == value and entry[1]:\n                entry[1] -= 1\n                return\n\n    def own(self, reported: Any, same: Callable[[Any, Any], bool] = operator.eq) -> bool:\n        \"\"\"Whether this report can be one of MXZ's writes (or the value before them).\"\"\"\n        return any(same(reported, value) for value, _ in self._entries)\n\n    def caught_up(\n        self, reported: Any, same: Callable[[Any, Any], bool] = operator.eq, *, moved: bool = True\n    ) -> None:\n        \"\"\"A report of a remembered value: the writes older than it are behind the head.\n\n        A value written twice counts as its earliest write left: this report may\n        be that one, with the writes after it still coming. One copy of it is\n        shown now, unless the report shows the first value remembered and didn't\n        move the setting (``moved``), which shows nothing new.\n        \"\"\"\n        if not self.own(reported, same):\n            return\n        passed = False\n        while not same(reported, self._entries[0][0]):\n            self._entries.popleft()\n            passed = True\n        if (passed or moved) and self._entries[0][1]:\n            self._entries[0][1] -= 1\n\n    def seen(self, shown: Any) -> None:\n        \"\"\"The head shows a value of a person's: it replaces the last one it showed.\n\n        The writes it hasn't shown yet stay, since they can still arrive after\n        it, and so does the value it showed while copies of it are still to come.\n        \"\"\"\n        if self._entries and (not self._entries[0][1] or len(self._entries) == self._size):\n            self._entries.popleft()\n        self._entries.appendleft([shown, 0])\n\n    def pressed(self, shown: Any, same: Callable[[Any, Any], bool] = operator.eq) -> None:\n        \"\"\"A person's change the hold adopted: what the head shows now replaces what it last\n        showed (``seen``), unless nothing is shown or MXZ's own writes explain it.\"\"\"\n        if shown is not None and not self.own(shown, same):\n            self.seen(shown)\n\n\nclass HeadSight:\n    \"\"\"What MXZ last saw of one head, and since when it has been out of sight.\n\n    Adapted from ``Zone.observe`` / ``lost`` / ``status`` / ``vote`` in\n    @csingley's ha-climate-zone-sequencer, commit f911e4a (``models.py``,\n    MIT License; see NOTICE). The idea is his: out of sight, a head keeps its\n    last-known vote for a time limit, because it may still be running that\n    want and nothing can steer it either way, so dropping the vote at once\n    would let a sibling contend blind. Past the limit the vote lapses.\n\n    What differs here: the caller's clock is monotonic seconds; the boundary\n    is half-open, as for a sensor's freshness cutoff (expired AT the limit,\n    not after it); and a head not seen since MXZ started is timed from that\n    start (:meth:`status` reads unknown until then, expired after), because\n    every head is briefly unavailable while Home Assistant boots.\n\n    It also keeps what the head was last seen running, for a room that votes\n    by action (:meth:`action_vote`). That filter is MXZ's own extension of\n    Chris's observed vote, not part of his design. ``settle`` is how long\n    after a mode change a report of running is unconfirmed (see\n    :meth:`observe`); 0 confirms every report at once.\n    \"\"\"\n\n    def __init__(self, started: float, started_wall: float, settle: float = 0.0) -> None:\n        self.mode: str | None = None  # the state last seen; None if never seen\n        # The head's own hvac_action last seen; None if it reported none.\n        self.action: str | None = None\n        # Whether it has reported one at all since MXZ started: a head that\n        # has can't fall back to its mode by dropping it for one report.\n        self.reports_action = False\n        self.lost_at: float | None = started  # monotonic; None while in sight\n        self.lost_wall: float | None = started_wall  # the same moment, for display\n        # The heat or cool the head was last seen running in its own mode,\n        # and when it was first seen no longer running it (None while it runs).\n        self.ran: str | None = None\n        self.stopped_at: float | None = None\n        self.settle = settle\n        # When its mode was last seen to change (monotonic); None if never.\n        self.changed_at: float | None = None\n\n    def observe(self, mode: str, action: Any = None, now: float | None = None) -> None:\n        \"\"\"Record the head's state and its own hvac_action, seen just now.\n\n        A run counts only when the action agrees with the mode: heating in\n        heat, cooling in cool. A head's action lags a mode change, so it can\n        read heating in off or cooling in fan_only for a poll; such a\n        contradiction is never a run, so it can't start, extend, or refresh\n        one. A head that leaves the mode it ran in ends that run, hold and\n        all; one that stops running in the same mode starts its hold, timed\n        from the first sighting that shows it stopped. ``now`` is monotonic;\n        without it a stop has no time to start a hold from, so it ends the\n        run instead (no hold, no vote). A hold already running keeps its own\n        start either way.\n\n        A head's action can also lag the other way: just after a mode change\n        it can read running in its new mode, carried over from the run\n        before. So a run that starts within ``settle`` of the mode last\n        changing is unconfirmed: no run, no vote, and stopping it starts no\n        hold. It counts only if a sighting at or past the end of that window\n        (:meth:`settles_in`) still shows it running. A run in the mode it\n        already ran in, held or not, counts at once (that run was confirmed\n        after the last change, so the window is over), as does any run while\n        the mode has not changed since MXZ first saw the head.\n        \"\"\"\n        if now is not None and self.mode is not None and mode != self.mode:\n            self.changed_at = now\n        self.mode = mode\n        self.action = action if isinstance(action, str) else None\n        self.reports_action = self.reports_action or self.action is not None\n        self.lost_at = None\n        self.lost_wall = None\n        if runs(mode, self.action) and (\n            now is None or self.changed_at is None or now - self.changed_at >= self.settle\n        ):\n            self.ran, self.stopped_at = mode, None\n        elif mode != self.ran or (now is None and self.stopped_at is None):\n            self.ran, self.stopped_at = None, None\n        elif self.stopped_at is None:\n            self.stopped_at = now\n\n    def lose(self, now: float, wall: float) -> None:\n        \"\"\"Record that the head can't be seen; the limit runs from the first call.\"\"\"\n        if self.lost_at is None:\n            self.lost_at = now\n            self.lost_wall = wall\n\n    def status(self, now: float, ttl: float) -> str:\n        \"\"\"live, stale, expired, or unknown (see VOTE_* in const).\"\"\"\n        if self.lost_at is None:\n            return VOTE_LIVE\n        if now - self.lost_at >= ttl:\n            return VOTE_EXPIRED\n        return VOTE_UNKNOWN if self.mode is None else VOTE_STALE\n\n    def expires_in(self, now: float, ttl: float) -> float | None:\n        \"\"\"Seconds until the vote expires, or None (in sight or already expired).\"\"\"\n        if self.lost_at is None or now - self.lost_at >= ttl:\n            return None\n        return ttl - (now - self.lost_at)\n\n    def vote(self, now: float, ttl: float) -> str | None:\n        \"\"\"The heat or cool that counts right now: the last seen, live or stale.\"\"\"\n        if self.status(now, ttl) not in (VOTE_LIVE, VOTE_STALE):\n            return None\n        return self.mode if self.mode in (MODE_COOL, MODE_HEAT) else None\n\n    def action_vote(self, now: float, ttl: float, hold: float) -> str | None:\n        \"\"\":meth:`vote`, counted only while the head runs it, or for ``hold`` after.\n\n        Never more than :meth:`vote`: this only drops a vote, it never makes\n        one. A lost head is judged as it was last seen (the moment it was\n        lost), so it keeps the vote it last had, running or held, stale until\n        the time limit, exactly as :meth:`vote` does. The hold is half-open,\n        like the time limit: over AT ``hold``, not after it.\n        \"\"\"\n        vote = self.vote(now, ttl)\n        if vote is None or vote != self.ran:\n            return None\n        if self.stopped_at is None:\n            return vote\n        seen = now if self.lost_at is None else self.lost_at\n        return vote if seen - self.stopped_at < hold else None\n\n    def hold_ends_in(self, now: float, hold: float) -> float | None:\n        \"\"\"Seconds until a stopped head's held vote drops, or None (no hold running).\n\n        None while the head is out of sight: its vote is then kept as last\n        seen, and :meth:`expires_in` times it.\n        \"\"\"\n        if self.lost_at is not None or self.ran is None or self.stopped_at is None:\n            return None\n        left = hold - (now - self.stopped_at)\n        return left if left > 0 else None\n\n    def settles_in(self, now: float) -> float | None:\n        \"\"\"Seconds until an unconfirmed run's window ends (0: it has), or None.\n\n        None unless the head was last seen, in sight, running a mode it is\n        not counted as running (see :meth:`observe`). Past the window it is 0:\n        a sighting is due to confirm it.\n        \"\"\"\n        if (\n            self.lost_at is not None\n            or self.changed_at is None\n            or self.mode == self.ran  # confirmed (or never in a window)\n            or not runs(self.mode, self.action)\n        ):\n            return None\n        return max(0.0, self.settle - (now - self.changed_at))\n\n\n# The head's own hvac_action that means it is running its mode.\n_RUNNING = {MODE_HEAT: \"heating\", MODE_COOL: \"cooling\"}\n\n\ndef runs(mode: Any, action: Any) -> bool:\n    \"\"\"Whether a head's own hvac_action says it runs its mode: heating in\n    heat, cooling in cool. Anything else, a lagging action included, is not\n    a run.\"\"\"\n    return isinstance(action, str) and _RUNNING.get(mode) == action\n\n\ndef floor_call(\n    *,\n    temp: float,\n    sensor_ok: bool,\n    low: float | None,\n    high: float | None,\n    prior: str | None,\n    margin: float,\n) -> str | None:\n    \"\"\"A disabled room's floor want: heat, cool, or None. Pure.\n\n    Untripped (``prior`` None): heat below ``low``, cool above ``high``.\n    Tripped heat holds until the room reaches ``low + margin`` (the clear\n    line), tripped cool until ``high - margin``; then the floor is untripped\n    and re-trips only past the floor again. The margin is the whole minimum\n    run: no separate timer. Without a usable reading there is no want, from\n    any prior: a floor never acts blind. ``None`` for ``low``/``high`` is no\n    floor/ceiling.\n    \"\"\"\n    if not sensor_ok:\n        return None\n    if prior == MODE_HEAT and low is not None and temp < low + margin:\n        return MODE_HEAT\n    if prior == MODE_COOL and high is not None and temp > high - margin:\n        return MODE_COOL\n    if low is not None and temp < low:\n        return MODE_HEAT\n    if high is not None and temp > high:\n        return MODE_COOL\n    return None\n\n\n@dataclass(frozen=True)\nclass FloorRun:\n    \"\"\"One tripped floor's progress record (the no-progress cap's state).\n\n    ``mark`` is the best reading credited this run (highest for heat, lowest\n    for cool), moved only by a whole ``step``; ``driven`` is how many seconds\n    MXZ has driven the head in the floor's direction since the mark last\n    moved; ``worst`` is the worst reading (lowest for heat) in the last\n    ``FLOOR_REARM_SECONDS`` of that driving, frozen once the run stalls, so\n    only a genuinely new low past it re-arms the run. ``recent`` holds the\n    readings that window needs, as (``driven`` when read, reading), oldest\n    first: only those that are still in it and worse than every later one.\n    \"\"\"\n\n    direction: str\n    mark: float\n    worst: float\n    driven: float = 0.0\n    stalled: bool = False\n    recent: tuple[tuple[float, float], ...] = ()\n\n\ndef floor_progress(\n    run: FloorRun, *, temp: float, driven_for: float, step: float, cap: float\n) -> FloorRun:\n    \"\"\"Advance one floor run by one reading. Pure.\n\n    ``driven_for`` is the time the head was actually driven in the run's\n    direction since the last reading (0 while it waited). A reading one\n    ``step`` past the mark moves the mark there and restarts the clock; a\n    clock that reaches ``cap`` stalls the run. A stalled run re-arms (as a\n    new run) only on a reading one step past its worst one in the last\n    ``FLOOR_REARM_SECONDS`` of driving before the stall (decision 11, P9);\n    reaching the clear line is the caller's other way out\n    (:func:`floor_call`). The window is on the run's own clock (driven\n    time), so a dip an hour of driving or more before the stall no longer\n    counts. ``worst`` restarts at each gain and is frozen while stalled, so\n    a room that keeps cooling in sub-step increments re-arms once it is one\n    step below it. A sensor flickering between two adjacent values does\n    neither: its low is in the window, and is already the window's worst,\n    while that low recurs within each ``FLOOR_REARM_SECONDS`` of driving. A\n    value held longer than that with nothing worse, then a reading one step\n    past it, re-arms (P14).\n    \"\"\"\n    sign = 1.0 if run.direction == MODE_HEAT else -1.0\n    if run.stalled:\n        if sign * (run.worst - temp) >= step - 1e-9:\n            return FloorRun(direction=run.direction, mark=temp, worst=temp)\n        return run\n    gained = sign * (temp - run.mark) >= step - 1e-9\n    if gained:\n        return replace(run, mark=temp, worst=temp, driven=0.0, recent=())\n    driven = run.driven + max(driven_for, 0.0)\n    # A reading leaves the window once older than its span, or once a later\n    # one is as bad or worse (it can no longer be the window's worst).\n    recent = (\n        *(\n            (at, seen) for at, seen in run.recent\n            if at >= driven - FLOOR_REARM_SECONDS and sign * (temp - seen) > 0\n        ),\n        (driven, temp),\n    )\n    return replace(\n        run, worst=recent[0][1], driven=driven, stalled=driven >= cap, recent=recent\n    )\n\n\ndef setpoints(\n    *,\n    mode: str,\n    target: float,\n    eco: bool,\n    clamp_min: float,\n    clamp_max: float,\n    band: float = 2.0,\n    step: float = 1.0,\n    eco_cool: tuple[float, float] = (float(ECO_COOL_LOW), float(ECO_COOL_HIGH)),\n    eco_heat: tuple[float, float] = (float(ECO_HEAT_LOW), float(ECO_HEAT_HIGH)),\n    heat_target: float | None = None,\n    cool_target: float | None = None,\n) -> tuple[float, float]:\n    \"\"\"Return (low, high) setpoint edges, clamped. Mirrors the actuator's edge math.\n\n    Unit-agnostic: ``band``/``step``/``eco_*`` carry the temperature unit. The\n    defaults reproduce the original °F behavior (2° band, whole-degree steps,\n    76/78 & 59/61 eco edges); a °C caller passes a 1° band, 0.5° step, and metric\n    eco edges. Edges are rounded to ``step`` and clamped to [clamp_min, clamp_max].\n\n    A dual-setpoint room builds them from ``cool_target`` (Cool to) while the\n    mode is cool and from ``heat_target`` (Heat to) otherwise; either left\n    None uses ``target``.\n    \"\"\"\n    if eco:\n        return eco_cool if mode == MODE_COOL else eco_heat\n    side = cool_target if mode == MODE_COOL else heat_target\n    tc = max(min(target if side is None else side, clamp_max), clamp_min)\n    if mode == MODE_COOL:\n        low, high = max(tc - band, clamp_min), tc\n    else:\n        low, high = tc, min(tc + band, clamp_max)\n    return (_round_to(low, step), _round_to(high, step))\n\n\ndef range_delta(*, temp: float, low: float, high: float) -> float:\n    \"\"\"How far ``temp`` sits outside ``[low, high]``: the fan boost's distance.\n\n    ``low - temp`` below the range, ``temp - high`` above it, 0 inside. A\n    single target is ``low == high == target``, where this is\n    ``abs(temp - target)`` exactly (IEEE subtraction is antisymmetric).\n    \"\"\"\n    if temp < low:\n        return low - temp\n    if temp > high:\n        return temp - high\n    return 0.0\n\n\nclass RangeError(ValueError):\n    \"\"\"A dual-setpoint write that is refused; ``reason`` is its translation key.\"\"\"\n\n    def __init__(self, reason: str) -> None:\n        super().__init__(reason)\n        self.reason = reason\n\n\n# RangeError reasons (each is an exception translation key in strings.json).\nRANGE_OUT_OF_BOUNDS = \"range_out_of_bounds\"\nRANGE_TOO_NARROW = \"range_too_narrow\"\nRANGE_PUSH_OUT_OF_BOUNDS = \"range_push_out_of_bounds\"\nRANGE_TOO_WIDE = \"range_too_wide\"\n\n\ndef resolve_range(\n    *,\n    low: float,\n    high: float,\n    new_low: float,\n    new_high: float,\n    gap: float,\n    bounds: tuple[float, float],\n    step: float,\n) -> tuple[float, float]:\n    \"\"\"The (Heat to, Cool to) a dual-setpoint write lands on, or RangeError.\n\n    ``low``/``high`` are the current pair and ``new_low``/``new_high`` the\n    asked-for one (pass the current value for an edge that isn't written).\n    Writes are refused, never silently clamped:\n\n    * each edge snaps to ``step`` (the climate tile's snap) and must sit\n      inside ``bounds``;\n    * a pair at least ``gap`` wide is taken as it is;\n    * when only ONE edge moved and the pair got too narrow (or crossed), the\n      other edge is pushed to keep exactly ``gap``, the way ecobee and Nest\n      behave; a push past ``bounds`` is refused;\n    * when BOTH moved and the pair is too narrow or inverted, it's refused.\n    \"\"\"\n    lo, hi = bounds\n    nl, nh = _round_to(new_low, step), _round_to(new_high, step)\n    if not (lo <= nl <= hi and lo <= nh <= hi):\n        raise RangeError(RANGE_OUT_OF_BOUNDS)\n    if nh - nl >= gap - 1e-9:\n        return nl, nh\n    low_moved, high_moved = nl != low, nh != high\n    if low_moved and not high_moved:\n        nh = nl + gap\n        if nh > hi:\n            raise RangeError(RANGE_PUSH_OUT_OF_BOUNDS)\n        return nl, nh\n    if high_moved and not low_moved:\n        nl = nh - gap\n        if nl < lo:\n            raise RangeError(RANGE_PUSH_OUT_OF_BOUNDS)\n        return nl, nh\n    raise RangeError(RANGE_TOO_NARROW)\n\n\ndef shift_range(\n    *,\n    width: float,\n    center: float,\n    bounds: tuple[float, float],\n    step: float,\n) -> tuple[float, float]:\n    \"\"\"A ``width``-wide (Heat to, Cool to) centered on ``center``, inside ``bounds``.\n\n    What writing a dual-setpoint room's target does, and how a range is\n    seeded and re-centered. Heat to snaps to ``step`` (halves round up, so a\n    range whose width is an odd number of steps sits half a step above\n    ``center`` rather than flipping with Python's half-to-even rounding);\n    Cool to is Heat to plus ``width`` exactly. A range that would cross a\n    bound slides back inside, still ``width`` wide; one wider than the\n    bounds is refused.\n    \"\"\"\n    lo, hi = bounds\n    if width > hi - lo + 1e-9:\n        raise RangeError(RANGE_TOO_WIDE)\n    low = center - width / 2\n    if step > 0:\n        low = math.floor(low / step + 0.5) * step\n    low = min(max(low, lo), hi - width)\n    return low, low + width\n\n\ndef snapped_midpoint(*, low: float, high: float, step: float) -> float:\n    \"\"\"The target a dual-setpoint room returns to: its midpoint, on ``step``.\n\n    The climate tile's own snap (``round(x / step) * step``).\n    \"\"\"\n    return _round_to((low + high) / 2, step)\n\n\ndef _round_to(value: float, step: float) -> float:\n    \"\"\"Round ``value`` to the nearest multiple of ``step`` (step<=0 -> unchanged).\"\"\"\n    if step <= 0:\n        return value\n    return round(value / step) * step\n\n\ndef fan_for_delta(\n    *,\n    delta: float,\n    cur_idx: int,\n    up_at: tuple[float, ...],\n    down_at: tuple[float, ...],\n    max_idx: int,\n) -> int:\n    \"\"\"Pick a fan-ladder INDEX (0..) from how far the room is off-target.\n\n    Tesla-style: a big ``delta`` steps the fan up toward ``max_idx``; as the room\n    closes on target the fan eases down. ``up_at``/``down_at`` carry a 0.5 °F\n    hysteresis band so the speed doesn't chatter on the boundary. The caller owns\n    persisting ``cur_idx`` between calls (per head).\n    \"\"\"\n    # step UP as far as delta allows, never above max_idx\n    while cur_idx < len(up_at) and cur_idx < max_idx and delta >= up_at[cur_idx]:\n        cur_idx += 1\n    # step DOWN only once delta clears the lower rung's down-threshold\n    while cur_idx > 0 and delta < down_at[cur_idx - 1]:\n        cur_idx -= 1\n    return min(cur_idx, max_idx)\n\n\ndef head_action(*, engage: str, mode: str, eco: bool, idle: str = MODE_FAN_ONLY) -> str:\n    \"\"\"Map a head's engage state to the mode to command. Mirrors p_act/s_act.\n\n    ``idle`` is the pre-resolved parking mode (fan_only or off) for a head that\n    is neither disabled nor running — satisfied rooms and standoff losers both\n    land there. Precedence: disabled > eco-satisfied > running > idle.\n    \"\"\"\n    if engage == MODE_OFF:\n        return MODE_OFF\n    if eco and engage == ENGAGE_SATISFIED:\n        return MODE_OFF\n    if engage == mode:\n        return mode\n    return idle\n",
 "custom_components/mxz_coordinator/plan.py": "\"\"\"The plan one compute decides, and the attributes it is shown as.\n\n``Plan`` and ``RoomPlan`` are the decision record the apply, the mode's\nwriteback, the dwell wakeup and the room thermostat read back. ``to_attributes``\nrenders them as the plan sensor, the room rows and diagnostics show them; key\norder is part of what they show (``tests/plan_attributes.json`` records it).\n\nA room row also carries what other controllers show for the room (its delivery,\nhead, floor, Dry and door/window state, its start points and vote basis). Each\nof those is the dict its controller renders, kept as rendered, and a few of\nthem are refreshed while a plan's deliveries run.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\nfrom .cloud import CLOUD_NOT_CONTROLLABLE\n\n\n@dataclass(slots=True)\nclass RoomPlan:\n    \"\"\"One room's part of a plan, in the order its row shows it.\"\"\"\n\n    slug: str\n    name: str\n    demand: str\n    engage: str\n    # The reading as shown: None when it was rejected (a stale one is shown).\n    temp: float | None\n    target: float\n    # A dual-setpoint room's Heat to and Cool to; None for a single target.\n    target_range: tuple[float | None, float | None] | None\n    enabled: bool\n    drift: float\n    drift_heat: float\n    drift_cool: float\n    start_points: dict[str, Any]\n    sensor_health: str\n    sensor_age: int | None\n    hands_off: str | None\n    hands_off_vote: str | None\n    vote_status: str\n    lost_since: str | None\n    vote_basis: dict[str, Any]\n    safety_priority: bool\n    comfort_priority_entity: str | None\n    comfort_priority: float\n    comfort_priority_status: str\n    floor_low: float | None\n    floor_high: float | None\n    floor_want: str | None\n    dry: dict[str, Any]\n    opening: dict[str, Any]\n    # Refreshed by the coordinator as the plan's deliveries run.\n    fan_hold: bool\n    control_reasons: list[dict[str, str]]\n    floor: dict[str, Any]\n    delivery: dict[str, Any]\n    head: dict[str, Any]\n\n    @property\n    def cloud_out(self) -> bool:\n        \"\"\"Whether the row shows a cloud head out of MXZ's control.\"\"\"\n        return self.head.get(\"cloud_status\") == CLOUD_NOT_CONTROLLABLE\n\n    @property\n    def dry_state(self) -> str | None:\n        \"\"\"An Allow Dry room's dry state as the row shows it; None for any other room.\"\"\"\n        return self.dry.get(\"dry\")\n\n    @property\n    def dry_vote(self) -> str | None:\n        \"\"\"An Allow Dry room's dry vote as the row shows it; None for any other room.\"\"\"\n        return self.dry.get(\"dry_vote\")\n\n    def to_attributes(self) -> dict[str, Any]:\n        \"\"\"The room's row, as the plan sensor and the room thermostat show it.\"\"\"\n        return {\n            \"name\": self.name,\n            \"demand\": self.demand,\n            \"engage\": self.engage,\n            \"temp\": self.temp,\n            \"target\": self.target,\n            **(\n                {\"target_low\": self.target_range[0], \"target_high\": self.target_range[1]}\n                if self.target_range is not None else {}\n            ),\n            \"enabled\": self.enabled,\n            \"drift\": self.drift,\n            \"drift_heat\": self.drift_heat,\n            \"drift_cool\": self.drift_cool,\n            **self.start_points,\n            \"fan_hold\": self.fan_hold,\n            \"sensor_health\": self.sensor_health,\n            \"sensor_age\": self.sensor_age,\n            \"control_reasons\": self.control_reasons,\n            \"hands_off\": self.hands_off,\n            \"hands_off_vote\": self.hands_off_vote,\n            \"vote_status\": self.vote_status,\n            \"lost_since\": self.lost_since,\n            **self.vote_basis,\n            \"safety_priority\": self.safety_priority,\n            \"comfort_priority_entity\": self.comfort_priority_entity,\n            \"comfort_priority\": self.comfort_priority,\n            \"comfort_priority_status\": self.comfort_priority_status,\n            \"floor_low\": self.floor_low,\n            \"floor_high\": self.floor_high,\n            **self.floor,\n            \"floor_want\": self.floor_want,\n            **self.delivery,\n            **self.head,\n            **self.dry,\n            **self.opening,\n        }\n\n\n@dataclass(slots=True)\nclass Plan:\n    \"\"\"One compute's decision: the shared mode, why, and each room's part.\"\"\"\n\n    rooms: list[RoomPlan]\n    state: str\n    standoff: bool\n    mode_by_hands_off: bool\n    mode_by_safety: bool\n    mode_by_comfort_priority: bool\n    mode_by_floor: bool\n    sensors_ok: bool\n    seconds_since_mode_change: int | None\n    mode_change_allowed: bool\n    inhibited: bool\n    idle_action: str\n    # Only an entry with a door/window pause has the list.\n    paused_rooms: list[str] | None = field(default=None)\n\n    def room(self, slug: str) -> RoomPlan | None:\n        \"\"\"The room with this slug, if the plan has it.\"\"\"\n        return next((room for room in self.rooms if room.slug == slug), None)\n\n    def to_attributes(self) -> dict[str, Any]:\n        \"\"\"The plan as the plan sensor and diagnostics show it.\"\"\"\n        attributes: dict[str, Any] = {}\n        for room in self.rooms:\n            attributes[f\"{room.slug}_demand\"] = room.demand\n            attributes[f\"{room.slug}_engage\"] = room.engage\n            attributes[f\"{room.slug}_temp\"] = room.temp\n            attributes[f\"{room.slug}_sensor_health\"] = room.sensor_health\n            attributes[f\"{room.slug}_sensor_age\"] = room.sensor_age\n        attributes.update(\n            {\n                \"state\": self.state,\n                \"zones\": [room.to_attributes() for room in self.rooms],\n                \"standoff\": self.standoff,\n                \"mode_by_hands_off\": self.mode_by_hands_off,\n                \"mode_by_safety\": self.mode_by_safety,\n                \"mode_by_comfort_priority\": self.mode_by_comfort_priority,\n                \"mode_by_floor\": self.mode_by_floor,\n                \"sensors_ok\": self.sensors_ok,\n                \"seconds_since_mode_change\": self.seconds_since_mode_change,\n                \"mode_change_allowed\": self.mode_change_allowed,\n                \"inhibited\": self.inhibited,\n                \"idle_action\": self.idle_action,\n            }\n        )\n        if self.paused_rooms is not None:\n            attributes[\"paused_rooms\"] = self.paused_rooms\n        return attributes\n",
 "custom_components/mxz_coordinator/planner.py": "\"\"\"The planner: what one compute decides from what it read. No Home Assistant.\n\n``MXZCoordinator._compute`` reads each room's sensor, head and controllers, hands the\nreadings to :func:`decide` as one :class:`RoomInput` per room and one :class:`Shared`,\nand builds the plan from the :class:`Decision`. ``_apply`` does what :func:`apply_plan` yields,\none part at a time: each head's gates, its idle park (:func:`idle_for`) and\n:func:`head_command` as :class:`HeadStep` values, then the plan's mode written back as\n:func:`mode_write_back` says, stamped by :func:`stamp_mode_change`. Each head's driver then runs that command's\n:func:`delivery_steps`.\nTime comes in as numbers: the seconds since the last mode change, the hold's length,\nthe coil-dry clock, and the clocks a start reads (:func:`mode_change_stamp`).\nThe engage latch and the startup seeds come in as they are and go out advanced; nothing\nhere keeps state.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections.abc import (\n    Callable,\n    Collection,\n    Hashable,\n    Iterable,\n    Iterator,\n    Mapping,\n    Sequence,\n)\nfrom dataclasses import asdict, dataclass, replace\nfrom typing import Any\n\nfrom .const import (\n    ADOPT_DELAY,\n    BAND_DRIFT_DELAY,\n    BANNED_MODES,\n    DEMAND_NEUTRAL,\n    ENGAGE_SATISFIED,\n    IDLE_ACTION_FAN_ONLY,\n    IDLE_ACTION_OFF,\n    IDLE_ACTION_OFF_AFTER_DRY,\n    MODE_COOL,\n    MODE_DRY,\n    MODE_FAN_ONLY,\n    MODE_HEAT,\n    MODE_OFF,\n    OFF_WHILE_ENABLED_DELAY,\n    UNAVAILABLE_STATES,\n    VOTE_EXPIRED,\n)\nfrom .grid import Grid\nfrom .head_writes import HEAD_WRITE_MODE, write_is_own\nfrom .logic import (\n    PRIORITY_DEMAND,\n    PRIORITY_FLOOR_HEAT,\n    PRIORITY_SAFETY,\n    PRIORITY_VOTE,\n    STATE_UNAVAILABLE,\n    Demand,\n    HeadWriteMemory,\n    arbitrate,\n    as_float,\n    comfort_boost,\n    engage_with_latch,\n    head_action,\n    range_delta,\n    room_call,\n    setpoints,\n)\nfrom .plan import Plan, RoomPlan\nfrom .timing import (\n    Arm,\n    Refresh,\n    coil_dry_delay,\n    head_refresh,\n    head_shows_new,\n    hold_end_arm,\n    run_changed,\n)\nfrom .units import clamp\n\n\n@dataclass(frozen=True, slots=True)\nclass CallLimits:\n    \"\"\"The lockouts and eco every room's call reads, as :func:`logic.room_call` takes them.\"\"\"\n\n    eco: bool\n    eco_cool_max: float\n    eco_heat_min: float\n    heat_lockout: bool\n    heat_lockout_floor: float\n    cool_lockout: bool\n    cool_lockout_ceiling: float\n\n\n@dataclass(frozen=True, slots=True)\nclass RoomInput:\n    \"\"\"One room as this compute read it.\"\"\"\n\n    slug: str\n    enabled: bool\n    # The reading, or the fallback when it was rejected; sensor_ok says which.\n    temp: float\n    # A valid reading that is not stale.\n    sensor_ok: bool\n    target: float\n    # Each side's target: Heat to and Cool to, or the one target twice.\n    heat_target: float\n    cool_target: float\n    heat_drift: float\n    cool_drift: float\n    # The head's reported state; None when it has none.\n    head: str | None\n    paused: bool\n    dry: bool\n    # A tripped floor's or ceiling's want.\n    floor: str | None\n    safety: bool\n    # A released hands-off head's vote.\n    vote: str | None\n    # Whether the room's own demand and run still count (see holds()).\n    holds: bool\n    # Comfort priority (0 = none).\n    boost: float\n\n\n@dataclass(frozen=True, slots=True)\nclass Shared:\n    \"\"\"What every room's decision shares this compute.\"\"\"\n\n    limits: CallLimits\n    demand_threshold: float\n    # The shared mode now.\n    mode: str\n    # Seconds since the last real mode change; None when none is on record.\n    elapsed: float | None\n    # The hold: the least time between two real mode changes.\n    hold: float\n    resting: str | None\n    # Whether hands-off votes alone set the shared mode.\n    by_votes: bool\n    # Coordinator on, and on before the start: a startup seed may resume a run.\n    resume: bool\n    accept_head_changes: bool\n\n\n@dataclass(frozen=True, slots=True)\nclass RoomDecision:\n    demand: str\n    engage: str\n    # The demand and engage arbitration counts (see holds()).\n    held_demand: str\n    held_engage: str\n    dry_vote: str | None\n\n\n@dataclass(frozen=True, slots=True)\nclass Decision:\n    rooms: tuple[RoomDecision, ...]\n    # The engage latch and startup seeds, advanced by this compute.\n    latch: dict[str, str]\n    startup: dict[str, str | None]\n    # A room let go of a run this compute.\n    coasted: bool\n    state: str\n    by_votes: bool\n    by_safety: bool\n    by_comfort: bool\n    by_floor: bool\n    standoff: bool\n    allowed: bool\n\n\ndef arbitration_mode(mode: str) -> str:\n    \"\"\"The shared mode arbitration starts from (cold start / junk -> cool).\"\"\"\n    return mode if mode in (MODE_COOL, MODE_HEAT) else MODE_COOL\n\n\ndef demand_bands(threshold: float, heat_drift: float, cool_drift: float) -> tuple[float, float]:\n    \"\"\"How far a room may sit off each side's target before it calls.\n\n    A room's demand vote respects its OWN drift (#18): a room told to tolerate a\n    wide band must not steer the shared compressor inside it. max() reproduces\n    the threshold exactly whenever drift <= threshold (the default). Per side, so\n    a wide \"warmer by\" also holds back cool demand.\n    \"\"\"\n    return max(threshold, heat_drift), max(threshold, cool_drift)\n\n\ndef holds(status: str | None, safety: bool, cloud_out: bool = False) -> bool:\n    \"\"\"Whether a room's own demand and run still count in arbitration.\n\n    Not once its head's vote has expired: a long-lost head must not hold\n    the shared mode for its room forever while a sibling waits. Kept as in\n    3.10.0, pending a maintainer decision: a room marked Safety priority with its\n    sensor on (its demand is a safety want), and a tripped floor or\n    ceiling (its own entry, never dropped here). Likewise not while a\n    cloud head is out of MXZ's control (``cloud_out``): MXZ can't run it,\n    so its room's call would only hold the outdoor unit for nothing. A\n    Safety priority room still calls from its room sensor.\n    \"\"\"\n    return safety or (status != VOTE_EXPIRED and not cloud_out)\n\n\ndef arbitration_entries(\n    *, demand: str, vote: str | None, safety: bool, index: int,\n    floor: str | None = None, dry: str | None = None, boost: float = 0.0,\n) -> tuple[Demand, ...]:\n    \"\"\"One zone's (demand, vote[, dry][, floor]) as :class:`Demand` entries.\n\n    ``boost`` is the room's Comfort priority. It goes on the demand, the\n    vote and the dry vote, never on a floor or ceiling entry, and\n    :func:`logic.arbitrate` ignores it on a Safety priority entry.\n\n    Shared by :func:`decide` (live) and the coordinator's dwell wakeup\n    (replayed from the already-computed plan) so the priority-tier math lives\n    in exactly one place. A dry head's cool (Allow Dry mode) is one more vote,\n    always at PRIORITY_VOTE: the room's Safety priority sensor never lifts it. A\n    tripped floor is a commanding entry: a freeze floor's heat at\n    PRIORITY_FLOOR_HEAT, a ceiling's cool at PRIORITY_SAFETY (see\n    :func:`logic.arbitrate`). It is independent of the room's own Safety\n    priority sensor.\n    \"\"\"\n    tier = PRIORITY_SAFETY if safety else None\n    pair: tuple[Demand, ...] = (\n        Demand(\n            direction=demand if demand in (MODE_COOL, MODE_HEAT) else None,\n            priority=(tier if tier is not None else PRIORITY_DEMAND, index),\n            boost=boost,\n        ),\n        Demand(\n            direction=vote,\n            priority=(tier if tier is not None else PRIORITY_VOTE, index),\n            read_only=True,\n            boost=boost,\n        ),\n    )\n    if dry is not None:\n        pair = (\n            *pair,\n            Demand(\n                direction=dry, priority=(PRIORITY_VOTE, index), read_only=True,\n                boost=boost,\n            ),\n        )\n    if floor not in (MODE_COOL, MODE_HEAT):\n        return pair\n    floor_tier = PRIORITY_FLOOR_HEAT if floor == MODE_HEAT else PRIORITY_SAFETY\n    return (*pair, Demand(direction=floor, priority=(floor_tier, index)))\n\n\ndef held_back(rooms: Sequence[RoomPlan], *, current: str, resting: str | None) -> bool:\n    \"\"\"Whether the mode-change hold keeps the shared mode from changing: with the hold open,\n    arbitration would pick another mode than ``current`` from these rooms.\n\n    The rooms are a computed plan's, replayed as :func:`decide` counted them (:func:`holds`),\n    so the dwell wakeup weighs exactly what that compute arbitrated.\n    \"\"\"\n    demands: list[str] = []\n    engages: list[str] = []\n    for room in rooms:\n        if holds(room.vote_status, room.safety_priority, room.cloud_out):\n            demands.append(room.demand)\n            engages.append(room.engage)\n        else:\n            demands.append(DEMAND_NEUTRAL)\n            engages.append(room.engage if room.floor_want is not None else ENGAGE_SATISFIED)\n    engaged = any(e in (MODE_COOL, MODE_HEAT) for e in engages)\n    entries: list[Demand] = []\n    for i, (room, demand) in enumerate(zip(rooms, demands)):\n        entries.extend(\n            arbitration_entries(\n                demand=demand,\n                vote=room.hands_off_vote,\n                safety=room.safety_priority,\n                index=i,\n                floor=room.floor_want,\n                dry=room.dry_vote,\n                boost=room.comfort_priority,\n            )\n        )\n    return arbitrate(\n        entries, engaged=engaged, current=current, allowed=True,\n        resting=resting, running=current in engages,\n    ).direction != current\n\n\ndef _seed_latch(\n    room: RoomInput, shared: Shared, latch: dict[str, str], startup: dict[str, str | None]\n) -> None:\n    \"\"\"Put a resumed or retargeted room's run in the latch before its engage is decided.\n\n    A start resumes each room's run from its head (``startup``), once the head\n    reports and the room has a usable reading; missing startup evidence is kept\n    apart from a known idle run. An enabled room with no latch (its target\n    changed) takes the run its head shows. With changes at the head accepted, a\n    head a person flipped off the shared mode is no run of MXZ's: its heat/cool\n    isn't adopted.\n    \"\"\"\n    head = room.head\n    seen = head is not None and head not in UNAVAILABLE_STATES\n    if room.slug in startup:\n        if not (room.enabled and shared.resume):\n            startup.pop(room.slug)\n        else:\n            if startup[room.slug] is None and seen:\n                startup[room.slug] = head if head in (MODE_COOL, MODE_HEAT) else \"\"\n            seed = startup[room.slug]\n            if room.sensor_ok and seed is not None and seen:\n                latch[room.slug] = seed\n                startup.pop(room.slug)\n    elif room.slug not in latch and room.enabled:\n        latch[room.slug] = (\n            head\n            if head in (MODE_COOL, MODE_HEAT)\n            and (not shared.accept_head_changes or head == shared.mode)\n            else \"\"\n        )\n\n\ndef decide(\n    rooms: Sequence[RoomInput],\n    shared: Shared,\n    latch: Mapping[str, str],\n    startup: Mapping[str, str | None],\n) -> Decision:\n    \"\"\"Each room's demand and engage, and the shared mode they arbitrate to.\n\n    It advances each room's engage latch and any pending startup seed, and\n    returns them with the decision.\n    \"\"\"\n    latch = dict(latch)\n    startup = dict(startup)\n    limits = asdict(shared.limits)\n    decided: list[RoomDecision] = []\n    entries: list[Demand] = []\n    coasted = False\n    for i, room in enumerate(rooms):\n        heat_band, cool_band = demand_bands(shared.demand_threshold, room.heat_drift, room.cool_drift)\n        demand = room_call(\n            temp=room.temp, target=room.target, enabled=room.enabled,\n            heat_target=room.heat_target, cool_target=room.cool_target,\n            sensor_ok=room.sensor_ok,\n            heat_band=heat_band,\n            cool_band=cool_band,\n            neutral=DEMAND_NEUTRAL,\n            **limits,\n        )\n        _seed_latch(room, shared, latch, startup)\n        prior_engage = latch.get(room.slug, \"\")\n        engage = engage_with_latch(\n            prior=prior_engage or None,\n            temp=room.temp, target=room.target, enabled=room.enabled,\n            heat_target=room.heat_target, cool_target=room.cool_target,\n            sensor_ok=room.sensor_ok, heat_band=room.heat_drift, cool_band=room.cool_drift,\n            neutral=ENGAGE_SATISFIED,\n            **limits,\n        )\n        if room.slug in latch:\n            latch[room.slug] = engage if engage in (MODE_COOL, MODE_HEAT) else \"\"\n        # Door/window pause: a paused room has no call and no run. It never\n        # votes, so it can neither keep nor turn the shared mode, and it doesn't\n        # hold Resting mode off; its run starts afresh on resume.\n        if room.paused:\n            demand, engage = DEMAND_NEUTRAL, ENGAGE_SATISFIED\n            if room.slug in latch:\n                latch[room.slug] = \"\"\n            prior_engage = \"\"\n        # Allow Dry mode (never while paused): a person runs this head in dry,\n        # so the room's temperature goal pauses (no call, no run). Its vote is\n        # the dry below. Out of dry it starts afresh.\n        dry = room.dry and not room.paused\n        if dry:\n            demand, engage = DEMAND_NEUTRAL, ENGAGE_SATISFIED\n            if room.slug in latch:\n                latch[room.slug] = \"\"\n            prior_engage = \"\"\n        # This room let go of a run and is now coasting: it is parked at the\n        # idle action, and only a later compute may engage it again. A disabled\n        # room (MODE_OFF) is not coasting.\n        if prior_engage and engage == ENGAGE_SATISFIED:\n            coasted = True\n        # A tripped floor is this disabled room's engage (the latch stays\n        # untouched: it belongs to the room's own enabled runs).\n        if room.floor is not None:\n            engage = room.floor\n        # A dry head runs the outdoor unit the cooling way: a cool vote at\n        # hands-off rank, whatever the room's Safety priority sensor says, and\n        # none at all under a cool lockout.\n        dry_vote = MODE_COOL if dry and not shared.limits.cool_lockout else None\n        held_demand = demand if room.holds else DEMAND_NEUTRAL\n        held_engage = engage if room.holds or room.floor is not None else ENGAGE_SATISFIED\n        entries.extend(\n            arbitration_entries(\n                demand=held_demand, vote=room.vote, safety=room.safety, index=i,\n                floor=room.floor, dry=dry_vote, boost=room.boost,\n            )\n        )\n        decided.append(RoomDecision(demand, engage, held_demand, held_engage, dry_vote))\n\n    current = arbitration_mode(shared.mode)\n    held_engages = [room.held_engage for room in decided]\n    allowed = shared.elapsed is None or shared.elapsed >= shared.hold\n    engaged = any(e in (MODE_COOL, MODE_HEAT) for e in held_engages)\n    # A room still running to its target in the shared mode keeps it from\n    # Resting mode until it gets there (logic.arbitrate).\n    running = current in held_engages\n    grant = arbitrate(\n        entries,\n        engaged=engaged,\n        current=current,\n        allowed=allowed,\n        resting=shared.resting,\n        running=running,\n    )\n    # Comfort priority earned the answer only if the same compute with\n    # every boost at 0 answers differently. Run only when one counts.\n    by_comfort = any(comfort_boost(d) > 0 for d in entries) and arbitrate(\n        [replace(d, boost=0.0) for d in entries],\n        engaged=engaged,\n        current=current,\n        allowed=allowed,\n        resting=shared.resting,\n        running=running,\n    ).direction != grant.direction\n    state, by_votes = grant.direction, grant.read_only\n    if (\n        not by_votes and shared.by_votes and state != current\n        and not any(\n            c in (MODE_COOL, MODE_HEAT)\n            for c in (*(room.demand for room in decided), *(room.engage for room in decided))\n        )\n    ):\n        by_votes = True\n    floors = [room.floor for room in rooms]\n    calls = [\n        *(room.held_demand for room in decided),\n        *(room.vote for room in rooms),\n        *(room.dry_vote for room in decided),\n        *floors,\n    ]\n    return Decision(\n        rooms=tuple(decided),\n        latch=latch,\n        startup=startup,\n        coasted=coasted,\n        state=state,\n        by_votes=by_votes,\n        by_safety=grant.by_safety,\n        by_comfort=by_comfort,\n        by_floor=state in floors,\n        # Both directions physically asked of the one outdoor unit, a hands-off\n        # head's and a floor's included (a room whose head's vote expired asks\n        # nothing any more).\n        standoff=MODE_COOL in calls and MODE_HEAT in calls,\n        allowed=allowed,\n    )\n\n\n@dataclass(frozen=True, slots=True)\nclass ModeWriteBack:\n    \"\"\"What one plan's mode does to the shared mode and its record.\"\"\"\n\n    mode: str\n    by_votes: bool\n    # The shared mode changed: the shared-mode select re-renders.\n    changed: bool\n    # Start the hold.\n    stamp: bool\n    # Write the record.\n    record: bool\n\n\ndef mode_write_back(\n    mode: str,\n    by_votes: bool,\n    *,\n    state: str,\n    by_hands_off: bool,\n    calls: Collection[str],\n    resting: str | None,\n) -> ModeWriteBack:\n    \"\"\"The shared mode ``mode`` (set by votes alone if ``by_votes``) after a plan for ``state``.\n\n    ``calls`` is every room's engage and demand in that plan. Stamp the flip only on\n    a real mode change (cool<->heat). A flip only hands-off heads asked for is not\n    one the coordinator caused, so it starts no dwell (see logic.arbitrate()). Once\n    a coordinated room runs in that mode, the mode is ours: stamp it then, as if\n    that room had flipped it, so the next reversal is dwelled. The vote's undoing\n    (back to the resting bias) starts no dwell either, but leaves a mode that owes\n    the vote nothing: a run there is no flip.\n    \"\"\"\n    if state != mode:\n        return ModeWriteBack(\n            mode=state,\n            by_votes=by_hands_off and state != resting,\n            changed=True,\n            stamp=not by_hands_off,\n            record=True,\n        )\n    if by_votes and state in calls:\n        return ModeWriteBack(\n            mode=mode,\n            by_votes=False,\n            changed=False,\n            stamp=True,\n            record=True,\n        )\n    return ModeWriteBack(mode=mode, by_votes=by_votes, changed=False, stamp=False, record=False)\n\n\ndef mode_change_stamp(stored: float | None, now: float, wall: float) -> float | None:\n    \"\"\"The stamp on MXZ's clock, read as ``now``, for a stored wall-clock change time.\n\n    ``wall`` is the wall clock read at the same start. The gate itself runs on\n    the monotonic clock (an NTP step inside one run must not move it), so the\n    stored time becomes \"this many seconds ago\" on that clock once, at startup.\n    A stored time in the future (the clock was set back, or it ran ahead when\n    the change was written) counts as now: the hold is then the full window\n    from this start, never longer.\n    \"\"\"\n    if stored is None:\n        return None\n    ago = max(0.0, wall - stored)\n    return now - ago\n\n\n@dataclass(frozen=True, slots=True)\nclass ModeStamp:\n    \"\"\"A real mode change, stamped: ``at`` on the monotonic clock and ``wall`` on the wall\n    clock, and the hold-end wakeup it arms (None: a retired coordinator arms none).\"\"\"\n\n    at: float\n    wall: float\n    hold_end: Arm | None\n\n\ndef stamp_mode_change(\n    clock: Callable[[], float], wall: Callable[[], float], *, retired: bool, hold: float\n) -> ModeStamp:\n    \"\"\"A real mode change happens now (:attr:`ModeWriteBack.stamp`): the hold starts.\n\n    ``clock`` and ``wall`` read the clocks, in that order. The hold-end wakeup is armed for the\n    hold left as the clock reads it again, the comparison the gate makes (``hold``, the\n    hold's length). Its end only redraws the thermostats.\n    \"\"\"\n    at = clock()\n    when = wall()\n    if retired:\n        return ModeStamp(at=at, wall=when, hold_end=None)\n    return ModeStamp(\n        at=at, wall=when, hold_end=hold_end_arm(max(0.0, hold - (clock() - at)), retired=False),\n    )\n\n\n@dataclass(frozen=True, slots=True)\nclass SetpointSettings:\n    \"\"\"How a head's setpoints are built, in the system unit (see logic.setpoints).\"\"\"\n\n    clamp_min: float\n    clamp_max: float\n    band: float\n    step: float\n    eco_cool: tuple[float, float]\n    eco_heat: tuple[float, float]\n\n\n@dataclass(frozen=True, slots=True)\nclass HeadCommand:\n    \"\"\"What one apply queues for a head.\"\"\"\n\n    mode: str\n    low: float\n    high: float\n    # How far the room sits outside its range: the fan boost's distance.\n    delta: float\n    # The engage the delivery's fan step follows; None for a floor run, which\n    # never writes the head's fan.\n    fan: str | None\n\n\n@dataclass(frozen=True, slots=True)\nclass LastRun:\n    \"\"\"The head's last run becomes ``run`` (its act and the clock reading it was sent at): the\n    coil-dry memory the coil-dry run counts from.\"\"\"\n\n    run: tuple[str, float]\n\n\n@dataclass(frozen=True, slots=True)\nclass DryNotice:\n    \"\"\"People are told, once, that the head's Dry is parked for another room's heat.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass FanRead:\n    \"\"\"The head's fan is read for ``act`` (``fan_latch.fan_read``): MXZ sends it no fan, and a\n    person's pick on it is kept.\"\"\"\n\n    act: str\n\n\n@dataclass(frozen=True, slots=True)\nclass HandBack:\n    \"\"\"A released hands-off room's hand-back, if one is owed, is queued (P3).\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass Landed:\n    \"\"\"The parking hands-off head has landed: it is someone else's now.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass Queue:\n    \"\"\"``command`` is queued for the head; ``taken``: the floor expects it over a person's run.\"\"\"\n\n    command: HeadCommand\n    taken: bool = False\n\n\n# What a parking read (IdlePark.steps) or a delivery's note (DeliverySteps.note) does to a\n# head's coil-dry memory: its last run kept, its coil-dry wakeup armed or cancelled.\ntype MemoryStep = LastRun | Arm\n# One thing an apply does at one head (HeadApply.steps).\ntype HeadStep = MemoryStep | DryNotice | FanRead | HandBack | Landed | Queue\n\n\ndef idle_park(\n    idle_action: str,\n    last_run: tuple[str, float] | None,\n    coil_dry_seconds: float,\n    clock: float,\n) -> tuple[str, float | None]:\n    \"\"\"The parking mode (fan_only|off) for a non-running head now, and the seconds\n    its coil-dry run has left (None when none is owed).\n\n    ``off_after_dry`` resolves per head from its last run (``last_run``, the mode\n    and the clock reading it was sent at): off immediately unless the head was\n    actively COOLING within the coil-dry window (a wet coil sealed behind closed\n    vanes is what grows the smell), in which case it dwells in fan_only until the\n    coil-dry clock runs out. The dwell is a clock comparison, so a restart can\n    never strand a head in fan_only.\n    \"\"\"\n    if idle_action == IDLE_ACTION_OFF:\n        return MODE_OFF, None\n    if idle_action != IDLE_ACTION_OFF_AFTER_DRY:\n        return MODE_FAN_ONLY, None\n    if last_run is None or last_run[0] != MODE_COOL:\n        return MODE_OFF, None  # heat leaves no wet coil; never-ran owes no dwell\n    remaining = coil_dry_seconds - (clock - last_run[1])\n    if remaining <= 0:\n        return MODE_OFF, None\n    return MODE_FAN_ONLY, remaining\n\n\ndef rebuilt_last_run(shown: str | None, clock: float) -> tuple[str, float] | None:\n    \"\"\"A head's last run after a restart, rebuilt from the mode it shows (``shown``).\n\n    A head seen still cooling was cooling until the restart; one seen in fan_only may be\n    mid-dwell. Both owe the full coil-dry run from now, erring a few minutes toward coil dry,\n    never stranding the head (the clock runs out regardless). Off, heat, no state and\n    unavailable owe nothing.\n    \"\"\"\n    if shown in (MODE_COOL, MODE_FAN_ONLY):\n        return (MODE_COOL, clock)\n    return None\n\n\n@dataclass(frozen=True, slots=True)\nclass IdlePark:\n    \"\"\"A non-running head's parking mode and what it does to the coil-dry memory.\n\n    ``seeded``: the last run rebuilt from what the head shows, to keep. ``arm``: the coil-dry\n    wakeup to arm, None when none is owed or one is already armed.\n    \"\"\"\n\n    idle: str\n    seeded: tuple[str, float] | None\n    arm: Arm | None\n\n    @property\n    def steps(self) -> tuple[MemoryStep, ...]:\n        \"\"\"What reading this park does, in order: the rebuilt memory kept, then the wakeup.\"\"\"\n        return (\n            *((LastRun(self.seeded),) if self.seeded is not None else ()),\n            *((self.arm,) if self.arm is not None else ()),\n        )\n\n\ndef idle_for(\n    head: Hashable,\n    idle_action: str,\n    last_run: tuple[str, float] | None,\n    shown: str | None,\n    coil_dry_seconds: float,\n    clock: float,\n    *,\n    dry_waiting: bool,\n) -> IdlePark:\n    \"\"\":func:`idle_park` for one head (key ``head``), with its memory rebuilt after a restart.\n\n    For ``off_after_dry`` a head with no last run on record has it rebuilt from what it shows\n    (``rebuilt_last_run``). A coil-dry run with time left gets one wakeup just after its end,\n    unless one is armed (``dry_waiting``): the stamp doesn't move while idle, and the wakeup\n    only makes the end prompt.\n    \"\"\"\n    seeded = None\n    if last_run is None and idle_action == IDLE_ACTION_OFF_AFTER_DRY:\n        seeded = last_run = rebuilt_last_run(shown, clock)\n    idle, coil_dry = idle_park(idle_action, last_run, coil_dry_seconds, clock)\n    arm = None\n    if coil_dry is not None and not dry_waiting:\n        arm = Arm(\"dry\", head, coil_dry_delay(coil_dry))\n    return IdlePark(idle=idle, seeded=seeded, arm=arm)\n\n\ndef head_command(\n    *,\n    engage: str,\n    floor_run: tuple[str, float] | None,\n    temp: float | None,\n    enabled: bool,\n    mode: str,\n    idle: str,\n    eco: bool,\n    target: float,\n    heat_target: float,\n    cool_target: float,\n    taken: tuple[float, float] | None,\n    settings: SetpointSettings,\n) -> HeadCommand:\n    \"\"\"The mode, setpoints, range delta and fan step one head is sent for the plan.\n\n    ``engage`` and ``temp`` are the plan's room (its engage, and the reading it\n    shows: None when rejected); ``mode`` is the plan's shared mode and ``idle`` the\n    head's parking mode (:func:`idle_park`). ``floor_run`` is a tripped floor's\n    want and its clear line; ``taken`` the low and high of a person's own run in\n    the floor's direction that the run took over (P10).\n    \"\"\"\n    if not enabled:\n        # A disabled room never idles in fan_only: a floor waiting out the mode\n        # is held off. (Without a floor, engage is off and decides first.)\n        idle = MODE_OFF\n    act = head_action(engage=engage, mode=mode, eco=eco, idle=idle)\n    low, high = setpoints(\n        mode=mode,\n        # A floor runs the head to its clear line, never the eco band.\n        target=target if floor_run is None else floor_run[1],\n        # Heat to while the shared mode is heat, Cool to while it's cool (the\n        # one target, twice, in a single-target room). A floor's clear line is\n        # its own target.\n        heat_target=heat_target if floor_run is None else None,\n        cool_target=cool_target if floor_run is None else None,\n        eco=eco and floor_run is None,\n        clamp_min=settings.clamp_min,\n        clamp_max=settings.clamp_max,\n        band=settings.band,\n        step=settings.step,\n        eco_cool=settings.eco_cool,\n        eco_heat=settings.eco_heat,\n    )\n    if floor_run is not None and taken is not None:\n        # A run taken over from a person's own heat keeps their setpoints where\n        # those are warmer than the clear line's (cooler, for a ceiling over\n        # their cool) (P10): their latest, if they changed them during the run\n        # (P15).\n        keep = max if floor_run[0] == MODE_HEAT else min\n        low, high = keep(low, taken[0]), keep(high, taken[1])\n    # How far the room sits outside its range (off its target, for a single\n    # target, where the range is the target itself).\n    delta = 0.0 if temp is None else range_delta(temp=temp, low=heat_target, high=cool_target)\n    # A floor delivery takes the fan-free path (engage None, as the standby park\n    # does): mode and setpoint only, so a manual fan pick is kept and MXZ never\n    # writes this head's fan.\n    return HeadCommand(\n        mode=act, low=low, high=high, delta=delta, fan=engage if floor_run is None else None\n    )\n\n\n@dataclass(frozen=True, slots=True)\nclass CoilDryMemory:\n    \"\"\"A head's coil-dry memory: its last run (None when none is kept) and whether its coil-dry\n    wakeup is armed.\"\"\"\n\n    last_run: tuple[str, float] | None\n    waiting: bool\n\n\n@dataclass(frozen=True, slots=True)\nclass ApplyHead:\n    \"\"\"One room's head as an apply reads it, when the apply reaches it.\n\n    ``settling`` is whether a change made at the head still holds it (``holds_change``) and\n    ``coil_dry`` the head's coil-dry memory. Both are called only when the apply reaches them,\n    in that order: reading ``settling`` can rebuild that memory and arm its wakeup (``planned``\n    reads the head's idle park), and a gate before either leaves both unread. ``head`` is the\n    state the head shows (None for none), ``hands_off`` the room's hands-off phase,\n    ``released`` whether its parking head has landed, ``busy`` whether a delivery runs on it,\n    ``startup`` whether its startup seed waits. ``floor_clear`` is a tripped floor's clear line\n    (None without a floor want) and ``taken_over`` the person's run a floor run took over.\n    \"\"\"\n\n    climate_id: str\n    vane_kick: bool\n    settling: Callable[[], bool]\n    paused: bool\n    head: str | None\n    hands_off: str | None\n    released: bool\n    busy: bool\n    startup: bool\n    enabled: bool\n    target: float\n    heat_target: float\n    cool_target: float\n    floor_clear: float | None\n    taken_over: tuple[str, float, float] | None\n    coil_dry: Callable[[], CoilDryMemory]\n\n\n@dataclass(frozen=True, slots=True)\nclass ApplyShared:\n    \"\"\"What every head's apply reads.\n\n    ``standby`` is the mode a fixed standby park sends every head (None when none parks them).\n    ``mode``, ``by_votes`` and ``resting`` are what the write-back reads: the shared mode now,\n    whether votes alone set it, and Resting mode.\n    \"\"\"\n\n    retired: bool\n    coordinator: bool\n    standby: str | None\n    inhibited: bool\n    eco: bool\n    idle_action: str\n    coil_dry_seconds: float\n    clock: float\n    settings: SetpointSettings\n    mode: str\n    by_votes: bool\n    resting: str | None\n\n\n@dataclass(frozen=True, slots=True)\nclass HeadApply:\n    \"\"\"What one apply does at one head: ``steps``, performed in order.\n\n    ``skip`` says why the head gets nothing more than its steps (``vane_kick``, ``settling``,\n    ``unavailable``: a paused head or a startup seed with no state, ``handback``: a released\n    hands-off room's hand-back, if any, is all it gets, ``landed``: a parking hands-off head is\n    off, ``dry``: a person's Dry is held); None for a head that is sent its command.\n    \"\"\"\n\n    climate_id: str\n    skip: str | None = None\n    steps: tuple[HeadStep, ...] = ()\n\n\n_VALID_ENGAGES = (MODE_COOL, MODE_HEAT, ENGAGE_SATISFIED, MODE_OFF)\n# A paused head's off: the queue call _apply made, with no delta and no fan step.\n_PAUSE_OFF = HeadCommand(mode=MODE_OFF, low=0.0, high=0.0, delta=0.0, fan=None)\n\n\ndef _head_apply(\n    room: RoomPlan, head: ApplyHead, state: str, shared: ApplyShared\n) -> HeadApply:\n    \"\"\"One head's part of an apply: its gates in order, then its idle park and command.\"\"\"\n    cid = head.climate_id\n    if head.vane_kick:\n        return HeadApply(cid, skip=\"vane_kick\")  # mid vane-kick: left alone until it finishes\n    if head.settling():\n        return HeadApply(cid, skip=\"settling\")  # a change made at the head is holding\n    if head.paused:\n        # Door/window pause: straight to off (no coil-dry run, no fan, setpoint or vane\n        # write), and only to a head that has a state. A person's fan pick on the off head is\n        # still read, so it is kept for the resume.\n        if head.head is None or head.head in UNAVAILABLE_STATES:\n            return HeadApply(cid, skip=\"unavailable\")\n        return HeadApply(cid, steps=(FanRead(MODE_OFF), Queue(_PAUSE_OFF)))\n    if head.hands_off in (\"parking\", \"released\") and not shared.inhibited:\n        # (A floor run skips all of this: the head is MXZ's for the run. Any standby hold,\n        # eco included, holds it off like any disabled room.)\n        if head.released:\n            # A floor run ended on a head a person was already running that way: theirs\n            # again, as they had it (P3). Its off landed: the head is someone else's now.\n            return HeadApply(cid, skip=\"handback\", steps=(HandBack(),))\n        if head.head == MODE_OFF and not head.busy:\n            return HeadApply(cid, skip=\"landed\", steps=(Landed(),))\n        # Otherwise the ordinary disabled path below sends off again.\n    if head.startup and (head.head is None or head.head in UNAVAILABLE_STATES):\n        # Do not make up the missing startup mode with a park or write of MXZ's. A known\n        # head still follows sensor-failure parking.\n        return HeadApply(cid, skip=\"unavailable\")\n    memory = head.coil_dry()\n    last_run = memory.last_run\n    steps: list[HeadStep] = []\n    dry = room.dry_state\n    if dry is not None:\n        if head.head == MODE_DRY:\n            # Dry wets the coil as cooling does: whenever the head leaves dry, the coil-dry\n            # run is owed from then. (A Dry picked on the thermostat and not reported yet\n            # hasn't.)\n            last_run = (MODE_COOL, shared.clock)\n            steps.append(LastRun(last_run))\n        if dry == \"held\":\n            # A person's dry: no mode, setpoint, fan or vane write.\n            return HeadApply(\n                cid, skip=\"dry\", steps=(*steps, Arm(\"dry\", cid, None), FanRead(MODE_DRY)),\n            )\n        # Another room won heat: park it at its idle action below, once told. Dry is never\n        # sent back.\n        steps.append(DryNotice())\n    park = idle_for(\n        cid, shared.idle_action, last_run, head.head, shared.coil_dry_seconds, shared.clock,\n        dry_waiting=memory.waiting,\n    )\n    floor = room.floor_want\n    floor_run = None\n    if floor:\n        if head.floor_clear is None:\n            raise ValueError(f\"{cid}: a floor want needs its clear line\")\n        floor_run = (floor, head.floor_clear)\n    taken = head.taken_over if floor == state else None\n    command = head_command(\n        engage=room.engage,\n        floor_run=floor_run,\n        temp=room.temp,\n        enabled=head.enabled,\n        mode=state,\n        idle=park.idle,\n        eco=shared.eco,\n        target=head.target,\n        heat_target=head.heat_target,\n        cool_target=head.cool_target,\n        taken=None if taken is None else (taken[1], taken[2]),\n        settings=shared.settings,\n    )\n    return HeadApply(cid, steps=(*steps, *park.steps, Queue(command, taken=taken is not None)))\n\n\ndef planned_act(\n    *,\n    active: str | None,\n    paused: bool,\n    state: str | None,\n    engage: str | None,\n    enabled: bool,\n    eco: bool,\n    idle: Callable[[], str],\n) -> str | None:\n    \"\"\"The mode the plan wants a head in now; None when no plan says.\n\n    ``active`` is the act of a delivery running on the head: a newer decision may already be\n    published while the head still reports an older operation, and the delivery owns its\n    writes. A paused room's head is off by plan, never drift. Otherwise the plan's (``state``,\n    the room's ``engage``; None for a head no room of the plan runs) as the apply would send it,\n    a disabled room parking off. ``idle`` is the head's parking mode (:func:`idle_for`), read\n    for any room the plan runs, as the apply reads it.\n    \"\"\"\n    if active is not None:\n        return active\n    if paused:\n        return MODE_OFF\n    if state not in (MODE_COOL, MODE_HEAT) or engage is None:\n        return None\n    if engage not in _VALID_ENGAGES:\n        return None\n    parked = idle()\n    return head_action(engage=engage, mode=state, eco=eco, idle=parked if enabled else MODE_OFF)\n\n\ndef apply_gate(plan: Plan, shared: ApplyShared) -> str | None:\n    \"\"\"Why an apply leaves the plan unapplied, in the order the gates run: this coordinator\n    ``retired``, the Coordinator switch off (``coordinator_off``: the heads are left\n    untouched), a fixed ``standby`` park (every head is sent its park mode instead), a plan\n    ``not_ready`` and an engage this does not know (``unknown_engage``). None: the plan is\n    applied.\"\"\"\n    if shared.retired:\n        return \"retired\"\n    if not shared.coordinator:\n        return \"coordinator_off\"\n    if shared.standby is not None:\n        return \"standby\"\n    if plan.state not in (MODE_COOL, MODE_HEAT):\n        return \"not_ready\"\n    if any(room.engage not in _VALID_ENGAGES for room in plan.rooms):\n        return \"unknown_engage\"\n    return None\n\n\ndef apply_plan(\n    plan: Plan, heads: Iterable[ApplyHead], shared: ApplyShared\n) -> Iterator[HeadApply | ModeWriteBack]:\n    \"\"\"What one apply does, in the order it is done: each head's part in room order, then the\n    plan's mode write-back.\n\n    ``heads`` is read one head at a time, as the apply reaches it, and each part is decided only\n    once the part before it has been taken: the caller performs a part before asking for the\n    next, so a head's gates read what the heads before it left (reading a head's ``settling``\n    can arm its coil-dry wakeup). For a fixed standby park (:func:`apply_gate`) each head is\n    sent the park mode, mode only (never the fan machinery, so a manual fan hold survives the\n    hold), except one mid vane-kick, and nothing is written back. For any other gate nothing is\n    done. The write-back comes after every head's part and before any head is sent anything:\n    the heads' commands are only queued until then.\n    \"\"\"\n    gate = apply_gate(plan, shared)\n    if gate == \"standby\" and shared.standby is not None:\n        park = HeadCommand(mode=shared.standby, low=0.0, high=0.0, delta=0.0, fan=None)\n        for head in heads:\n            if head.vane_kick:\n                yield HeadApply(head.climate_id, skip=\"vane_kick\")\n            else:\n                yield HeadApply(head.climate_id, steps=(Queue(park),))\n        return\n    if gate is not None:\n        return\n    state = plan.state\n    for room, head in zip(plan.rooms, heads):\n        yield _head_apply(room, head, state, shared)\n    yield mode_write_back(\n        shared.mode,\n        shared.by_votes,\n        state=state,\n        by_hands_off=plan.mode_by_hands_off,\n        calls=(*(room.engage for room in plan.rooms), *(room.demand for room in plan.rooms)),\n        resting=shared.resting,\n    )\n\n\n@dataclass(frozen=True, slots=True)\nclass DeliverySteps:\n    \"\"\"What one head's delivery does besides its mode and setpoints.\n\n    ``handback``: the fan goes back to auto before the mode, on the way to off.\n    ``last_run``: the act is the head's last run, which the coil-dry run counts from.\n    ``ends_coil_dry``: the act ends a coil-dry run's wakeup.\n    ``fan_machinery``: the delivery has a fan step at all (not a fixed standby\n    park or a floor); :meth:`fan` says which.\n    \"\"\"\n\n    handback: bool\n    last_run: bool\n    ends_coil_dry: bool\n    fan_machinery: bool\n\n    @property\n    def order(self) -> tuple[str, ...]:\n        \"\"\"The delivery's steps at a local head, in order.\n\n        ``\"note\"``: the coil-dry note (:meth:`note`). ``\"handback\"``, only\n        with a hand-back: the fan back to auto (the fan boost step for fan_only). ``\"setpoints\"``:\n        the mode and setpoints. ``\"fan\"``, only with fan machinery: :meth:`fan`, which reads\n        the standby hold again when it runs. After each step that writes to the head, the\n        delivery stops if it is no longer owned.\n        \"\"\"\n        return (\n            \"note\",\n            *((\"handback\",) if self.handback else ()),\n            \"setpoints\",\n            *((\"fan\",) if self.fan_machinery else ()),\n        )\n\n    def note(self, head: Hashable, act: str, at: float) -> tuple[MemoryStep, ...]:\n        \"\"\"The coil-dry note: what sending ``head`` ``act`` at ``at`` does to its coil-dry\n        memory, in order. ``act`` becomes its last run, then its coil-dry wakeup is cancelled.\"\"\"\n        return (\n            *((LastRun((act, at)),) if self.last_run else ()),\n            *((Arm(\"dry\", head, None),) if self.ends_coil_dry else ()),\n        )\n\n    def fan(self, *, inhibited: bool) -> str | None:\n        \"\"\"The step after the mode and setpoints.\n\n        ``\"drop_rung\"`` after a hand-back (the ladder starts from the bottom\n        next run), ``\"boost\"`` (the fan boost step for the act) outside a\n        standby hold, or None (no fan step). ``inhibited`` is the standby hold\n        as read when this step runs. A local head reads it again after its mode\n        write returns, so a hold that starts or ends during the write decides\n        this step, while the hand-back, decided before the write, stands.\n        \"\"\"\n        if not self.fan_machinery:\n            return None\n        if self.handback:\n            return \"drop_rung\"\n        return None if inhibited else \"boost\"\n\n\ndef delivery_steps(\n    act: str,\n    engage: str | None,\n    *,\n    idle_action: str,\n    eco: bool,\n    inhibited: bool,\n    head_state: str | None,\n) -> DeliverySteps:\n    \"\"\"What a delivery of ``act`` does at its head besides the mode and setpoints.\n\n    ``engage`` None is a fixed standby park or a floor: no coil-dry note and no\n    fan machinery. ``head_state`` is the state the head shows, None for none.\n\n    Heat or cool is the head's last run, and anything but fan_only ends a\n    coil-dry run's wakeup. The fan goes back to auto before an off only on a\n    head that is on now, parked off by the plan (an idle action other than\n    fan_only, a room that is not off), outside eco and a standby hold\n    (``inhibited``, as read before the delivery's first write). A local head is\n    sent the hand-back, then the mode and setpoints, then the fan step\n    (:meth:`DeliverySteps.fan`); a cloud head's batch carries the same decisions.\n    \"\"\"\n    if engage is None:\n        return DeliverySteps(\n            handback=False, last_run=False, ends_coil_dry=False, fan_machinery=False,\n        )\n    handback = (\n        act == MODE_OFF and idle_action != IDLE_ACTION_FAN_ONLY\n        and engage != MODE_OFF and not eco and not inhibited\n        and head_state is not None and head_state not in (MODE_OFF, *UNAVAILABLE_STATES)\n    )\n    return DeliverySteps(\n        handback=handback,\n        last_run=act in (MODE_COOL, MODE_HEAT),\n        ends_coil_dry=act != MODE_FAN_ONLY,\n        fan_machinery=True,\n    )\n\n\ndef setpoint_field(mode: str, *, features: int | None, cloud: bool) -> str | None:\n    \"\"\"The head setpoint that carries the room's target in the mode the head shows.\n\n    The one MXZ writes: the high edge in cool, the low edge in heat, or the one\n    setpoint of a head without a range (``features`` lacks\n    ``TARGET_TEMPERATURE_RANGE``, 2) or of a cloud head. None off heat and cool.\n    \"\"\"\n    if mode not in (MODE_COOL, MODE_HEAT):\n        return None\n    if cloud or not int(features or 0) & 2:\n        return \"temperature\"\n    return \"target_temp_high\" if mode == MODE_COOL else \"target_temp_low\"\n\n\ndef head_moved(\n    *,\n    accept: bool,\n    old_mode: str | None,\n    new_mode: str | None,\n    field: str | None,\n    old_setpoint: Any,\n    new_setpoint: Any,\n) -> set[str]:\n    \"\"\"What a head's report moved that a person may have changed: \"mode\", \"setpoint\".\n\n    ``field`` is the setpoint carrying the room's target in the new mode\n    (:func:`setpoint_field`), and the setpoints are that field's values as\n    reported, compared as they are. Nothing with Accept changes off, and nothing\n    from or to no state or unavailable: that is the head (re)loading. A fan or\n    vane report moves nothing.\n    \"\"\"\n    if (\n        not accept or old_mode is None or new_mode is None\n        or old_mode in UNAVAILABLE_STATES or new_mode in UNAVAILABLE_STATES\n    ):\n        return set()\n    moved = {\"mode\"} if old_mode != new_mode else set()\n    if field is not None and old_setpoint != new_setpoint:\n        moved.add(\"setpoint\")\n    return moved\n\n\n@dataclass(frozen=True, slots=True)\nclass HeadChange:\n    \"\"\"A change a head shows, and its room, as :func:`adopt_head_change` reads them.\n\n    ``moved`` is what moved since the hold began (:func:`head_moved`). The gates:\n    Accept changes made at the head (``accept``), this coordinator retired, the\n    Coordinator switch on (``coordinator``), a standby hold (``inhibited``),\n    eco, a start still quiet (``starting``), a disabled hands-off room's head\n    (``hands_off``), a floor run (``floor``), a door/window pause (``paused``),\n    and a cloud head's report of an older mode (``stale``).\n\n    ``mode`` is the mode the head shows, None for no state or unavailable, and\n    ``mode_own`` whether MXZ's own writes explain it. ``enabled`` is the room's\n    enable, and ``planned`` the mode the plan wants for the head now, read only\n    for an off pressed at an enabled room's head (reading it can arm the\n    coil-dry wakeup). ``field`` is the setpoint carrying the room's target\n    (:func:`setpoint_field`), ``setpoint`` its value, None if unreadable,\n    ``setpoint_own`` whether MXZ's own writes explain it and ``setpoint_stale``\n    whether it is a cloud head's poll from before MXZ's last batch. ``driven``\n    is a cloud head run past the target by its drive offset. ``target`` is the\n    room target on the room's step that leaves the head at ``setpoint``, held\n    to the room's bounds, ``current`` the room's target on that side now, and\n    ``step`` the target step.\n    \"\"\"\n\n    moved: Collection[str]\n    accept: bool\n    retired: bool\n    coordinator: bool\n    inhibited: bool\n    eco: bool\n    starting: bool\n    hands_off: bool\n    floor: bool\n    paused: bool\n    stale: bool\n    mode: str | None\n    mode_own: bool\n    enabled: bool\n    planned: Callable[[], str | None]\n    field: str | None\n    setpoint: float | None\n    setpoint_own: bool\n    setpoint_stale: bool\n    driven: bool\n    target: float | None\n    current: float | None\n    step: float\n\n\n@dataclass(frozen=True, slots=True)\nclass Adoption:\n    \"\"\"What a person's change at a head asks of its room: its new enable and target.\n\n    Neither is a person's change with nothing to adopt, like a heat/cool choice:\n    the head still goes back on the plan.\n    \"\"\"\n\n    enable: bool | None = None\n    target: float | None = None\n\n    def as_dict(self) -> dict[str, Any]:\n        \"\"\"The change as the coordinator keeps and logs it: ``enable`` first, then ``target``.\"\"\"\n        change: dict[str, Any] = {} if self.enable is None else {\"enable\": self.enable}\n        if self.target is not None:\n            change[\"target\"] = self.target\n        return change\n\n\ndef adopt_head_change(change: HeadChange) -> Adoption | None:\n    \"\"\"What a change at a head asks of its room now; None if it isn't a person's.\n\n    Only what moved counts, and only if MXZ's own writes can't explain it, so a\n    mode change alone never reads the setpoint the head happened to be on as a\n    new target. An off pressed at an enabled room's head disables the room,\n    unless the plan itself wants the head off. Heat or cool pressed at a\n    disabled room's head enables it. A setpoint pressed in heat or cool is the\n    room's new target when it differs from the room's by half a step or more,\n    except on a cloud head driven past the target. fan_only is the park, and\n    heat_cool, auto and dry are healed: none is adopted.\n    \"\"\"\n    if (\n        not change.accept or change.retired or not change.coordinator or change.inhibited\n        or change.eco or change.starting or change.mode is None\n        # A disabled hands-off room's head is the person's, on purpose; a floor\n        # run's is MXZ's until it ends; a paused room's has its own rule.\n        or change.hands_off or change.floor or change.paused or change.stale\n    ):\n        return None\n    mode_press = \"mode\" in change.moved and not change.mode_own\n    if change.mode == MODE_OFF:\n        if mode_press and change.enabled and change.planned() != MODE_OFF:\n            return Adoption(enable=False)\n        return None\n    if change.field is None:\n        return None\n    if not change.enabled and not mode_press:\n        return None\n    setpoint_press = (\n        \"setpoint\" in change.moved and change.setpoint is not None\n        and not change.setpoint_own and not change.setpoint_stale\n    )\n    if not mode_press and not setpoint_press:\n        return None\n    target = None\n    if (\n        setpoint_press and not change.driven\n        and change.target is not None and change.current is not None\n        and abs(change.target - change.current) >= change.step / 2\n    ):\n        target = change.target\n    return Adoption(enable=None if change.enabled else True, target=target)\n\n\ndef adopted(adoption: Adoption | None) -> bool:\n    \"\"\"Whether a change at a head asks anything of its room: a person's change with a target\n    or an enable in it. One with nothing to adopt, like a heat/cool choice, protects nothing.\"\"\"\n    return adoption is not None and bool(adoption.as_dict())\n\n\ndef holds_change(holding: bool, adoption: Callable[[], Adoption | None]) -> bool:\n    \"\"\"Whether a person's change at a head is still holding (``holding``: its adopt hold is\n    armed) and would still count: the apply leaves that head alone.\n\n    ``adoption`` is :func:`adopt_head_change` for what moved since the hold began, read only\n    while the hold is armed.\n    \"\"\"\n    return holding and adopted(adoption())\n\n\n@dataclass(frozen=True, slots=True)\nclass HeadReport:\n    \"\"\"What a head's report does to its adopt hold.\n\n    ``pending``: what moved since the hold began, to keep for its end; None drops it.\n    ``hold``: the hold armed for ``ADOPT_DELAY``, or cancelled. ``disown``: a command of MXZ's\n    still waiting for the head is no longer owed (a person's change is newer). ``replan``: the\n    report ended a hold with nothing adopted (a press taken back, say): the plan skipped the\n    head while it held, and arming it disowned any command still waiting, so re-plan.\n    \"\"\"\n\n    pending: set[str] | None\n    hold: Arm\n    disown: bool\n    replan: bool\n\n\ndef head_report(\n    moved: set[str],\n    pending: Collection[str],\n    *,\n    key: Hashable,\n    holding: bool,\n    adoption: Callable[[set[str]], Adoption | None],\n) -> HeadReport | None:\n    \"\"\"A head's report against its adopt hold; None when it moved nothing (:func:`head_moved`).\n\n    ``pending`` is what moved since the hold began, ``key`` the hold's key and ``holding``\n    whether it is armed. Each report that moves the mode or the setpoint starts the hold over,\n    with everything moved since it began; ``adoption`` judges that (:func:`adopt_head_change`).\n    A change with nothing to adopt (a heat/cool flip alone) holds nothing: the head goes back\n    on the plan at the next compute, as with the option off.\n    \"\"\"\n    if not moved:\n        return None\n    moved = moved | set(pending)\n    if not adopted(adoption(moved)):\n        return HeadReport(pending=None, hold=Arm(\"heal\", key, None), disown=False, replan=holding)\n    return HeadReport(pending=moved, hold=Arm(\"heal\", key, ADOPT_DELAY), disown=True, replan=False)\n\n\n@dataclass(frozen=True, slots=True)\nclass AdoptEnd:\n    \"\"\"What the end of an adopt hold writes.\n\n    ``seen``: the head-write fields whose memory takes what the head shows now\n    (``head_writes.writes_pressed``): ``HEAD_WRITE_MODE`` when the mode moved, the setpoint field when\n    the setpoint did. ``number``: the room's number the target goes to (``target``, or a dual\n    room's ``target_high`` in cool and ``target_low`` otherwise), None for no target.\n    ``target`` and ``enable``: the room's new target and enable (None: unchanged). Then a\n    compute is asked for.\n    \"\"\"\n\n    seen: tuple[str, ...]\n    number: str | None\n    target: float | None\n    enable: bool | None\n\n    @property\n    def steps(self) -> tuple[AdoptStep, ...]:\n        \"\"\"What the end writes, in order: the memory takes what the head shows, the room's\n        target, its enable, then the off heal is checked again against the room as it is now.\"\"\"\n        return (\n            Pressed(self.seen),\n            *((SetTarget(self.number, self.target),)\n              if self.number is not None and self.target is not None else ()),\n            *((SetEnable(self.enable),) if self.enable is not None else ()),\n            OffHealRecheck(),\n        )\n\n\n@dataclass(frozen=True, slots=True)\nclass Pressed:\n    \"\"\"MXZ's write memory takes what the head shows for ``fields`` (``writes_pressed``): a\n    person's change is what the head shows now, whatever MXZ wrote before it.\"\"\"\n\n    fields: tuple[str, ...]\n\n\n@dataclass(frozen=True, slots=True)\nclass SetTarget:\n    \"\"\"The room's ``number`` (``target``, ``target_high`` or ``target_low``) is set to ``value``,\n    through the room's own number.\"\"\"\n\n    number: str\n    value: float\n\n\n@dataclass(frozen=True, slots=True)\nclass SetEnable:\n    \"\"\"The room's enable is set to ``on``, through the room's own switch.\"\"\"\n\n    on: bool\n\n\n@dataclass(frozen=True, slots=True)\nclass OffHealRecheck:\n    \"\"\"The head's off heal, if armed, is checked again against the room as it is now\n    (:func:`off_heal_recheck`): an off adopted as \"disable the room\" is the room's, not drift.\"\"\"\n\n\ntype AdoptStep = Pressed | SetTarget | SetEnable | OffHealRecheck\n\n\ndef adopt_end(\n    moved: Collection[str], adoption: Adoption, *, mode: str, field: str | None, dual: bool\n) -> AdoptEnd:\n    \"\"\"The end of an adopt hold whose change still counts (``adoption``, judged again now).\n\n    ``moved`` is what moved since the hold began, ``mode`` the mode the head shows and\n    ``field`` the setpoint carrying the room's target in it (:func:`setpoint_field`).\n    \"\"\"\n    seen = (*((HEAD_WRITE_MODE,) if \"mode\" in moved else ()),\n            *((field,) if \"setpoint\" in moved and field else ()))\n    number = None\n    if adoption.target is not None:\n        number = \"target\"\n        if dual:\n            number += \"_high\" if mode == MODE_COOL else \"_low\"\n    return AdoptEnd(seen=seen, number=number, target=adoption.target, enable=adoption.enable)\n\n\n@dataclass(frozen=True, slots=True)\nclass StartupReport:\n    \"\"\"What a head's report does to its room's startup seed: ``cancel`` it (the room resumes\n    no run), and ``replan`` now.\"\"\"\n\n    cancel: bool\n    replan: bool\n\n\ndef startup_report(\n    mode: str | None,\n    old_mode: str | None,\n    *,\n    planned: Callable[[], str | None],\n    stale: Callable[[], bool],\n) -> StartupReport:\n    \"\"\"A report from the head of a room whose startup seed is still pending.\n\n    A reported off beyond MXZ's own sensor-failure park (``planned``, the mode the plan wants\n    for the head) cancels the remembered startup run, just like an off present at restore,\n    unless it is a cloud head's report of an older state (``stale``). Each is read only when\n    it decides. A real mode, new since the last report, re-plans.\n    \"\"\"\n    return StartupReport(\n        cancel=mode == MODE_OFF and planned() != MODE_OFF and not stale(),\n        replan=mode not in (None, *UNAVAILABLE_STATES) and mode != old_mode,\n    )\n\n\n@dataclass(frozen=True, slots=True)\nclass HoldEnd:\n    \"\"\"What the end of an adopt hold does: ``steps`` in order, then a compute asked for\n    (``refresh``), also after a write that is refused.\"\"\"\n\n    steps: tuple[AdoptStep, ...]\n    refresh: Refresh = Refresh.REQUEST\n\n\ndef hold_end(\n    moved: Collection[str],\n    adoption: Adoption | None,\n    *,\n    mode: str | None,\n    field: str | None,\n    dual: bool,\n) -> HoldEnd:\n    \"\"\"An adopt hold ends (its ``heal`` wakeup for ``(head, \"adopt\")`` ran).\n\n    ``moved`` is the pending set, taken: the hold's end consumes it. ``adoption`` is the change\n    judged again now (:func:`adopt_head_change` of :func:`head_change`); None adopts nothing and\n    only asks for a compute. ``mode`` and ``field`` are what the head shows now and the setpoint\n    carrying the room's target in it.\n    \"\"\"\n    if adoption is None or mode is None:\n        return HoldEnd(steps=())\n    return HoldEnd(steps=adopt_end(moved, adoption, mode=mode, field=field, dual=dual).steps)\n\n\ndef head_dropped(key: Hashable) -> HeadReport:\n    \"\"\"A change to the room in Home Assistant (its target, range or enable) during an adopt\n    hold ends the hold with nothing adopted: the later change wins. ``key`` is the hold's.\"\"\"\n    return HeadReport(pending=None, hold=Arm(\"heal\", key, None), disown=False, replan=False)\n\n\n# -- a person's write to a room's target, range or enable ------------------------------------\n@dataclass(frozen=True, slots=True)\nclass Latch:\n    \"\"\"The room's engage-latch entry becomes ``entry``: ``\"\"`` decides afresh, None forgets it\n    (an enabled, live room's next compute seeds it again from its head's mode, :func:`decide`).\"\"\"\n\n    entry: str | None\n\n\n@dataclass(frozen=True, slots=True)\nclass SeedDropped:\n    \"\"\"The room's startup seed, if one waits, is dropped: the room resumes no run.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass ReleaseEnded:\n    \"\"\"A hands-off room is no longer released: the plan drives its head again.\"\"\"\n\n\ntype RoomStep = HeadReport | ReleaseEnded | SeedDropped | Latch\n\n\ndef range_target(low: float, high: float) -> float:\n    \"\"\"A dual-setpoint room's target: the middle of its range.\"\"\"\n    return (low + high) / 2\n\n\ndef target_written(\n    head: Hashable, *, startup: bool, coordinator: bool, enabled: bool\n) -> tuple[RoomStep, ...]:\n    \"\"\"A person wrote a room's target, or its range (whose middle is the target,\n    :func:`range_target`): a fresh decision. What it does, in order.\n\n    ``head`` is the room's head. The adopt hold ends with nothing adopted\n    (:func:`head_dropped`). Then a room whose startup seed still waits (``startup``), under the\n    Coordinator switch off (``coordinator`` False), or disabled (``enabled`` False) drops the\n    seed and decides afresh: new intent must not revive an old pending run. Any other room\n    forgets its latch, which its next compute seeds again from its head's mode.\n    \"\"\"\n    if startup or not coordinator or not enabled:\n        latch: tuple[RoomStep, ...] = (SeedDropped(), Latch(\"\"))\n    else:\n        latch = (Latch(None),)\n    return (head_dropped((head, \"adopt\")), *latch)\n\n\ndef enable_written(head: Hashable, *, was_on: bool, on: bool) -> tuple[RoomStep, ...]:\n    \"\"\"A person turned a room on or off (``on``; it was ``was_on``). What it does, in order,\n    once the room's enable is ``on``.\n\n    Turned on, a hands-off room's release ends: the plan drives its head again, and the next\n    disablement parks afresh. Turned on from off, or off, is a fresh decision: its startup seed\n    is dropped and its latch decides afresh. Last, the adopt hold ends with nothing adopted\n    (:func:`head_dropped`); ``head`` is the room's head.\n    \"\"\"\n    return (\n        *((ReleaseEnded(),) if on else ()),\n        *((SeedDropped(), Latch(\"\")) if not was_on or not on else ()),\n        head_dropped((head, \"adopt\")),\n    )\n\n\ndef band_drift(mode: str | None, *, hands_off_head: bool, dry_allowed: bool) -> bool:\n    \"\"\"A head in a mode MXZ never runs (``BANNED_MODES``), unless it is a released hands-off\n    room's (``hands_off_head``) or in a Dry its room lets stay (``dry_allowed``).\"\"\"\n    return mode in BANNED_MODES and not hands_off_head and not dry_allowed\n\n\ndef off_while_enabled(\n    mode: str | None, *, enabled: bool, eco_idle: bool, planned: Callable[[], str | None]\n) -> bool:\n    \"\"\"Off while its room is enabled and the plan wants it on: the off heal's drift. ``planned``\n    (:func:`planned_act`) is read last, only for an off at an enabled room's head outside eco.\"\"\"\n    return mode == MODE_OFF and enabled and not eco_idle and planned() != MODE_OFF\n\n\ndef off_heal_recheck(\n    head: Hashable,\n    waiting: bool,\n    mode: str | None,\n    *,\n    enabled: bool,\n    eco_idle: bool,\n    planned: Callable[[], str | None],\n) -> Arm | None:\n    \"\"\":class:`OffHealRecheck` at ``head``: an armed off heal (``waiting``) whose head no longer\n    drifts (:func:`off_while_enabled`, ``mode`` as it shows now) is cancelled; None leaves it as\n    it is. A later re-enable is read from the head's next report, not from this wait.\"\"\"\n    if waiting and not off_while_enabled(mode, enabled=enabled, eco_idle=eco_idle, planned=planned):\n        return Arm(\"heal\", (head, \"off\"), None)\n    return None\n\n\ndef heal_due(\n    kind: str,\n    mode: str | None,\n    *,\n    hands_off_head: Callable[[], bool],\n    dry_allowed: Callable[[], bool],\n    enabled: bool,\n    eco_idle: bool,\n    planned: Callable[[], str | None],\n    stale: Callable[[], bool],\n    coordinator: bool,\n    inhibited: bool,\n) -> Refresh | None:\n    \"\"\"A ``band`` or ``off`` heal wait ran: if its drift still holds, the plan is applied to the\n    head again, so it returns the compute to ask for (and someone is told); None does nothing.\n    ``mode`` is what the head shows now; ``stale``, a cloud head's report of an older state, is\n    not drift. Each read is made only when it decides.\"\"\"\n    if kind == \"band\":\n        still = band_drift(mode, hands_off_head=hands_off_head(), dry_allowed=dry_allowed())\n    else:\n        still = off_while_enabled(mode, enabled=enabled, eco_idle=eco_idle, planned=planned)\n    return Refresh.REQUEST if still and not stale() and coordinator and not inhibited else None\n\n\n@dataclass(frozen=True, slots=True)\nclass AdoptGates:\n    \"\"\"What turns head-change adoption off for a head (:class:`HeadChange`'s gates): Accept\n    changes made at the head (``accept``), this coordinator retired, the Coordinator switch on\n    (``coordinator``), a standby hold (``inhibited``), eco, a start still quiet (``starting``),\n    a disabled hands-off room (``hands_off``), a floor run (``floor``) and a door/window pause\n    (``paused``).\"\"\"\n\n    accept: bool\n    retired: bool\n    coordinator: bool\n    inhibited: bool\n    eco: bool\n    starting: bool\n    hands_off: bool\n    floor: bool\n    paused: bool\n\n\ndef head_change(\n    moved: Collection[str],\n    *,\n    state: str | None,\n    attributes: Mapping[str, Any],\n    cloud: bool,\n    gates: AdoptGates,\n    enabled: bool,\n    heat_target: float,\n    cool_target: float,\n    driven: bool,\n    step: float,\n    memories: Mapping[str, HeadWriteMemory],\n    grid: Grid,\n    mode_stale: Callable[[str], bool],\n    setpoint_stale: Callable[[float], bool],\n    planned: Callable[[], str | None],\n) -> HeadChange:\n    \"\"\"The :class:`HeadChange` a head shows (``state`` and ``attributes``, None and empty for no\n    state) for what moved since its adopt hold began.\n\n    The head's mode is what it shows, None for no state or unavailable; the setpoint is the one\n    carrying the room's target in it (:func:`setpoint_field`), as a number. Whether MXZ's own\n    writes explain each is read off ``memories`` on the head's ``grid``. The candidate target is\n    the target on the room's step that leaves the head where a person put it\n    (``Grid.target_for_setpoint``), held to the bounds a target may take on it. ``current`` is\n    the room's Cool to in cool and its Heat to otherwise. ``driven`` is a cloud head run past\n    the target by its drive offset. ``mode_stale`` and ``setpoint_stale`` say whether a cloud\n    head's poll is from before MXZ's last batch; ``step`` is the room's target step.\n    \"\"\"\n    mode = state if state is not None and state not in UNAVAILABLE_STATES else None\n    field: str | None = None\n    shown: float | None = None\n    if mode is not None:\n        field = setpoint_field(mode, features=attributes.get(\"supported_features\"), cloud=cloud)\n        shown = None if field is None else as_float(attributes.get(field))\n    target = None if shown is None else clamp(grid.target_for_setpoint(shown), grid.target_bounds())\n    return HeadChange(\n        moved=moved,\n        accept=gates.accept,\n        retired=gates.retired,\n        coordinator=gates.coordinator,\n        inhibited=gates.inhibited,\n        eco=gates.eco,\n        starting=gates.starting,\n        hands_off=gates.hands_off,\n        floor=gates.floor,\n        paused=gates.paused,\n        stale=mode is not None and mode_stale(mode),\n        mode=mode,\n        mode_own=mode is not None and write_is_own(memories, HEAD_WRITE_MODE, mode, grid),\n        enabled=enabled,\n        planned=planned,\n        field=field,\n        setpoint=shown,\n        setpoint_own=(\n            shown is not None and field is not None and write_is_own(memories, field, shown, grid)\n        ),\n        setpoint_stale=shown is not None and setpoint_stale(shown),\n        driven=driven,\n        target=target,\n        current=cool_target if mode == MODE_COOL else heat_target,\n        step=step,\n    )\n\n\n# -- a head's report -------------------------------------------------------------------------\n# The attribute a head's run shows (Home Assistant's ATTR_HVAC_ACTION).\n_HVAC_ACTION = \"hvac_action\"\n\n\n@dataclass(frozen=True, slots=True)\nclass FanShown:\n    \"\"\"The head shows ``fan``: the fan writes before it are behind it (``FanEcho.caught_up``).\"\"\"\n\n    fan: Any\n\n\n@dataclass(frozen=True, slots=True)\nclass WritesShown:\n    \"\"\"MXZ's mode and setpoint writes before this report are behind the head for good\n    (``head_writes.writes_caught_up``).\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass SightLost:\n    \"\"\"MXZ loses sight of the head: what it showed just before (``observe_old``: the old state\n    was in sight) is its last-known vote, then it is out of sight (``HeadSight``).\"\"\"\n\n    observe_old: bool\n\n\n@dataclass(frozen=True, slots=True)\nclass SightObserved:\n    \"\"\"The head's run as it shows it now is observed (``HeadSight.observe``): a parking\n    hands-off head's run MXZ drove ends here.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass SeedCancelled:\n    \"\"\"The room's startup seed is cancelled: it resumes no run.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass FloorYielded:\n    \"\"\"A person's mode change takes a hands-off head back from the floor run (decision 8b).\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass TakenOver:\n    \"\"\"A person's change at a paused room's head takes the room over until the opening\n    closes.\"\"\"\n\n\ntype ReportStep = (\n    FanShown | WritesShown | SightLost | SightObserved | SeedCancelled | Landed | FloorYielded\n    | TakenOver | Arm | LastRun | HeadReport | Refresh\n)\n\n\n@dataclass(frozen=True, slots=True)\nclass ReportedHead:\n    \"\"\"A head's report as MXZ reads it.\n\n    ``key`` is the head. ``mode`` and ``attributes`` are what the new state shows (None and\n    empty for none), ``old_mode`` and ``old_attributes`` the state before it. Read before the\n    report does anything: ``accept`` (Accept changes made at the head), ``cloud`` (a cloud\n    head), ``sight`` (MXZ keeps sight of it), ``released_by_action`` (a released hands-off room\n    votes by its run), ``startup`` (its room's startup seed waits), ``owned_off`` (no command of\n    MXZ's but an off runs on it), ``parking`` (its hands-off room is parking), ``kicking`` (a\n    vane kick runs or just woke it), ``floor_run`` (a floor run has it), ``paused`` (its room\n    is paused for an opening), ``stale`` (a cloud head's report of an older state), ``allow_dry``\n    (its room offers Dry), ``dry_allowed`` (a Dry its room lets stay), ``enabled``,\n    ``eco_idle``, ``inhibited`` (a standby hold), ``unresponsive`` (a cloud head out of control\n    reported again), ``pending`` (what moved since its adopt hold began) and ``holding`` (the\n    hold is armed).\n\n    Read when the report reaches them, after what it did before: ``hands_off_head`` (its room\n    is a released hands-off room: a floor run the report ended released it), ``dry_reported``\n    (Dry's reading of the report, which keeps what it reads; true when it ends a room's Dry),\n    ``planned`` (:func:`planned_act`; reading it can rebuild the head's coil-dry memory and arm\n    its wakeup, ``IdlePark.steps``), ``clock`` and ``adoption`` (:func:`adopt_head_change` of\n    :func:`head_change` for what moved).\n    \"\"\"\n\n    key: str\n    mode: str | None\n    attributes: Mapping[str, Any]\n    old_mode: str | None\n    old_attributes: Mapping[str, Any]\n    accept: bool\n    cloud: bool\n    sight: bool\n    released_by_action: bool\n    startup: bool\n    owned_off: bool\n    parking: bool\n    kicking: bool\n    floor_run: bool\n    paused: bool\n    stale: bool\n    allow_dry: bool\n    dry_allowed: bool\n    enabled: bool\n    eco_idle: bool\n    inhibited: bool\n    unresponsive: bool\n    pending: Collection[str]\n    holding: bool\n    hands_off_head: Callable[[], bool]\n    dry_reported: Callable[[], bool]\n    planned: Callable[[], str | None]\n    clock: Callable[[], float]\n    adoption: Callable[[set[str]], Adoption | None]\n\n\ndef report_steps(r: ReportedHead) -> Iterator[ReportStep]:\n    \"\"\"What a head's report does, in order; each step is done before the next is decided.\n\n    The fan echo and MXZ's write memory catch up on what it shows. Out of sight: its last-known\n    vote is kept. A startup seed it cancels (:func:`startup_report`). A parking hands-off head\n    seen off with nothing of MXZ's but an off in flight has landed. A person's real mode change\n    (between two available states, not a vane kick, not stale) to anything but what the plan\n    wants takes a floor-run head back, and, to anything but off, a paused room over. The band\n    heal wait is armed or cancelled (:func:`band_drift`); leaving dry owes the coil-dry run from\n    now. The off heal wait (:func:`off_while_enabled`, outside a standby hold). The adopt hold\n    (:func:`head_report`). Last, the compute it asks for (``timing.head_refresh``), if any: at\n    once for a released room that votes by its run and started or stopped one, else for any\n    step that re-plans or anything new the head shows.\n    \"\"\"\n    mode, old_mode = r.mode, r.old_mode\n    key = r.key\n    if mode is not None:\n        yield FanShown(r.attributes.get(\"fan_mode\"))\n        yield WritesShown()\n    replan = False\n    lost = mode in (None, STATE_UNAVAILABLE)\n    if r.sight and lost:\n        yield SightLost(observe_old=old_mode is not None and old_mode != STATE_UNAVAILABLE)\n    if r.sight and lost != (old_mode is None or old_mode == STATE_UNAVAILABLE):\n        # Out of sight, or back: unknown <-> unavailable recomputes the vote now too.\n        replan = True\n    run = False\n    if mode is not None and old_mode is not None and r.released_by_action:\n        run = run_changed(\n            old_mode, mode, r.old_attributes.get(_HVAC_ACTION), r.attributes.get(_HVAC_ACTION),\n        )\n    if r.startup:\n        seed = startup_report(mode, old_mode, planned=r.planned, stale=lambda: r.stale)\n        if seed.cancel:\n            yield SeedCancelled()\n        if seed.replan:\n            replan = True\n    if mode == MODE_OFF and r.owned_off and r.parking:\n        yield Landed()\n        if r.sight:\n            yield SightObserved()\n    real = (\n        mode != old_mode and mode not in (None, *UNAVAILABLE_STATES)\n        and old_mode not in (None, *UNAVAILABLE_STATES) and not r.kicking and not r.stale\n    )\n    if real and r.floor_run and mode != r.planned():\n        yield FloorYielded()\n        replan = True\n    if real and mode != MODE_OFF and r.paused and mode != r.planned():\n        yield TakenOver()\n        replan = True\n    band = band_drift(mode, hands_off_head=r.hands_off_head(), dry_allowed=r.dry_allowed)\n    yield Arm(\"heal\", (key, \"band\"), BAND_DRIFT_DELAY if band and not r.stale else None)\n    if (mode == MODE_DRY) != (old_mode == MODE_DRY) and r.allow_dry:\n        replan = True\n        if old_mode == MODE_DRY and not r.stale and mode not in (None, *UNAVAILABLE_STATES):\n            # Dry wets the coil as cooling does: leaving it owes the coil-dry run from now.\n            yield LastRun((MODE_COOL, r.clock()))\n    if r.dry_reported():\n        replan = True\n    off = (\n        off_while_enabled(mode, enabled=r.enabled, eco_idle=r.eco_idle, planned=r.planned)\n        and not r.inhibited and not r.stale\n    )\n    yield Arm(\"heal\", (key, \"off\"), OFF_WHILE_ENABLED_DELAY if off else None)\n    field = None if mode is None else setpoint_field(\n        mode, features=r.attributes.get(\"supported_features\"), cloud=r.cloud,\n    )\n    moved = head_moved(\n        accept=r.accept, old_mode=old_mode, new_mode=mode, field=field,\n        old_setpoint=None if old_mode is None or field is None else r.old_attributes.get(field),\n        new_setpoint=None if mode is None or field is None else r.attributes.get(field),\n    )\n    report = head_report(moved, r.pending, key=(key, \"adopt\"), holding=r.holding, adoption=r.adoption)\n    if report is not None:\n        yield report\n        replan = replan or report.replan\n    if r.unresponsive:\n        replan = True\n    refresh = head_refresh(\n        run_changed=run,\n        moved=replan or head_shows_new(old_mode, mode, r.old_attributes, r.attributes),\n    )\n    if refresh is not None:\n        yield refresh\n",
 "custom_components/mxz_coordinator/resume.py": "\"\"\"Restart resume: what a start takes back from the room state store and the mode record.\n\nStandard library only, so the simulator and the tests call it without Home Assistant.\n``MXZCoordinator`` reads the store (:class:`SavedState`) and the mode record, gathers each\nroom's head and target bounds, and applies what these return through the same calls an\nentity's restore data uses:\n\n- :func:`mode_record` reads a stored mode record with the wall clock, and\n  :func:`resumed_mode` weighs it against the shared-mode select's restore data;\n- :func:`resume` reads every room's values, the switches, each head's fan hold and MXZ's\n  memory of its head writes out of the store, and says which values the store resumes;\n- :func:`resumed_enable` is what a resumed enable does to the engage latch and the startup\n  seeds, the hands-off release and the floor record.\n\nTime comes in as numbers. Which source wins (the store, or an entity's newer restore data),\nand when each is read, stays with the coordinator and the entities.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections.abc import Mapping, Sequence\nfrom dataclasses import dataclass, field\nfrom datetime import datetime\nfrom typing import Any\n\nfrom .const import (\n    HEAD_WRITES_REMEMBERED,\n    KEY_COOL_LOCKOUT,\n    KEY_COORDINATOR_ENABLE,\n    KEY_ECO_IDLE,\n    KEY_HEAT_LOCKOUT,\n    MODE_COOL,\n    MODE_HEAT,\n)\nfrom .fan_latch import FanRecord\nfrom .head_writes import HEAD_WRITE_FIELDS\nfrom .logic import HeadWriteMemory, finite_number\nfrom .units import offset_in_unit, snap_to_step, target_in_unit\n\n# The room state store's sections (room_state.py says what each holds).\nSECTION_ROOMS = \"rooms\"\nSECTION_SWITCHES = \"switches\"\nSECTION_FAN = \"fan\"\nSECTION_FLOOR = \"floor\"\nSECTION_MODE = \"mode\"\nSECTION_OPENINGS = \"openings\"\nSECTION_HEAD_WRITES = \"head_writes\"\n\n# The switches the room state store keeps; each is a coordinator attribute of that name.\nSWITCH_KEYS = (KEY_COORDINATOR_ENABLE, KEY_ECO_IDLE, KEY_HEAT_LOCKOUT, KEY_COOL_LOCKOUT)\n\n# What MXZ remembers of its head writes (logic.HeadWriteMemory), by service field.\n\n# The mode record: the room state store's ``mode`` section, and for one release also its\n# own file (coordinator.py, where it is written and loaded). It holds the time of the last\n# real change (MODE_CHANGE_KEY, absent while none was ever made) and the shared mode as of\n# MODE_AT_KEY, with whether hands-off votes alone set it (MODE_BY_VOTES_KEY). Earlier\n# versions wrote the time only; their records read as before, with no mode on record.\n# Times are wall-clock UTC epoch seconds, the only clock that means anything to the next\n# process.\nMODE_CHANGE_KEY = \"last_mode_change\"\nMODE_KEY = \"mode\"\nMODE_AT_KEY = \"mode_at\"\nMODE_BY_VOTES_KEY = \"mode_by_votes\"\n\n\n@dataclass(frozen=True)\nclass SavedState:\n    \"\"\"What the store held at a start.\n\n    ``readable`` is False for a store that can't be loaded, such as one a later\n    release wrote: it is neither read nor written over. Without ``saved_at`` the store is older than any restore\n    record.\n    \"\"\"\n\n    saved_at: float | None = None\n    unit: str | None = None\n    sections: Mapping[str, dict[str, Any]] = field(default_factory=dict)\n    readable: bool = True\n\n    def section(self, name: str) -> dict[str, Any] | None:\n        \"\"\"One section as stored, or None.\"\"\"\n        return self.sections.get(name)\n\n    def item(self, name: str, key: str) -> dict[str, Any] | None:\n        \"\"\"One head's (or one switch section's) record, or None if it isn't a record.\"\"\"\n        value = (self.sections.get(name) or {}).get(key)\n        return value if isinstance(value, dict) else None\n\n    def outranks(self, recorded_at: datetime | None) -> bool:\n        \"\"\"Whether this store is newer than a restore record taken at ``recorded_at``.\n\n        No record (None) is always older. A record as new as the store or newer\n        was written after it, by this release or by an earlier one after a\n        rollback, and wins.\n        \"\"\"\n        if recorded_at is None:\n            return True\n        return self.saved_at is not None and self.saved_at > recorded_at.timestamp()\n\n\n@dataclass(frozen=True)\nclass ModeRecord:\n    \"\"\"The entry's mode-change record, as a start reads it.\n\n    ``changed_at`` is the last real cool/heat change (None: none on record).\n    ``mode`` is the shared mode when the record was written at ``mode_at``,\n    and ``by_votes`` whether hands-off votes alone had set it; ``mode`` is\n    None when the record has no readable mode (an earlier version wrote it).\n    \"\"\"\n\n    changed_at: float | None = None\n    mode: str | None = None\n    mode_at: float = 0.0\n    by_votes: bool = False\n\n    def stored(self) -> dict[str, Any] | None:\n        \"\"\"The record as it is written; None for no record.\"\"\"\n        data: dict[str, Any] = {}\n        if self.mode is not None:\n            data = {MODE_KEY: self.mode, MODE_AT_KEY: self.mode_at, MODE_BY_VOTES_KEY: self.by_votes}\n        if self.changed_at is not None:\n            data[MODE_CHANGE_KEY] = self.changed_at\n        return data or None\n\n\ndef mode_record(stored: Any, now: float) -> tuple[ModeRecord, bool]:\n    \"\"\"The mode record a start reads from ``stored``, and whether its change time was unreadable.\n\n    ``stored`` is the record as loaded (None: there is none) and ``now`` the wall clock.\n\n    No change time means no change was ever recorded (a fresh install, the\n    first start on a version that did not keep it, or a record that so far\n    holds only a mode votes chose): there is nothing to wait out. A record\n    that is there but whose time is unreadable is not a fresh install; it\n    counts as a change made now, so the hold is the full window, as it was\n    before this was kept. A mode that is not readable is no mode on record.\n    \"\"\"\n    if stored is None:\n        return ModeRecord(), False\n    data: Any = stored if isinstance(stored, dict) else {}\n    mode, mode_at, by_votes = (\n        data.get(MODE_KEY), data.get(MODE_AT_KEY), data.get(MODE_BY_VOTES_KEY)\n    )\n    has_mode = (\n        mode in (MODE_COOL, MODE_HEAT) and finite_number(mode_at)\n        and isinstance(by_votes, bool)\n    )\n    shared: dict[str, Any] = (\n        {\"mode\": mode, \"mode_at\": float(mode_at), \"by_votes\": by_votes} if has_mode else {}\n    )\n    value = data.get(MODE_CHANGE_KEY)\n    if finite_number(value):\n        return ModeRecord(changed_at=float(value), **shared), False\n    if has_mode and MODE_CHANGE_KEY not in data:\n        return ModeRecord(changed_at=None, **shared), False\n    return ModeRecord(changed_at=now, **shared), True\n\n\ndef resumed_mode(\n    record: ModeRecord, restored: str | None, restored_at: float | None\n) -> tuple[str, bool]:\n    \"\"\"The shared mode a start resumes in, and whether votes alone set it.\n\n    ``restored`` is the shared-mode select's restored option (None: no restore\n    data) and ``restored_at`` when that state last changed (wall clock). The\n    record is written at every change, at once, and restore data only every\n    15 minutes and at a stop, so where the two disagree the record wins unless\n    the restore data is newer: then the mode changed while a version that did\n    not keep it in the record ran, and it is not known whether votes set it.\n    Where they agree the record also says whether votes set the mode (the\n    select's state is written anew at every start, so its time says nothing\n    then).\n    \"\"\"\n    if record.mode is None:\n        mode, by_votes = restored or MODE_COOL, False\n    elif (\n        restored in (None, record.mode)\n        or restored_at is None\n        or record.mode_at >= restored_at\n    ):\n        mode, by_votes = record.mode, record.by_votes\n    else:\n        mode, by_votes = restored, False\n    return mode, by_votes\n\n\n@dataclass(frozen=True, slots=True)\nclass RoomSlot:\n    \"\"\"A room as resume reads it: its head, its slug, and its head's target bounds.\"\"\"\n\n    climate_id: str\n    slug: str\n    bounds: tuple[float, float]\n\n\n@dataclass(frozen=True, slots=True)\nclass RoomResume:\n    \"\"\"What the store resumes of one room; None (and ``has_drift`` False) where it holds nothing.\n\n    ``target`` is in the system unit, on the target step, held to the head's bounds;\n    ``target_range`` is the Heat to / Cool to pair, only when both edges are stored.\n    ``drift`` None with ``has_drift`` is a stored \"follow the global\". ``enable_record``\n    is the floor record and the hands-off release that go with a stored enable.\n    \"\"\"\n\n    target: float | None = None\n    target_range: tuple[float, float] | None = None\n    has_drift: bool = False\n    drift: float | None = None\n    enable: bool | None = None\n    enable_record: dict[str, Any] = field(default_factory=dict)\n    fan: FanRecord | None = None\n    head_writes: dict[str, HeadWriteMemory] = field(default_factory=dict)\n\n\n@dataclass(frozen=True, slots=True)\nclass Resume:\n    \"\"\"What the store resumes: the switches, each room in order, and which values it holds.\n\n    ``resumed`` names each value as ``MXZCoordinator.store_resumes`` does: (\"switch\", key),\n    (\"target\" | \"range\" | \"drift\" | \"enable\", slug), (\"fan\", climate_id).\n    \"\"\"\n\n    switches: dict[str, bool]\n    rooms: tuple[RoomResume, ...]\n    resumed: frozenset[tuple[str, str]]\n\n\ndef saved_temperature(value: Any, saved_in: str | None, unit: str, step: float) -> float | None:\n    \"\"\"A stored temperature in ``unit``, on ``step``; None if it isn't one.\"\"\"\n    if not finite_number(value):\n        return None\n    return target_in_unit(float(value), saved_in, unit, step)\n\n\ndef saved_drift(\n    value: float | None, saved_in: str | None, celsius: bool, bounds: tuple[float, float]\n) -> float | None:\n    \"\"\"A stored drift override in the system unit, held to ``bounds``; None follows the global.\n\n    A band is a difference, so it only scales, onto the drift number's step.\n    \"\"\"\n    if value is None:\n        return None\n    lo, hi = bounds\n    scaled = offset_in_unit(float(value), saved_in, celsius)\n    if scaled != value:\n        scaled = snap_to_step(scaled, lo / 2)\n    return min(max(scaled, lo), hi)\n\n\ndef resume(\n    saved: SavedState,\n    rooms: Sequence[RoomSlot],\n    *,\n    unit: str,\n    step: float,\n    celsius: bool,\n    engage_bounds: tuple[float, float],\n) -> Resume:\n    \"\"\"Every value the room state store holds, as a start resumes it.\n\n    ``unit`` is the system's temperature unit (``celsius`` whether it is °C), ``step`` the\n    target step and ``engage_bounds`` the drift's bounds. Temperatures saved in the other\n    unit are converted, as a restored target number's are, and a target is held to its\n    head's bounds. MXZ's memory of its head writes resumes only in the unit it was kept in:\n    a remembered 70 °F is no report in °C. A fan record counts only if it is usable.\n    \"\"\"\n    resumed: set[tuple[str, str]] = set()\n    stored_switches = saved.section(SECTION_SWITCHES) or {}\n    switches: dict[str, bool] = {}\n    for key in SWITCH_KEYS:\n        if isinstance(on := stored_switches.get(key), bool):\n            switches[key] = on\n            resumed.add((\"switch\", key))\n    resumed_rooms: list[RoomResume] = []\n    for slot in rooms:\n        cid, slug = slot.climate_id, slot.slug\n        room = saved.item(SECTION_ROOMS, cid) or {}\n        target = None\n        if (value := saved_temperature(room.get(\"target\"), saved.unit, unit, step)) is not None:\n            lo, hi = slot.bounds\n            target = min(max(value, lo), hi)\n            resumed.add((\"target\", slug))\n        target_range = None\n        low = saved_temperature(room.get(\"target_low\"), saved.unit, unit, step)\n        high = saved_temperature(room.get(\"target_high\"), saved.unit, unit, step)\n        if low is not None and high is not None:\n            target_range = (low, high)\n            resumed.add((\"range\", slug))\n        has_drift, drift = False, None\n        stored_drift = room.get(\"drift\")\n        if (stored_drift is None and \"drift\" in room) or finite_number(stored_drift):\n            has_drift, drift = True, saved_drift(stored_drift, saved.unit, celsius, engage_bounds)\n            resumed.add((\"drift\", slug))\n        enable, enable_record = None, {}\n        if isinstance(on := room.get(\"enable\"), bool):\n            floor = saved.item(SECTION_FLOOR, cid) or {}\n            released = room.get(\"hands_off_released\") is True\n            enable, enable_record = on, {**floor, \"hands_off_released\": released}\n            resumed.add((\"enable\", slug))\n        fan = None\n        if (stored_fan := saved.item(SECTION_FAN, cid)) is not None and (\n            fan := FanRecord.from_dict(stored_fan)\n        ) is not None:\n            resumed.add((\"fan\", cid))\n        writes = (saved.item(SECTION_HEAD_WRITES, cid) or {}) if saved.unit == unit else {}\n        memories: dict[str, HeadWriteMemory] = {}\n        for name in HEAD_WRITE_FIELDS:\n            memory = HeadWriteMemory.restored(HEAD_WRITES_REMEMBERED, writes.get(name))\n            if memory is not None:\n                memories[name] = memory\n        resumed_rooms.append(\n            RoomResume(\n                target=target,\n                target_range=target_range,\n                has_drift=has_drift,\n                drift=drift,\n                enable=enable,\n                enable_record=enable_record,\n                fan=fan,\n                head_writes=memories,\n            )\n        )\n    return Resume(switches=switches, rooms=tuple(resumed_rooms), resumed=frozenset(resumed))\n\n\n@dataclass(frozen=True, slots=True)\nclass EnableResume:\n    \"\"\"What a resumed enable leaves: the engage latch and startup seeds, the hands-off\n    release, and the floor record ``FloorGuard.restore`` takes.\"\"\"\n\n    latch: dict[str, str]\n    startup: dict[str, str | None]\n    released: bool\n    floor: dict[str, Any]\n\n\ndef resumed_enable(\n    slug: str,\n    on: bool,\n    hands_off: bool,\n    saved: dict[str, Any],\n    latch: Mapping[str, str],\n    startup: Mapping[str, str | None],\n) -> EnableResume:\n    \"\"\"A start resumed a room's enable, and a disabled room's release and floor.\n\n    ``saved`` holds ``hands_off_released`` and the floor record (``FloorGuard.record``);\n    ``hands_off`` is whether the room is opted in now. An enabled room resumes a run its\n    head shows: it waits in ``startup`` for its head's first report (``planner.decide``\n    seeds its latch from it). A disabled one has no run. A disabled hands-off room is\n    released only if its off had landed, and a disabled room's floor run or yield comes\n    back only for a floor it still sets (``FloorGuard.restore`` checks that). The latch and\n    the seeds come in as they are and go out advanced, as copies.\n    \"\"\"\n    latch, startup = dict(latch), dict(startup)\n    if on:\n        startup[slug] = None\n    else:\n        startup.pop(slug, None)\n        latch[slug] = \"\"\n    return EnableResume(\n        latch=latch,\n        startup=startup,\n        released=not on and hands_off and saved.get(\"hands_off_released\") is True,\n        floor={} if on else saved,\n    )\n",
 "custom_components/mxz_coordinator/sim_timing.py": "\"\"\"When MXZ computes, for a simulator: MXZ's own timing on a model of Home Assistant's debouncer.\n\nStandard library only, and for a simulator only: no module of the integration imports it\n(tools/import_bounds.py ``SIMULATOR_ONLY``). The coordinator keeps Home Assistant's own request\ndebouncer and ``DataUpdateCoordinator``, and the delivery queue on top of them. This models\nthem as Home Assistant 2025.11 and later behave, with each delivery done within its compute, so\na simulator with no Home Assistant computes when the product would. MXZ's own rules come from\n``timing``: what each input and wakeup asks for, and the heartbeat.\n\nThe model, for a refresh asked for (``timing.Refresh``):\n\n- ``REQUEST`` or ``REPORT`` computes at once, unless the request cooldown is running; then it is\n  kept, and one compute runs when the cooldown ends. A compute the debouncer ran starts the\n  cooldown when it ends.\n- ``NOW`` computes at once and ends the cooldown and the request it kept; it starts none.\n- While a compute runs: a ``REPORT`` is kept for the end of a cooldown that starts then. A\n  ``REQUEST`` made while that plan's deliveries run is followed up by a compute at once after\n  it, and so is a ``NOW``; either ends the cooldown and what it kept. A ``REQUEST`` made during\n  a plan that sent nothing is asked once it ends. Timers due at the same instant all run before\n  the compute the first of them started has ended.\n- The heartbeat runs every ``timing.HEARTBEAT`` seconds from MXZ's start and asks ``REQUEST``.\n  Each wakeup runs at its due time and asks what ``timing.WAKEUPS`` says.\n\n``tests/test_sim_timing_parity.py`` checks this against the real coordinator on every supported\nrelease (``tests/timing_parity.py``); where a release differs it names the difference.\n\nA simulator calls ``start`` at MXZ's start, then ``step`` with each input (``Ask``, ``Arm``), with\n``Tick`` at ``due(timers)``, and with ``Computed`` after each compute a step asked for. A\nrestart is ``start`` again: nothing of the old timers is kept.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections.abc import Hashable, Mapping\nfrom dataclasses import dataclass, field, replace\nfrom enum import StrEnum\n\nfrom .const import STARTUP_RECOVER_DELAY\nfrom .timing import HEARTBEAT, REQUEST_COOLDOWN, WAKEUPS, Arm, CancelAll, Refresh\n\n__all__ = [\n    \"Arm\", \"Ask\", \"Beat\", \"CancelAll\", \"Computed\", \"Due\", \"Event\", \"Fire\", \"Step\", \"Tick\", \"Timers\", \"Why\",\n    \"due\", \"start\", \"step\",\n]\n\n\nclass Why(StrEnum):\n    \"\"\"Why a compute runs: the debouncer ran a request at once (``ASK``) or at the end of its\n    cooldown (``COOLDOWN``), a refresh at once (``NOW``), or the delivery queue's follow-up.\"\"\"\n\n    ASK = \"ask\"\n    COOLDOWN = \"cooldown\"\n    NOW = \"now\"\n    FOLLOWUP = \"followup\"\n\n\n@dataclass(frozen=True, slots=True)\nclass Ask:\n    \"\"\"An input asked for a refresh.\"\"\"\n\n    refresh: Refresh\n\n\n@dataclass(frozen=True, slots=True)\nclass Computed:\n    \"\"\"The compute a step asked for ran.\n\n    ``sent``: its plan queued a delivery to a head. ``asked``: what its heads' reports asked for\n    while it was applied, in order. ``armed``: the wakeups it armed or cancelled, in the order\n    the product's steps did them: each ``Arm`` among the apply's ``HeadApply.steps`` and the\n    write-back's ``ModeStamp.hold_end`` (``planner.apply_plan``, ``stamp_mode_change``), then\n    each one its deliveries' notes did (``DeliverySteps.note``), then ``timing.arms``.\n    \"\"\"\n\n    sent: bool\n    asked: tuple[Refresh, ...] = ()\n    armed: tuple[Arm | CancelAll, ...] = ()\n\n\n@dataclass(frozen=True, slots=True)\nclass Tick:\n    \"\"\"Time has come to ``now``: every timer due by then runs.\"\"\"\n\n\ntype Event = Ask | Arm | Computed | Tick\n\n\n@dataclass(frozen=True, slots=True)\nclass Fire:\n    \"\"\"A wakeup ran.\"\"\"\n\n    name: str\n    key: Hashable\n\n\n@dataclass(frozen=True, slots=True)\nclass Beat:\n    \"\"\"The heartbeat ran.\"\"\"\n\n\n@dataclass(frozen=True, slots=True)\nclass Due:\n    \"\"\"A timer: when it runs, and the order it was set in (timers due together run in it).\"\"\"\n\n    at: float\n    order: int\n\n\n@dataclass(frozen=True, slots=True)\nclass Timers:\n    \"\"\"MXZ's timers and the debouncer's, between two steps.\n\n    ``cooldown``: the end of the request cooldown, None when none runs. ``kept``: a request\n    waits for it. ``waits``: each armed wakeup by name and key. ``computing``: why the compute a\n    step asked for runs, until ``Computed``; ``during``: what was asked meanwhile.\n    \"\"\"\n\n    heartbeat: Due\n    cooldown: Due | None = None\n    kept: bool = False\n    waits: Mapping[tuple[str, Hashable], Due] = field(default_factory=dict)\n    computing: Why | None = None\n    during: tuple[Refresh, ...] = ()\n    order: int = 0\n\n\n@dataclass(frozen=True, slots=True)\nclass Step:\n    \"\"\"What one step did.\n\n    ``compute``: run one compute now, then send ``Computed``; None: nothing to run. ``ran``:\n    what ran, in order: each wakeup, the heartbeat, and the start of the compute. ``kept``: a\n    request waits for the end of the cooldown (the debounce outcome of an ask that computed\n    nothing).\n    \"\"\"\n\n    compute: Why | None = None\n    ran: tuple[Fire | Beat | Why, ...] = ()\n    kept: bool = False\n\n\ndef start(now: float) -> tuple[Timers, Step]:\n    \"\"\"MXZ starts: it computes at once, arms its startup wakeup, and its heartbeat starts.\"\"\"\n    run = _Run(Timers(heartbeat=Due(now + HEARTBEAT, 0), order=1), now)\n    run.arm(Arm(\"startup\", None, STARTUP_RECOVER_DELAY))\n    run.begin(Why.NOW)\n    return run.done()\n\n\ndef due(timers: Timers) -> float:\n    \"\"\"When the next timer runs.\"\"\"\n    return min(timer.at for timer in _timers(timers))\n\n\ndef step(timers: Timers, event: Event, now: float) -> tuple[Timers, Step]:\n    \"\"\"One input, one ``Tick``, or the end of a compute, at ``now``.\"\"\"\n    run = _Run(timers, now)\n    match event:\n        case Ask(refresh):\n            run.ask(refresh)\n        case Arm():\n            run.arm(event)\n        case Computed():\n            run.computed(event)\n        case Tick():\n            run.tick()\n    return run.done()\n\n\ndef _timers(timers: Timers) -> list[Due]:\n    return [\n        timers.heartbeat,\n        *([timers.cooldown] if timers.cooldown is not None else []),\n        *timers.waits.values(),\n    ]\n\n\nclass _Run:\n    \"\"\"One step's working copy of the timers, and what it did.\"\"\"\n\n    def __init__(self, timers: Timers, now: float) -> None:\n        self.timers = timers\n        self.now = now\n        self.waits = dict(timers.waits)\n        self.during = list(timers.during)\n        self.ran: list[Fire | Beat | Why] = []\n        self.kept = False\n        self.order = timers.order\n\n    def done(self) -> tuple[Timers, Step]:\n        timers = replace(self.timers, waits=self.waits, during=tuple(self.during), order=self.order)\n        computing = timers.computing if timers.computing in self.ran else None\n        return timers, Step(compute=computing, ran=tuple(self.ran), kept=self.kept)\n\n    def due(self, delay: float) -> Due:\n        self.order += 1\n        return Due(self.now + delay, self.order)\n\n    def set(self, **changes: object) -> None:\n        self.timers = replace(self.timers, **changes)  # type: ignore[arg-type]\n\n    def arm(self, arm: Arm | CancelAll) -> None:\n        if isinstance(arm, CancelAll):\n            for name, key in [wait for wait in self.waits if wait[0] == arm.name]:\n                del self.waits[name, key]\n            return\n        self.waits.pop((arm.name, arm.key), None)\n        if arm.delay is not None:\n            self.waits[arm.name, arm.key] = self.due(arm.delay)\n\n    def begin(self, why: Why) -> None:\n        if why in (Why.NOW, Why.FOLLOWUP):\n            self.set(cooldown=None, kept=False)\n        self.set(computing=why)\n        self.ran.append(why)\n\n    def ask(self, refresh: Refresh) -> None:\n        if self.timers.computing is not None:\n            self.during.append(refresh)\n        elif refresh is Refresh.NOW:\n            self.begin(Why.NOW)\n        elif self.timers.cooldown is not None:\n            self.set(kept=True)\n            self.kept = True\n        else:\n            self.begin(Why.ASK)\n\n    def computed(self, event: Computed) -> None:\n        why = self.timers.computing\n        if why is None:\n            raise ValueError(\"no compute is running\")\n        during = [*self.during, *event.asked]\n        self.during = []\n        self.set(computing=None)\n        debounced = why in (Why.ASK, Why.COOLDOWN)\n        if Refresh.REPORT in during:\n            self.set(kept=True)\n            if not debounced and self.timers.cooldown is None:\n                self.set(cooldown=self.due(REQUEST_COOLDOWN))\n        for arm in event.armed:\n            self.arm(arm)\n        if debounced:\n            self.set(cooldown=self.due(REQUEST_COOLDOWN))\n        if Refresh.NOW in during:\n            self.begin(Why.NOW)\n        elif Refresh.REQUEST in during:\n            if event.sent:\n                self.begin(Why.FOLLOWUP)\n            else:\n                self.ask(Refresh.REQUEST)\n\n    def tick(self) -> None:\n        if self.timers.computing is not None:\n            raise ValueError(\"a compute is running: send Computed first\")\n        timers = self.timers\n        names = {timer: name for name, timer in timers.waits.items()}\n        for timer in sorted(\n            (timer for timer in _timers(timers) if timer.at <= self.now),\n            key=lambda timer: (timer.at, timer.order),\n        ):\n            if timer is timers.heartbeat:\n                self.set(heartbeat=self.due(HEARTBEAT))\n                self.ran.append(Beat())\n                self.ask(Refresh.REQUEST)\n            elif timer is timers.cooldown:\n                kept = self.timers.kept\n                self.set(cooldown=None, kept=False)\n                if kept:\n                    self.begin(Why.COOLDOWN)\n            else:\n                name, key = names[timer]\n                del self.waits[name, key]\n                self.ran.append(Fire(name, key))\n                if (refresh := WAKEUPS.get(name)) is not None:\n                    self.ask(refresh)\n",
 "custom_components/mxz_coordinator/timing.py": "\"\"\"MXZ's own timing: what each input asks of the plan, each wakeup's delay, the heartbeat.\n\nStandard library only (tools/import_bounds.py). The coordinator and its controllers read Home\nAssistant and the clock, call these, and arm what they say on ``clock.Clock``. ``sim_timing``\nruns the same rules for a simulator, on a model of Home Assistant's request debouncer.\n\nA refresh is asked for in one of three ways (``Refresh``). A head's report asks what\n``head_refresh`` says, a room sensor's unchanged report what ``same_reading_refresh`` says, and\neach wakeup what ``WAKEUPS`` says when it runs. A room switched to or from a dual setpoint in\nplace, and MXZ's own start, refresh at once. Every other input asks ``Refresh.REQUEST``: a room\nreading that changed, a person's change to one of MXZ's controls (a room's target, range or\nenable, the shared-mode select, the Fan auto switch), a Safety or Comfort priority entity, a door\nor window, the standby hold, the ``mxz_recompute`` event and the heartbeat.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom collections.abc import Callable, Hashable, Iterable, Mapping, Sequence\nfrom dataclasses import dataclass\nfrom enum import StrEnum\nfrom typing import Any\n\nfrom .const import HEALTH_REPORT_SENSITIVE, UNAVAILABLE_STATES\nfrom .logic import CLOSED_READ, HeadSight, comfort_stale_in\n\n\nclass Refresh(StrEnum):\n    \"\"\"How an input asks for a compute.\n\n    ``REQUEST``: through the request debouncer, as new input. ``REPORT``: a head's report,\n    through the debouncer, never as new input (``DeliveryQueue.request_for_report``). ``NOW``: at\n    once, past the request cooldown (``async_refresh_now``).\n    \"\"\"\n\n    REQUEST = \"request\"\n    REPORT = \"report\"\n    NOW = \"now\"\n\n\n@dataclass(frozen=True, slots=True)\nclass Arm:\n    \"\"\"A wakeup armed ``delay`` seconds from now, in place of the one of this name and key;\n    a delay of None cancels it.\"\"\"\n\n    name: str\n    key: Hashable\n    delay: float | None\n\n\n@dataclass(frozen=True, slots=True)\nclass CancelAll:\n    \"\"\"Every wakeup of this name cancelled, whatever its key.\"\"\"\n\n    name: str\n\n\n# Seconds the request debouncer waits after a refresh it ran before it runs another.\nREQUEST_COOLDOWN = 10\n# Seconds between two heartbeats: a refresh even when nothing reports.\nHEARTBEAT = 900\n# A run that coasts to its target is looked at again just after the cooldown it may have started.\nCOAST_FOLLOWUP_DELAY = REQUEST_COOLDOWN + 1\n\n# What each wakeup asks for when it runs. None asks nothing by itself: the end of the\n# mode-change hold only redraws the entities, and a heal or adopt hold judges first.\nWAKEUPS: Mapping[str, Refresh | None] = {\n    \"fresh\": Refresh.REQUEST,\n    \"dwell\": Refresh.REQUEST,\n    \"coast\": Refresh.REQUEST,\n    \"dry\": Refresh.REQUEST,\n    \"lost\": Refresh.REQUEST,\n    \"comfort\": Refresh.REQUEST,\n    \"cloud\": Refresh.REQUEST,\n    \"startup\": Refresh.REQUEST,\n    \"dry_pick\": Refresh.REQUEST,\n    \"settle\": Refresh.NOW,\n    \"opening\": Refresh.NOW,\n    \"hold_end\": None,\n    \"heal\": None,\n}\n\n\ndef startup_quiet(*, running: bool, startup_ran: bool) -> bool:\n    \"\"\"Whether MXZ's start is still quiet: it was set up before Home Assistant was running\n    (``running`` False), and its ``startup`` wakeup, ``STARTUP_RECOVER_DELAY`` after Home\n    Assistant started, has not run yet (``startup_ran``; ``sim_timing.start`` arms it). While\n    quiet, a change at a head is not adopted (``planner.AdoptGates.starting``) and a room sensor\n    with no usable reading waits to warn. A reload while Home Assistant runs is never quiet.\"\"\"\n    return not running and not startup_ran\n\n\ndef head_refresh(*, run_changed: bool, moved: bool) -> Refresh | None:\n    \"\"\"What a head's report asks for.\n\n    ``run_changed``: the head of a released room that votes by its run started or stopped one\n    (``run_changed``); that counts at once, not after a cooldown. ``moved``: the report showed\n    something the plan reads (``head_shows_new``, or a change one of the head's rules waits for).\n    \"\"\"\n    if run_changed:\n        return Refresh.NOW\n    return Refresh.REPORT if moved else None\n\n\ndef run_changed(old_mode: str, new_mode: str, old_action: Any, new_action: Any) -> bool:\n    \"\"\"Whether a head's report starts or stops a run: its mode or its action changed.\"\"\"\n    return new_mode != old_mode or new_action != old_action\n\n\ndef head_shows_new(\n    old_mode: str | None, new_mode: str | None,\n    old_attributes: Mapping[str, Any], new_attributes: Mapping[str, Any],\n) -> bool:\n    \"\"\"Whether a head's report changed its fan, its fan list or features, or its availability.\n\n    A mode of None is no state at all, with no attributes.\n    \"\"\"\n    capabilities_changed = any(\n        type(new_attributes.get(key)) is not type(old_attributes.get(key))\n        or new_attributes.get(key) != old_attributes.get(key)\n        for key in (\"fan_modes\", \"supported_features\")\n    )\n    availability_changed = (new_mode is None or new_mode in UNAVAILABLE_STATES) != (\n        old_mode is None or old_mode in UNAVAILABLE_STATES\n    )\n    return (\n        new_attributes.get(\"fan_mode\") != old_attributes.get(\"fan_mode\")\n        or capabilities_changed\n        or availability_changed\n    )\n\n\ndef same_reading_refresh(healths: Iterable[str | None]) -> Refresh | None:\n    \"\"\"What a room sensor's report of an unchanged value asks for, by the health of each room\n    it serves: only a room waiting for a report (stale, invalid, or in its startup grace) asks.\"\"\"\n    return Refresh.REQUEST if any(health in HEALTH_REPORT_SENSITIVE for health in healths) else None\n\n\ndef nearest(waits: Iterable[float | None]) -> float | None:\n    \"\"\"The soonest of these waits, None for none: one wakeup serves them all.\"\"\"\n    found = [wait for wait in waits if wait is not None]\n    return min(found) if found else None\n\n\ndef fresh_delay(deadlines: Iterable[float], now: float) -> float | None:\n    \"\"\"The fresh wakeup: at the nearest sensor freshness deadline (wall clock), none without one.\n\n    The deadline itself, with nothing added: the refresh it runs reads the room as stale.\n    \"\"\"\n    soonest = nearest(deadlines)\n    return None if soonest is None else max(soonest - now, 0.0)\n\n\ndef dwell_delay(\n    remaining: float, *, active: bool, allowed: bool, held_back: Callable[[], bool]\n) -> float | None:\n    \"\"\"The dwell wakeup: when the mode-change hold ends, while it holds a change back.\n\n    ``remaining``: seconds the hold has left (-inf with no change on record, 0 or less once it\n    ended). ``active``: the coordinator is on, not retired, and no standby hold parks every\n    head. ``allowed``: the plan just decided had the hold open. ``held_back``: whether the hold\n    is what keeps the plan from another mode (``planner.held_back``), read only when it matters.\n    A hold that ended while the plan was applied wakes at once.\n    \"\"\"\n    if not active:\n        return None\n    if remaining <= 0 and allowed:\n        return None\n    if not held_back():\n        return None\n    return remaining + 1 if remaining > 0 else 0\n\n\ndef coast_delay(coasted: bool, *, active: bool) -> float | None:\n    \"\"\"The coast wakeup: a compute just after a run coasted, while the coordinator can act.\"\"\"\n    return COAST_FOLLOWUP_DELAY if active and coasted else None\n\n\ndef coil_dry_delay(left: float) -> float:\n    \"\"\"The coil-dry wakeup: just after a parked head's coil-dry run ends (``planner.idle_park``).\"\"\"\n    return left + 1\n\n\ndef cloud_delay(waits: Iterable[float]) -> float | None:\n    \"\"\"The cloud wakeup: the nearest cloud head deadline still ahead.\"\"\"\n    return nearest(wait for wait in waits if wait > 0)\n\n\ndef opening_wait(reading: str, *, open_delay: float, close_delay: float) -> float:\n    \"\"\"A door or window's new reading: its room's wakeup is at the end of this delay.\"\"\"\n    return close_delay if reading == CLOSED_READ else open_delay\n\n\ndef opening_delay(delay: float) -> float:\n    \"\"\"A door/window wakeup: at the end of the room's delay, at once for one already over.\"\"\"\n    return max(0.0, delay)\n\n\ndef hold_end_delay(remaining: float) -> float | None:\n    \"\"\"The hold-end wakeup: just after the mode-change hold ends, none with no hold left.\"\"\"\n    return remaining + 1 if remaining > 0 else None\n\n\ndef hold_end_arm(remaining: float, *, retired: bool) -> Arm:\n    \"\"\"The hold-end wakeup for a mode-change hold with ``remaining`` seconds left; a retired\n    coordinator cancels it.\"\"\"\n    return Arm(\"hold_end\", None, None if retired else hold_end_delay(remaining))\n\n\n@dataclass(frozen=True, slots=True)\nclass Watched:\n    \"\"\"A room's head as the lost and settle wakeups read it.\n\n    ``by_action``: a hands-off room whose vote follows its head's run. ``released``: its\n    hands-off phase is released.\n    \"\"\"\n\n    sight: HeadSight\n    by_action: bool\n    released: bool\n\n\n@dataclass(frozen=True, slots=True)\nclass CloudWaits:\n    \"\"\"A cloud head's deadlines as its record holds them.\n\n    ``pending``: its confirm window is open, until ``window_until``. ``release_at``: when a\n    batch or fan step its limit held back may go. ``seen``: when it last showed it is there\n    (wall clock) and the limit after which it is out of MXZ's control (None for none); not\n    read for a head already out (``unresponsive``).\n    \"\"\"\n\n    pending: bool\n    window_until: float\n    release_at: float | None\n    unresponsive: bool\n    seen: tuple[float, int | None] | None\n\n\ndef cloud_arm(\n    retired: bool, clouds: Sequence[CloudWaits], clock: float, wall: float\n) -> Arm:\n    \"\"\"The one wakeup the cloud heads share: at the nearest deadline still ahead.\n\n    The end of a confirm window (confirm, or send again), a batch or fan step held back by\n    its limit, and the moment a quiet head would become not controllable. None for a retired\n    coordinator or no cloud head.\n    \"\"\"\n    if retired or not clouds:\n        return Arm(\"cloud\", None, None)\n    waits: list[float] = []\n    for cloud in clouds:\n        if cloud.pending:\n            waits.append(cloud.window_until - clock)\n        if cloud.release_at is not None and cloud.release_at > clock:\n            waits.append(cloud.release_at - clock)\n        if not cloud.unresponsive and cloud.seen is not None:\n            since, limit = cloud.seen\n            if limit is not None:\n                waits.append(since + limit - wall)\n    return Arm(\"cloud\", None, cloud_delay(waits))\n\n\n@dataclass(frozen=True, slots=True)\nclass Wakeups:\n    \"\"\"What the wakeups armed after a compute read.\n\n    ``retired``: this coordinator is retired; ``clock_retired``: its clock is too (a unit\n    switch retires the coordinator and reloads it, with the clock still running).\n    ``coordinator`` and ``standby``: the Coordinator switch is on, and a standby hold parks\n    every head at one fixed mode. ``clock`` and ``wall``: MXZ's clock and the wall clock, read\n    once. ``remaining``, ``allowed`` and ``held_back``: what :func:`dwell_delay` reads.\n    ``coasted``: a room let go of a run. ``fresh``: each room's freshness deadline (wall\n    clock). ``sights``: every head's record; ``rooms``: each room's, as the lost and settle\n    wakeups read it; ``lost_ttl`` and ``action_hold``: how long a lost head's vote lasts and\n    a stopped head's vote is held. ``comfort_stale_after`` and ``comfort``: when an \"on\"\n    Comfort priority goes stale (None: never), and each room's entity (domain, state, age).\n    ``clouds``: each cloud head's deadlines. ``openings``: each door/window room's slug and\n    the end of its delay (wall clock; None with no delay running).\n    \"\"\"\n\n    retired: bool\n    clock_retired: bool\n    coordinator: bool\n    standby: bool\n    clock: float\n    wall: float\n    remaining: float\n    allowed: bool\n    held_back: Callable[[], bool]\n    coasted: bool\n    fresh: Sequence[float]\n    sights: Sequence[HeadSight]\n    rooms: Sequence[Watched]\n    lost_ttl: float\n    action_hold: float\n    comfort_stale_after: float | None\n    comfort: Sequence[tuple[str | None, str | None, float | None]]\n    clouds: Sequence[CloudWaits]\n    openings: Sequence[tuple[str, float | None]]\n\n\ndef arms(w: Wakeups) -> tuple[Arm | CancelAll, ...]:\n    \"\"\"Every wakeup a compute leaves armed or cancels, in the order the coordinator arms them.\n\n    Each keeps exactly one wait for what it watches, re-armed from this compute's readings,\n    so it moves when a reading moves it and goes when nothing is left to wait for. Nothing is\n    captured: each wakeup only asks for what ``WAKEUPS`` says, which re-reads everything.\n\n    - ``dwell``: a flip the mode-change hold holds back (:func:`dwell_delay`), while the\n      coordinator is on, its clock not retired, and no fixed standby park holds.\n    - ``coast``: just after a room coasts, while the coordinator is on and not parked.\n    - ``fresh``: the nearest sensor freshness deadline.\n    - ``lost``: the nearest lost-vote expiry, and the nearest end of a stopped head's held\n      vote in a hands-off room that votes by its run.\n    - ``settle``: the nearest end of a settle window of a released hands-off head that votes\n      by its run; none once retired.\n    - ``comfort``: the moment the nearest \"on\" Comfort priority goes stale; none once retired\n      or with no stale time set.\n    - ``cloud``: :func:`cloud_arm`.\n    - ``opening``: every room's cancelled, then, unless retired, one at the end of each\n      room's open or close delay.\n    \"\"\"\n    out: list[Arm | CancelAll] = [\n        Arm(\"dwell\", None, dwell_delay(\n            w.remaining,\n            active=not (w.clock_retired or not w.coordinator or w.standby),\n            allowed=w.allowed,\n            held_back=w.held_back,\n        )),\n        Arm(\"coast\", None, coast_delay(w.coasted, active=w.coordinator and not w.standby)),\n        Arm(\"fresh\", None, fresh_delay(w.fresh, w.wall)),\n        # The boundary itself, as for freshness: expiry is half-open, so the refresh this\n        # runs reads the vote as expired.\n        Arm(\"lost\", None, nearest([\n            *(sight.expires_in(w.clock, w.lost_ttl) for sight in w.sights),\n            *(room.sight.hold_ends_in(w.clock, w.action_hold) for room in w.rooms if room.by_action),\n        ])),\n        Arm(\"settle\", None, None if w.retired else nearest(\n            room.sight.settles_in(w.clock) for room in w.rooms if room.by_action and room.released\n        )),\n        Arm(\"comfort\", None, None if w.retired or w.comfort_stale_after is None else nearest(\n            comfort_stale_in(domain, state, age=age, stale_after=w.comfort_stale_after)\n            for domain, state, age in w.comfort\n        )),\n        cloud_arm(w.retired, w.clouds, w.clock, w.wall),\n        CancelAll(\"opening\"),\n    ]\n    if not w.retired:\n        out.extend(\n            Arm(\"opening\", slug, opening_delay(due - w.wall))\n            for slug, due in w.openings if due is not None\n        )\n    return tuple(out)\n",
 "custom_components/mxz_coordinator/units.py": "\"\"\"Temperature units: how a saved value follows a °F/°C switch, and the rounding it uses.\n\nNo Home Assistant dependency, so the math is tested directly.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport math\n\n# Home Assistant's UnitOfTemperature values, as a set drive offset's unit is\n# stored (ZONE_DRIVE_OFFSET_UNIT).\nUNIT_C = \"°C\"\nUNIT_F = \"°F\"\n\n\ndef offset_in_unit(value: float, set_in: object, celsius: bool) -> float:\n    \"\"\"A drive offset set in ``set_in`` (°C or °F), in the system unit.\n\n    An offset is a difference, so it scales by 5/9 or 9/5 with no 32° shift:\n    3 °F is 1.67 °C. To two places, as the room page shows it. Any other\n    ``set_in`` (none stored: an offset saved before its unit was) is taken to\n    be in the system unit already, and so is returned unchanged.\n    \"\"\"\n    if set_in == UNIT_F and celsius:\n        return round(value * 5 / 9, 2)\n    if set_in == UNIT_C and not celsius:\n        return round(value * 9 / 5, 2)\n    return value\n\n\ndef target_in_unit(value: float, set_in: object, unit: str, step: float) -> float:\n    \"\"\"An absolute temperature set in ``set_in`` (°C or °F), in ``unit``, on ``step``.\n\n    59 °F is 15 °C. Anything else ``set_in`` can be (the same unit, none stored)\n    leaves the value as it is, so a value converted once is never converted again.\n    \"\"\"\n    if set_in == UNIT_F and unit == UNIT_C:\n        return snap_to_step((value - 32) * 5 / 9, step)\n    if set_in == UNIT_C and unit == UNIT_F:\n        return snap_to_step(value * 9 / 5 + 32, step)\n    return value\n\n\ndef snap_to_step(value: float, step: float) -> float:\n    \"\"\"``value`` on the nearest multiple of ``step``, half up.\n\n    Half up, as the CN105 path reads a head's grid (``grid.Grid.already_at``):\n    Python's round() is half to even. No usable step leaves it unchanged.\n    \"\"\"\n    if not step > 0 or not math.isfinite(step):\n        return value\n    return math.floor(value / step + 0.5) * step\n\n\ndef clamp(value: float, band: tuple[float, float] | None) -> float:\n    \"\"\"``value`` inside ``band`` (low, high); unchanged with no band.\"\"\"\n    if band is None:\n        return value\n    low, high = band\n    return min(max(value, low), high)\n",
 "invented_house/__init__.py": "\"\"\"The simulator's stand-in for invented_house/__init__.py, which sets up Home Assistant.\n\nThe page loads only model.py and devices.py (tools/simulator_bundle.py).\"\"\"\n",
 "invented_house/model.py": "\"\"\"The demo's outdoor unit and rooms: three invented rules, and no more.\n\nOff unless a journey turns it on (feature map section 6), so the proof journeys\nkeep setting exact temperatures. With it on, every room temperature after the\nstart follows from what the heads were told:\n\n1. One outdoor unit runs one direction. A head set to the other direction waits\n   in standby until no head is set to the running direction. This is the rule\n   Mitsubishi's manual states for heads on one outdoor unit: \"the unit selected\n   last goes into standby mode.\"\n2. A head in the running direction moves its room toward its setpoint at a fixed\n   rate, then idles in its mode. Heat uses the low setpoint, cool the high one.\n3. A room no head is moving drifts toward a fixed ambient at a slower fixed rate.\n\nIt measures nothing: the rates are invented, the fan does not change them, and\nnothing here is a model of real equipment. No Home Assistant import: the\nverification suite tests this module directly.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import TYPE_CHECKING\n\nif TYPE_CHECKING:\n    from .devices import Devices, Head, Room\n\nHEAT = \"heat\"\nCOOL = \"cool\"\nDIRECTIONS = (HEAT, COOL)\n\n\n@dataclass(frozen=True)\nclass Climate:\n    \"\"\"The invented numbers, from house.json.\"\"\"\n\n    ambient: float\n    run_rate: float  # degrees per minute a running head moves its room\n    drift_rate: float  # degrees per minute an unattended room moves toward ambient\n    tick: float  # seconds between steps\n\n\ndef direction(devices: Devices, running: str | None) -> str | None:\n    \"\"\"Rule 1: the direction the outdoor unit runs after the heads' latest change.\n\n    It keeps its direction while any head is set to it. Otherwise it takes the\n    direction of the first head, in house order, set to heat or cool.\n    \"\"\"\n    asked = [head.hvac_mode for head in devices.heads.values() if head.available and head.hvac_mode in DIRECTIONS]\n    if running in asked:\n        return running\n    return asked[0] if asked else None\n\n\ndef setpoint(head: Head) -> float | None:\n    \"\"\"The setpoint a head runs to in its mode: the low one in heat, the high one in cool.\"\"\"\n    if head.hvac_mode == HEAT:\n        return head.target_temp_low\n    if head.hvac_mode == COOL:\n        return head.target_temp_high\n    return None\n\n\ndef action(head: Head, room: Room, running: str | None) -> str:\n    \"\"\"What a head is doing: off, fan, standby, heating, cooling or idle.\"\"\"\n    if head.hvac_mode == \"off\" or not head.available:\n        return \"off\"\n    if head.hvac_mode not in DIRECTIONS:\n        return \"fan\"\n    if head.hvac_mode != running:\n        return \"standby\"\n    target = setpoint(head)\n    if target is not None and head.hvac_mode == HEAT and room.temperature < target:\n        return \"heating\"\n    if target is not None and head.hvac_mode == COOL and room.temperature > target:\n        return \"cooling\"\n    return \"idle\"\n\n\ndef _toward(value: float, goal: float, most: float) -> float:\n    return goal if abs(goal - value) <= most else value + most * (1 if goal > value else -1)\n\n\ndef step(devices: Devices, climate: Climate, minutes: float) -> None:\n    \"\"\"Move every room ``minutes`` forward under rules 2 and 3, after rule 1.\"\"\"\n    devices.outdoor = direction(devices, devices.outdoor)\n    for key, room in devices.rooms.items():\n        head = devices.heads[key]\n        target = setpoint(head)\n        if target is not None and action(head, room, devices.outdoor) in (\"heating\", \"cooling\"):\n            room.temperature = _toward(room.temperature, target, climate.run_rate * minutes)\n        else:\n            room.temperature = _toward(room.temperature, climate.ambient, climate.drift_rate * minutes)\n        room.temperature = round(room.temperature, 3)\n",
 "invented_house/devices.py": "\"\"\"What each invented device holds, kept in a file that outlives Home Assistant.\n\nA real head keeps its mode, setpoints and fan while Home Assistant is down, so\nevery change is written at once and read back at start. No Home Assistant\nimport: the verification suite tests this module directly.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport os\nfrom dataclasses import asdict, dataclass, field\nfrom pathlib import Path\nfrom typing import Any\n\nHOUSE = Path(__file__).with_name(\"house.json\")\nDEVICE_FILE = \"invented_house.json\"\n\n\n@dataclass\nclass Head:\n    hvac_mode: str = \"off\"\n    target_temp_low: float | None = None\n    target_temp_high: float | None = None\n    fan_mode: str = \"auto\"\n    available: bool = True\n\n\n@dataclass\nclass Room:\n    temperature: float\n    window_open: bool = False\n    occupied: bool = False\n\n\n@dataclass\nclass Devices:\n    heads: dict[str, Head] = field(default_factory=dict)\n    rooms: dict[str, Room] = field(default_factory=dict)\n    outdoor: str | None = None  # the outdoor unit's direction, kept only while the demo model runs\n\n    @classmethod\n    def fresh(cls, house: dict[str, Any]) -> Devices:\n        return cls(\n            heads={room[\"key\"]: Head() for room in house[\"rooms\"]},\n            rooms={room[\"key\"]: Room(float(room[\"temperature\"])) for room in house[\"rooms\"]},\n        )\n\n    @classmethod\n    def load(cls, path: Path, house: dict[str, Any]) -> Devices:\n        \"\"\"The stored devices, or the house's starting state when none is stored.\"\"\"\n        devices = cls.fresh(house)\n        if not path.exists():\n            return devices\n        stored = json.loads(path.read_text())\n        for key, head in stored[\"heads\"].items():\n            devices.heads[key] = Head(**head)\n        for key, room in stored[\"rooms\"].items():\n            devices.rooms[key] = Room(**room)\n        devices.outdoor = stored.get(\"outdoor\")\n        return devices\n\n    def save(self, path: Path) -> None:\n        \"\"\"Replace the file in one rename, so a kill never leaves half a file.\"\"\"\n        scratch = path.with_suffix(\".tmp\")\n        scratch.write_text(json.dumps(asdict(self), indent=2, sort_keys=True) + \"\\n\")\n        os.replace(scratch, path)\n\n\ndef reading(temperature: float) -> float:\n    \"\"\"What a room sensor reports: the room's temperature to a tenth of a degree.\n\n    The model keeps thousandths, so a room it holds at a setpoint alternates\n    between, say, 70.000 and 70.004 every tick. A real sensor never shows that,\n    and MXZ, which evaluates a room at most once per its 10 s refresh cooldown,\n    can then see only the 70.004 readings and never the one at target.\n    \"\"\"\n    return round(temperature, 1)\n\n\ndef load_house(path: Path = HOUSE) -> dict[str, Any]:\n    return json.loads(path.read_text())\n",
 "invented_house/house.json": "{\n  \"site\": {\n    \"name\": \"Invented house\",\n    \"latitude\": 0.0,\n    \"longitude\": 0.0,\n    \"elevation\": 0,\n    \"time_zone\": \"UTC\",\n    \"country\": \"US\",\n    \"currency\": \"USD\",\n    \"unit_system\": \"us_customary\"\n  },\n  \"rooms\": [\n    {\"key\": \"studio\", \"name\": \"Studio\", \"temperature\": 70},\n    {\"key\": \"loft\", \"name\": \"Loft\", \"temperature\": 70},\n    {\"key\": \"den\", \"name\": \"Den\", \"temperature\": 70}\n  ],\n  \"head\": {\n    \"hvac_modes\": [\"off\", \"cool\", \"heat\", \"fan_only\"],\n    \"fan_modes\": [\"auto\", \"quiet\", \"low\", \"medium\", \"middle\", \"high\"],\n    \"min_temp\": 59,\n    \"max_temp\": 88\n  },\n  \"climate\": {\n    \"ambient\": 76,\n    \"run_rate\": 1.0,\n    \"drift_rate\": 0.05,\n    \"tick\": 5\n  }\n}\n"
};
